window.DOC_LIBRARY = {"texts":[{"id":"h1-01","level":1,"title":"米饭在哪儿？","title_vi":"Mễ Phạn đâu rồi?","topic":"gia đình","chars":191,"paragraphs":["我叫小月，今年八岁。我家有一个小猫，名字叫“米饭”。米饭很小，很漂亮。我很爱米饭，我们是好朋友。","昨天下午，我回家的时候，没看见米饭。我叫：“米饭！米饭！你在哪儿？”没有猫来。","我看了桌子下，看了椅子后面，看了电视后面，都没有米饭。我很不高兴，打电话说：“喂，妈妈，米饭不在家！”","妈妈说：“没关系，你去看看我的衣服。”我去看妈妈的衣服，米饭在衣服里睡觉呢！","六点，妈妈回家了。我说：“妈妈，你不在家，怎么会说‘看衣服’？”妈妈说：“小月，你小的时候，很喜欢在妈妈的衣服里睡觉。米饭和你都喜欢妈妈！”"],"pinyin":["wǒ jiào xiǎo yuè jīn nián bā suì wǒ jiā yǒu yí gè xiǎo māo míng zi jiào mǐ fàn mǐ fàn hěn xiǎo hěn piào liang wǒ hěn ài mǐ fàn wǒ men shì hǎo péng you","zuó tiān xià wǔ wǒ huí jiā de shí hou méi kàn jiàn mǐ fàn wǒ jiào mǐ fàn mǐ fàn nǐ zài nǎ ér méi yǒu māo lái","wǒ kàn le zhuō zi xià kàn le yǐ zi hòu miàn kàn le diàn shì hòu miàn dōu méi yǒu mǐ fàn wǒ hěn bù gāo xìng dǎ diàn huà shuō wèi mā ma mǐ fàn bù zài jiā","mā ma shuō méi guān xì nǐ qù kàn kàn wǒ de yī fu wǒ qù kàn mā ma de yī fu mǐ fàn zài yī fu lǐ shuì jiào ne","liù diǎn mā ma huí jiā le wǒ shuō mā ma nǐ bù zài jiā zěn me huì shuō kàn yī fu mā ma shuō xiǎo yuè nǐ xiǎo de shí hou hěn xǐ huan zài mā ma de yī fu lǐ shuì jiào mǐ fàn hé nǐ dōu xǐ huan mā ma"],"translations":["Mình tên là Tiểu Nguyệt, năm nay tám tuổi. Nhà mình có một chú mèo nhỏ tên là “Mễ Phạn” (Cơm). Mễ Phạn nhỏ xíu, rất xinh. Mình rất yêu Mễ Phạn, tụi mình là bạn thân.","Chiều hôm qua, lúc về đến nhà, mình không thấy Mễ Phạn đâu. Mình gọi: “Mễ Phạn! Mễ Phạn! Em ở đâu?” Chẳng có con mèo nào chạy ra cả.","Mình tìm dưới gầm bàn, tìm sau ghế, tìm sau ti vi, đều không có Mễ Phạn. Mình buồn lắm, gọi điện thoại: “Alo, mẹ ơi, Mễ Phạn không có ở nhà!”","Mẹ nói: “Không sao đâu, con đi xem quần áo của mẹ xem.” Mình đi xem đống quần áo của mẹ, hóa ra Mễ Phạn đang ngủ trong đó!","Sáu giờ, mẹ về nhà. Mình hỏi: “Mẹ ơi, mẹ đâu có ở nhà, sao mẹ lại bảo ‘xem quần áo’?” Mẹ nói: “Tiểu Nguyệt à, hồi con còn bé, con rất thích ngủ trong đống quần áo của mẹ. Mễ Phạn với con đều mê mẹ cả!”"],"questions":[{"q":"“米饭”是什么？","q_vi":"“Mễ Phạn” là gì?","options":["一个人","一个小猫","一个小狗","一本书"],"answer":1,"explain_vi":"Đoạn 1: “我家有一个小猫，名字叫‘米饭’” – Mễ Phạn là tên chú mèo."},{"q":"米饭在哪儿睡觉？","q_vi":"Mễ Phạn ngủ ở đâu?","options":["桌子下","电视后面","椅子上","妈妈的衣服里"],"answer":3,"explain_vi":"Đoạn 4: “米饭在衣服里睡觉呢” – nó ngủ trong quần áo của mẹ."},{"q":"妈妈为什么会想到衣服？","q_vi":"Vì sao mẹ lại nghĩ đến chỗ quần áo?","options":["她上午在家看见了米饭","米饭喜欢吃衣服","小月小的时候也喜欢在那里睡觉","小月打电话说了"],"answer":2,"explain_vi":"Đoạn 5: mẹ nói hồi nhỏ Tiểu Nguyệt cũng thích ngủ trong quần áo của mẹ, nên mẹ đoán mèo cũng vậy."}],"beyond":[]},{"id":"h1-02","level":1,"title":"下雨天的出租车","title_vi":"Chiếc taxi ngày mưa","topic":"đời sống","chars":197,"paragraphs":["星期一上午，北京下雨了。王老师今年六十岁，他想去火车站，坐十点的火车回家。","王先生在学校前面看见一个出租车。他坐上车，说：“你好，请去火车站。”","开车的先生说：“您在哪里工作？”王先生说：“我在前面那个学校工作，我是汉语老师。”先生说：“汉语老师？我小的时候，很喜欢我的汉语老师。他的字很漂亮。”","二十分钟后，火车站在前面了。王先生说：“多少钱？”先生说：“我不能要您的钱。”","王先生不认识他：“你是……？”先生说：“王老师，我是李小明！二十年前，我是您的学生。您的字，我现在都会写！”王先生很高兴：“小明，谢谢你！”"],"pinyin":["xīng qī yī shàng wǔ běi jīng xià yǔ le wáng lǎo shī jīn nián liù shí suì tā xiǎng qù huǒ chē zhàn zuò shí diǎn de huǒ chē huí jiā","wáng xiān sheng zài xué xiào qián miàn kàn jiàn yí gè chū zū chē tā zuò shàng chē shuō nǐ hǎo qǐng qù huǒ chē zhàn","kāi chē de xiān sheng shuō nín zài nǎ lǐ gōng zuò wáng xiān sheng shuō wǒ zài qián miàn nà ge xué xiào gōng zuò wǒ shì hàn yǔ lǎo shī xiān sheng shuō hàn yǔ lǎo shī wǒ xiǎo de shí hou hěn xǐ huan wǒ de hàn yǔ lǎo shī tā de zì hěn piào liang","èr shí fēn zhōng hòu huǒ chē zhàn zài qián miàn le wáng xiān sheng shuō duō shǎo qián xiān sheng shuō wǒ bù néng yào nín de qián","wáng xiān sheng bù rèn shi tā nǐ shì xiān sheng shuō wáng lǎo shī wǒ shì lǐ xiǎo míng èr shí nián qián wǒ shì nín de xué sheng nín de zì wǒ xiàn zài dū huì xiě wáng xiān sheng hěn gāo xìng xiǎo míng xiè xiè nǐ"],"translations":["Sáng thứ Hai, Bắc Kinh đổ mưa. Thầy Vương năm nay sáu mươi tuổi, thầy muốn ra ga tàu, đi chuyến tàu mười giờ để về nhà.","Trước cổng trường, ông Vương thấy một chiếc taxi. Ông lên xe và nói: “Chào anh, cho tôi ra ga tàu.”","Người lái xe hỏi: “Bác làm việc ở đâu ạ?” Ông Vương đáp: “Tôi dạy ở ngôi trường đằng kia, tôi là giáo viên tiếng Hán.” Anh ta nói: “Giáo viên tiếng Hán ạ? Hồi nhỏ cháu rất quý thầy dạy tiếng Hán của cháu. Chữ thầy viết đẹp lắm.”","Hai mươi phút sau, ga tàu đã ở ngay phía trước. Ông Vương hỏi: “Bao nhiêu tiền vậy?” Anh ta nói: “Cháu không thể lấy tiền của bác được.”","Ông Vương không nhận ra anh: “Anh là…?” Anh ta nói: “Thầy Vương, em là Lý Tiểu Minh đây! Hai mươi năm trước, em là học trò của thầy. Những chữ thầy dạy, giờ em đều viết được hết!” Ông Vương vui lắm: “Tiểu Minh, cảm ơn em!”"],"questions":[{"q":"王先生想去哪儿？","q_vi":"Ông Vương muốn đi đâu?","options":["学校","医院","火车站","商店"],"answer":2,"explain_vi":"Đoạn 1: “他想去火车站” – ông muốn ra ga tàu."},{"q":"开出租车的先生是谁？","q_vi":"Người lái taxi là ai?","options":["王先生二十年前的学生","王先生的儿子","一个医生","王先生的同学"],"answer":0,"explain_vi":"Đoạn 5: “二十年前，我是您的学生” – anh là học trò cũ của ông Vương."},{"q":"开车的先生为什么不要钱？","q_vi":"Vì sao người lái xe không lấy tiền?","options":["他不喜欢钱","王先生没有钱","火车站不远","王先生是他的老师"],"answer":3,"explain_vi":"Anh nhận ra ông Vương là thầy giáo cũ của mình nên không lấy tiền để cảm ơn thầy."}],"beyond":[]},{"id":"h1-03","level":1,"title":"四个苹果","title_vi":"Bốn quả táo","topic":"mua sắm","chars":194,"paragraphs":["星期六上午，妈妈说：“小丽，这里有十块钱，你去商店买些水果，好吗？”","我家前面有一个水果商店。我去了那里，看见很多水果。我问：“小姐，苹果多少钱一个？”小姐说：“三块。”","我想：我家有爸爸、妈妈、我，和小狗点点。点点很爱吃苹果，我想买四个苹果。四个苹果是十二块，我的钱太少了。","我说：“对不起，我买三个。”小姐问：“你家有几个人？”我说：“三个人和一个小狗。”小姐听了，说：“这个苹果是小狗的，不要钱！”","中午，我们一家人坐在桌子前面吃苹果。点点吃了一个大苹果，很高兴。妈妈说：“小丽，谢谢你！你是一个好女儿。”"],"pinyin":["xīng qī liù shàng wǔ mā ma shuō xiǎo lì zhè lǐ yǒu shí kuài qián nǐ qù shāng diàn mǎi xiē shuǐ guǒ hǎo ma","wǒ jiā qián miàn yǒu yí gè shuǐ guǒ shāng diàn wǒ qù le nà lǐ kàn jiàn hěn duō shuǐ guǒ wǒ wèn xiǎo jiě píng guǒ duō shǎo qián yí gè xiǎo jiě shuō sān kuài","wǒ xiǎng wǒ jiā yǒu bà ba mā ma wǒ hé xiǎo gǒu diǎn diǎn diǎn diǎn hěn ài chī píng guǒ wǒ xiǎng mǎi sì gè píng guǒ sì gè píng guǒ shì shí èr kuài wǒ de qián tài shǎo le","wǒ shuō duì bù qǐ wǒ mǎi sān gè xiǎo jiě wèn nǐ jiā yǒu jǐ gè rén wǒ shuō sān gè rén hé yí gè xiǎo gǒu xiǎo jiě tīng le shuō zhè ge píng guǒ shì xiǎo gǒu de bú yào qián","zhōng wǔ wǒ men yī jiā rén zuò zài zhuō zi qián miàn chī píng guǒ diǎn diǎn chī le yí gè dà píng guǒ hěn gāo xìng mā ma shuō xiǎo lì xiè xiè nǐ nǐ shì yí gè hǎo nǚ ér"],"translations":["Sáng thứ Bảy, mẹ nói: “Tiểu Lệ, đây là mười đồng, con ra cửa hàng mua ít trái cây nhé?”","Trước nhà mình có một cửa hàng trái cây. Mình đến đó, thấy rất nhiều trái cây. Mình hỏi: “Chị ơi, táo bao nhiêu tiền một quả ạ?” Chị bán hàng nói: “Ba đồng.”","Mình nghĩ: nhà mình có bố, mẹ, mình và chú chó Điểm Điểm. Điểm Điểm rất thích ăn táo, nên mình muốn mua bốn quả. Bốn quả táo là mười hai đồng, tiền của mình ít quá.","Mình nói: “Xin lỗi chị, em mua ba quả thôi ạ.” Chị hỏi: “Nhà em có mấy người?” Mình đáp: “Ba người và một chú chó ạ.” Chị nghe xong thì nói: “Quả táo này là của chú chó, không lấy tiền!”","Buổi trưa, cả nhà mình ngồi quanh bàn ăn táo. Điểm Điểm ăn hết một quả táo to, vui lắm. Mẹ nói: “Tiểu Lệ, cảm ơn con! Con là một đứa con gái ngoan.”"],"questions":[{"q":"苹果多少钱一个？","q_vi":"Táo bao nhiêu tiền một quả?","options":["两块","三块","四块","十块"],"answer":1,"explain_vi":"Đoạn 2: chị bán hàng nói “三块” – ba đồng một quả."},{"q":"小丽为什么想买四个苹果？","q_vi":"Vì sao Tiểu Lệ muốn mua bốn quả táo?","options":["小狗点点也爱吃苹果","她很爱吃苹果","妈妈想吃两个","苹果不贵"],"answer":0,"explain_vi":"Đoạn 3: nhà có ba người và chú chó Điểm Điểm cũng thích ăn táo, nên cần bốn quả."},{"q":"小狗的苹果多少钱？","q_vi":"Quả táo của chú chó giá bao nhiêu?","options":["三块","九块","不要钱","十二块"],"answer":2,"explain_vi":"Đoạn 4: chị bán hàng nói quả táo của chú chó “不要钱” – không lấy tiền, tức là tặng."}],"beyond":[["不要","bùyào","BẤT YẾU","đừng, chớ, không được"],["一家人","yījiārén","NHẤT GIA NHÂN","người một nhà, cả gia đình"]]},{"id":"h1-04","level":1,"title":"我在北京","title_vi":"Con đang ở Bắc Kinh","topic":"thư từ","chars":187,"paragraphs":["妈妈：你好！我是阿明。我现在在北京学习汉语，我很好。","北京很大，人很多。现在是十二月，北京很冷，我买了很多衣服。","我的老师是中国人，她很漂亮，我们都很喜欢她。上午我们学习说汉语，下午学习写字。我现在会写八十个字了！","我有一个中国朋友，他叫李大文。星期天，我和大文去饭馆吃饭。中国菜很多，我都喜欢。但是，我想吃妈妈做的菜。","明年一月，我回家。我很想您和爸爸，想我们家的小狗。大文说，他很想去越南看看。妈妈，我的中国朋友能住在我们家吗？","阿明，十二月九日"],"pinyin":["mā ma nǐ hǎo wǒ shì ā míng wǒ xiàn zài zài běi jīng xué xí hàn yǔ wǒ hěn hǎo","běi jīng hěn dà rén hěn duō xiàn zài shì shí èr yuè běi jīng hěn lěng wǒ mǎi le hěn duō yī fu","wǒ de lǎo shī shì zhōng guó rén tā hěn piào liang wǒ men dōu hěn xǐ huan tā shàng wǔ wǒ men xué xí shuō hàn yǔ xià wǔ xué xí xiě zì wǒ xiàn zài huì xiě bā shí gè zì le","wǒ yǒu yí gè zhōng guó péng you tā jiào lǐ dà wén xīng qī tiān wǒ hé dà wén qù fàn guǎn chī fàn zhōng guó cài hěn duō wǒ dōu xǐ huan dàn shì wǒ xiǎng chī mā ma zuò de cài","míng nián yí yuè wǒ huí jiā wǒ hěn xiǎng nín hé bà ba xiǎng wǒ men jiā de xiǎo gǒu dà wén shuō tā hěn xiǎng qù yuè nán kàn kàn mā ma wǒ de zhōng guó péng you néng zhù zài wǒ men jiā ma","ā míng shí èr yuè jiǔ rì"],"translations":["Mẹ ơi, mẹ khỏe không ạ! Con là A Minh đây. Bây giờ con đang học tiếng Hán ở Bắc Kinh, con vẫn khỏe.","Bắc Kinh rất rộng, người rất đông. Bây giờ là tháng Mười Hai, Bắc Kinh lạnh lắm, con đã mua rất nhiều quần áo.","Cô giáo của con là người Trung Quốc, cô rất xinh, cả lớp đều quý cô. Buổi sáng tụi con học nói tiếng Hán, buổi chiều học viết chữ. Bây giờ con viết được tám mươi chữ rồi đó!","Con có một người bạn Trung Quốc tên là Lý Đại Văn. Chủ nhật, con với Đại Văn đi nhà hàng ăn cơm. Món Trung Quốc nhiều lắm, món nào con cũng thích. Nhưng con vẫn thèm món mẹ nấu.","Tháng Một năm sau con về nhà. Con nhớ mẹ và bố lắm, nhớ cả chú chó nhà mình nữa. Đại Văn bảo cậu ấy rất muốn sang Việt Nam xem thử. Mẹ ơi, bạn Trung Quốc của con ở nhà mình được không ạ?","A Minh, ngày 9 tháng 12"],"questions":[{"q":"阿明在北京做什么？","q_vi":"A Minh làm gì ở Bắc Kinh?","options":["工作","学习汉语","看医生","开商店"],"answer":1,"explain_vi":"Đoạn 1: “我现在在北京学习汉语” – A Minh đang học tiếng Hán."},{"q":"阿明现在会写多少个字？","q_vi":"Bây giờ A Minh viết được bao nhiêu chữ?","options":["十个","二十个","四十个","八十个"],"answer":3,"explain_vi":"Đoạn 3: “我现在会写八十个字了” – tám mươi chữ."},{"q":"阿明为什么问“我的中国朋友能住在我们家吗”？","q_vi":"Vì sao A Minh hỏi “bạn Trung Quốc của con ở nhà mình được không”?","options":["大文想去越南看看","大文没有钱","大文不喜欢北京","阿明家很大"],"answer":0,"explain_vi":"Đoạn 5: Đại Văn rất muốn sang Việt Nam, nên A Minh muốn mời bạn về ở nhà mình."}],"beyond":[["但是","dànshì","ĐÃN THỊ","nhưng"],["越南","Yuènán","VIỆT NAM","Việt Nam"]]},{"id":"h1-05","level":1,"title":"一个电话","title_vi":"Một cuộc điện thoại","topic":"truyện ngắn","chars":178,"paragraphs":["星期天下午三点，我在家看书，电话来了。","“喂，是小李吗？我是爸爸。”我说：“对不起，我不是小李，我叫王一。”","那个人说：“对不起，对不起。”听他说话，我想他七八十岁了。他说：“我儿子在北京工作，他很少回家。今天我很想和他说说话……”","我听了，想了想，说：“先生，没关系，我们能说说话。您住在哪里？今天那里天气怎么样？”我们说了二十分钟。他喜欢喝茶，喜欢小猫，他家有三个猫。","现在，星期天下午三点，我都会打电话。电话里，那个先生很高兴：“喂，是小王吗？我是你的老朋友！”"],"pinyin":["xīng qī tiān xià wǔ sān diǎn wǒ zài jiā kàn shū diàn huà lái le","wèi shì xiǎo lǐ ma wǒ shì bà ba wǒ shuō duì bù qǐ wǒ bú shì xiǎo lǐ wǒ jiào wáng yī","nà ge rén shuō duì bù qǐ duì bù qǐ tīng tā shuō huà wǒ xiǎng tā qī bā shí suì le tā shuō wǒ ér zi zài běi jīng gōng zuò tā hěn shǎo huí jiā jīn tiān wǒ hěn xiǎng hé tā shuō shuō huà","wǒ tīng le xiǎng le xiǎng shuō xiān sheng méi guān xì wǒ men néng shuō shuō huà nín zhù zài nǎ lǐ jīn tiān nà lǐ tiān qì zěn me yàng wǒ men shuō le èr shí fēn zhōng tā xǐ huan hē chá xǐ huan xiǎo māo tā jiā yǒu sān gè māo","xiàn zài xīng qī tiān xià wǔ sān diǎn wǒ dū huì dǎ diàn huà diàn huà lǐ nà ge xiān sheng hěn gāo xìng wèi shì xiǎo wáng ma wǒ shì nǐ de lǎo péng you"],"translations":["Ba giờ chiều Chủ nhật, mình đang đọc sách ở nhà thì có điện thoại gọi đến.","“Alo, Tiểu Lý đó hả? Bố đây.” Mình nói: “Xin lỗi, cháu không phải Tiểu Lý, cháu tên là Vương Nhất.”","Người đó nói: “Xin lỗi, xin lỗi.” Nghe giọng ông, mình đoán ông đã bảy, tám mươi tuổi. Ông nói: “Con trai tôi làm việc ở Bắc Kinh, nó ít khi về nhà. Hôm nay tôi rất muốn nói chuyện với nó một chút…”","Nghe xong, mình nghĩ một lát rồi nói: “Ông ơi, không sao đâu, mình nói chuyện với nhau nhé. Ông sống ở đâu ạ? Hôm nay thời tiết ở đó thế nào?” Hai ông cháu nói chuyện hai mươi phút. Ông thích uống trà, thích mèo, nhà ông có ba con mèo.","Bây giờ, cứ ba giờ chiều Chủ nhật là mình gọi điện. Trong điện thoại, ông vui vẻ nói: “Alo, Tiểu Vương đó hả? Bạn già của cháu đây!”"],"questions":[{"q":"打电话的先生想找谁？","q_vi":"Ông cụ gọi điện muốn tìm ai?","options":["王一","他的女儿","他的儿子小李","一个医生"],"answer":2,"explain_vi":"Đoạn 2: “是小李吗？我是爸爸” – ông muốn gọi cho con trai là Tiểu Lý nhưng gọi nhầm."},{"q":"那个先生为什么想说说话？","q_vi":"Vì sao ông cụ muốn nói chuyện?","options":["他想买猫","他儿子很少回家","他是汉语老师","他不认识路"],"answer":1,"explain_vi":"Đoạn 3: con trai ông làm việc ở Bắc Kinh, ít khi về nhà nên ông thấy cô đơn."},{"q":"从这个故事我们能知道什么？","q_vi":"Qua câu chuyện này, ta biết được điều gì?","options":["王一不喜欢说话","那个先生住在北京","王一是小李的同学","王一和那个先生现在是朋友"],"answer":3,"explain_vi":"Đoạn 5: mỗi Chủ nhật Vương Nhất đều gọi điện, ông cụ gọi cậu là “bạn già” – hai người đã thành bạn."}],"beyond":[["老朋友","lǎo péngyou","LÃO BẰNG HỮU","bạn cũ, bạn lâu năm"]]},{"id":"h2-01","level":2,"title":"第一次考试","title_vi":"Kỳ thi đầu tiên","topic":"học tập","chars":229,"paragraphs":["我叫马小东，在北京学习汉语。上个星期五，老师告诉我们：“下星期一有考试，大家好好准备吧。”","这是我的第一次汉语考试，所以我每天都在准备：早上六点起床，晚上十二点睡觉。我看了很多书，做了几百个题。星期天晚上，两点多了，我还在学习。","星期一早上，我起床的时候，手机上已经是七点五十了！我想：考试八点开始，我得快点儿！我很快穿上衣服，什么也没吃，就跑出了门。","我坐出租车到了学校，跑进教室。但是教室里一个人也没有！我想：“我来晚了吗？大家都考完了吗？”","这时候，老师从门外走进来。他看见我，笑了：“小东，你来得真早！考试是下午两点开始的。你可以先回家睡觉了！”"],"pinyin":["wǒ jiào mǎ xiǎo dōng zài běi jīng xué xí hàn yǔ shàng gè xīng qī wǔ lǎo shī gào su wǒ men xià xīng qī yī yǒu kǎo shì dà jiā hǎo hǎo zhǔn bèi ba","zhè shì wǒ de dì yī cì hàn yǔ kǎo shì suǒ yǐ wǒ měi tiān dōu zài zhǔn bèi zǎo shang liù diǎn qǐ chuáng wǎn shang shí èr diǎn shuì jiào wǒ kàn le hěn duō shū zuò le jǐ bǎi gè tí xīng qī tiān wǎn shang liǎng diǎn duō le wǒ hái zài xué xí","xīng qī yī zǎo shang wǒ qǐ chuáng de shí hou shǒu jī shàng yǐ jīng shì qī diǎn wǔ shí le wǒ xiǎng kǎo shì bā diǎn kāi shǐ wǒ de kuài diǎn ér wǒ hěn kuài chuān shàng yī fu shén me yě méi chī jiù pǎo chū le mén","wǒ zuò chū zū chē dào le xué xiào pǎo jìn jiào shì dàn shì jiào shì lǐ yí gè rén yě méi yǒu wǒ xiǎng wǒ lái wǎn le ma dà jiā dōu kǎo wán le ma","zhè shí hou lǎo shī cóng mén wài zǒu jìn lái tā kàn jiàn wǒ xiào le xiǎo dōng nǐ lái de zhēn zǎo kǎo shì shì xià wǔ liǎng diǎn kāi shǐ de nǐ kě yǐ xiān huí jiā shuì jiào le"],"translations":["Tôi tên là Mã Tiểu Đông, đang học tiếng Hán ở Bắc Kinh. Thứ Sáu tuần trước, thầy giáo bảo chúng tôi: “Thứ Hai tuần sau có bài thi, mọi người chuẩn bị cho tốt nhé.”","Đây là kỳ thi tiếng Hán đầu tiên của tôi, vì vậy ngày nào tôi cũng ôn: sáu giờ sáng dậy, mười hai giờ đêm mới ngủ. Tôi đọc rất nhiều sách, làm mấy trăm câu bài tập. Tối Chủ nhật, đã hơn hai giờ sáng mà tôi vẫn còn học.","Sáng thứ Hai, lúc tôi thức dậy, điện thoại đã chỉ bảy giờ năm mươi! Tôi nghĩ: tám giờ bắt đầu thi, mình phải nhanh lên! Tôi vội vàng mặc quần áo, chẳng ăn gì, chạy ngay ra khỏi nhà.","Tôi đi taxi đến trường, chạy vào phòng học. Nhưng trong phòng học không có một ai! Tôi nghĩ: “Mình đến muộn rồi sao? Mọi người thi xong hết rồi à?”","Đúng lúc đó, thầy giáo từ ngoài cửa bước vào. Thấy tôi, thầy bật cười: “Tiểu Đông, em đến sớm thật đấy! Hai giờ chiều mới bắt đầu thi cơ. Em có thể về nhà ngủ một giấc trước đã!”"],"questions":[{"q":"这个星期小东为什么睡觉很晚？","q_vi":"Tuần này vì sao Tiểu Đông ngủ rất muộn?","options":["他在看电视","他在准备考试","他在公司工作","他生病了"],"answer":1,"explain_vi":"Đoạn 2: đây là kỳ thi đầu tiên nên ngày nào cậu cũng ôn đến khuya."},{"q":"小东跑进教室的时候，教室里有谁？","q_vi":"Khi Tiểu Đông chạy vào phòng học, trong phòng có ai?","options":["很多同学","老师和同学","一个人也没有","两个同学"],"answer":2,"explain_vi":"Đoạn 4: “教室里一个人也没有” – trong phòng không có ai cả."},{"q":"从这个故事我们可以知道什么？","q_vi":"Qua câu chuyện này, ta có thể biết điều gì?","options":["小东考试考得很好","老师来晚了","同学们都考完了","小东觉得考试是早上八点开始"],"answer":3,"explain_vi":"Tiểu Đông tưởng tám giờ sáng thi nên vội vàng chạy đến, thật ra hai giờ chiều mới thi."}],"beyond":[["好好","hǎohǎo","HẢO HẢO","chu đáo, cẩn thận; ngoan, tốt đẹp"],["穿上","chuānshang","XUYÊN THƯỢNG","mặc, khoác lên; xỏ"],["完了","wánle","HOÀN LIỄU","xong rồi"]]},{"id":"h2-02","level":2,"title":"爸爸的手表","title_vi":"Chiếc đồng hồ của bố","topic":"gia đình","chars":274,"paragraphs":["爸爸有一块手表，是二十年前妈妈送给他的。这块手表不贵，颜色也不新了，但是爸爸非常喜欢，每天上班都要用它。","上个星期，爸爸的手表找不到了。他在房间里找，在公司里找，还给公共汽车公司打了电话，都没有找到。爸爸很不高兴，饭也吃得很少。","我和弟弟想：我们送爸爸一块新手表吧！我们一起去商店看了很多手表。好看的都非常贵，我们的钱太少了。我们买了一块黑色的，三百块。","爸爸生日那天，我们把新手表送给他。爸爸笑了：“谢谢你们！”这时候，妈妈从房间里走出来，说：“我也有一件东西要送给你。”她送的，就是那块找不到的手表！","妈妈说：“昨天我洗衣服的时候，在你的衣服里找到的。”现在，爸爸有两块手表，左边一块，右边一块。他说：“左边的是妻子送的，右边的是孩子们送的，我都爱！”"],"pinyin":["bà ba yǒu yī kuài shǒu biǎo shì èr shí nián qián mā ma sòng gěi tā de zhè kuài shǒu biǎo bù guì yán sè yě bù xīn le dàn shì bà ba fēi cháng xǐ huan měi tiān shàng bān dōu yào yòng tā","shàng gè xīng qī bà ba de shǒu biǎo zhǎo bú dào le tā zài fáng jiān lǐ zhǎo zài gōng sī lǐ zhǎo huán gěi gōng gòng qì chē gōng sī dǎ le diàn huà dōu méi yǒu zhǎo dào bà ba hěn bù gāo xìng fàn yě chī de hěn shǎo","wǒ hé dì di xiǎng wǒ men sòng bà ba yī kuài xīn shǒu biǎo ba wǒ men yì qǐ qù shāng diàn kàn le hěn duō shǒu biǎo hǎo kàn de dōu fēi cháng guì wǒ men de qián tài shǎo le wǒ men mǎi le yī kuài hēi sè de sān bǎi kuài","bà ba shēng rì nà tiān wǒ men bǎ xīn shǒu biǎo sòng gěi tā bà ba xiào le xiè xiè nǐ men zhè shí hou mā ma cóng fáng jiān lǐ zǒu chū lái shuō wǒ yě yǒu yī jiàn dōng xi yào sòng gěi nǐ tā sòng de jiù shì nà kuài zhǎo bú dào de shǒu biǎo","mā ma shuō zuó tiān wǒ xǐ yī fú de shí hou zài nǐ de yī fu lǐ zhǎo dào de xiàn zài bà ba yǒu liǎng kuài shǒu biǎo zuǒ biān yī kuài yòu biān yī kuài tā shuō zuǒ biān de shì qī zi sòng de yòu biān de shì hái zi men sòng de wǒ dōu ài"],"translations":["Bố có một chiếc đồng hồ đeo tay, là quà mẹ tặng bố từ hai mươi năm trước. Chiếc đồng hồ này không đắt, màu cũng đã cũ, nhưng bố rất thích, ngày nào đi làm cũng mang theo.","Tuần trước, bố không tìm thấy đồng hồ đâu nữa. Bố tìm trong phòng, tìm ở công ty, còn gọi điện cho cả công ty xe buýt, nhưng đều không tìm được. Bố buồn lắm, ăn cơm cũng ít hẳn.","Em trai và tôi nghĩ: hay là mình tặng bố một chiếc đồng hồ mới! Hai anh em cùng ra cửa hàng xem rất nhiều đồng hồ. Cái nào đẹp cũng đắt lắm, tiền của tụi tôi thì ít quá. Cuối cùng tụi tôi mua một chiếc màu đen, giá ba trăm đồng.","Hôm sinh nhật bố, tụi tôi tặng bố chiếc đồng hồ mới. Bố cười: “Cảm ơn các con!” Đúng lúc đó, mẹ từ trong phòng bước ra, nói: “Em cũng có một món muốn tặng anh.” Thứ mẹ tặng chính là chiếc đồng hồ đã thất lạc!","Mẹ nói: “Hôm qua lúc giặt quần áo, em tìm thấy nó trong túi áo của anh.” Bây giờ bố có hai chiếc đồng hồ, tay trái một chiếc, tay phải một chiếc. Bố bảo: “Cái bên trái là vợ tặng, cái bên phải là các con tặng, bố quý cả hai!”"],"questions":[{"q":"爸爸的旧手表是谁送的？","q_vi":"Chiếc đồng hồ cũ của bố là ai tặng?","options":["孩子们","妈妈","爸爸的朋友","公司"],"answer":1,"explain_vi":"Đoạn 1: “是二十年前妈妈送给他的” – do mẹ tặng hai mươi năm trước."},{"q":"手表是在哪儿找到的？","q_vi":"Chiếc đồng hồ được tìm thấy ở đâu?","options":["公司里","公共汽车上","商店里","爸爸的衣服里"],"answer":3,"explain_vi":"Đoạn 5: mẹ giặt quần áo và tìm thấy đồng hồ trong quần áo của bố."},{"q":"爸爸为什么说“我都爱”？","q_vi":"Vì sao bố nói “bố quý cả hai”?","options":["两块手表都是家人送的","两块手表都很贵","两块手表颜色一样","他不喜欢新手表"],"answer":0,"explain_vi":"Một chiếc là vợ tặng, một chiếc là các con tặng – cả hai đều chứa tình cảm gia đình."}],"beyond":[["把","bǎ","BẢ","đem, lấy (giới từ) · đem, lấy (giới từ câu chữ 把)"],["就是","jiùshì","TỰU THỊ","chính là; cho dù; dù là"]]},{"id":"h2-03","level":2,"title":"第一次看见雪","title_vi":"Lần đầu thấy tuyết","topic":"du lịch, nhật ký","chars":242,"paragraphs":["一月十五日，晴。今天我和姐姐从北京坐飞机去了哈尔滨。哈尔滨离北京很远，我们坐了两个多小时的飞机。","在越南，我没有看见过雪。下飞机的时候，我看见外面都是白色的，高兴得笑了起来。外面非常冷，比北京冷多了。我穿了三件衣服，但是还觉得冷。","下午，我们在雪里玩了两个小时。我们做了一个很大的雪人。它有两个黑黑的眼睛，还穿着姐姐的红衣服，非常漂亮！","晚上，我们去饭馆吃饭。服务员向我们介绍了这里的羊肉和鱼。羊肉非常好吃，也不贵，两个人一共一百多块钱。","回到房间，我给妈妈打电话：“妈妈，我看见雪了！”妈妈说：“真的吗？你们那里冷不冷？今天我们这里也很冷，十五度！”我和姐姐听了，都笑了。"],"pinyin":["yí yuè shí wǔ rì qíng jīn tiān wǒ hé jiě jie cóng běi jīng zuò fēi jī qù le hā ěr bīn hā ěr bīn lí běi jīng hěn yuǎn wǒ men zuò le liǎng gè duō xiǎo shí de fēi jī","zài yuè nán wǒ méi yǒu kàn jiàn guò xuě xià fēi jī de shí hou wǒ kàn jiàn wài miàn dōu shì bái sè de gāo xìng de xiào le qǐ lái wài miàn fēi cháng lěng bǐ běi jīng lěng duō le wǒ chuān le sān jiàn yī fu dàn shì hái jué de lěng","xià wǔ wǒ men zài xuě lǐ wán le liǎng gè xiǎo shí wǒ men zuò le yí gè hěn dà de xuě rén tā yǒu liǎng gè hēi hēi de yǎn jing hái chuān zhe jiě jie de hóng yī fú fēi cháng piào liang","wǎn shang wǒ men qù fàn guǎn chī fàn fú wù yuán xiàng wǒ men jiè shào le zhè lǐ de yáng ròu hé yú yáng ròu fēi cháng hǎo chī yě bù guì liǎng gè rén yī gòng yì bǎi duō kuài qián","huí dào fáng jiān wǒ gěi mā ma dǎ diàn huà mā ma wǒ kàn jiàn xuě le mā ma shuō zhēn de ma nǐ men nà lǐ lěng bù lěng jīn tiān wǒ men zhè lǐ yě hěn lěng shí wǔ dù wǒ hé jiě jie tīng le dōu xiào le"],"translations":["Ngày 15 tháng 1, trời nắng. Hôm nay em và chị gái đi máy bay từ Bắc Kinh đến Cáp Nhĩ Tân. Cáp Nhĩ Tân cách Bắc Kinh rất xa, tụi em ngồi máy bay hơn hai tiếng.","Ở Việt Nam, em chưa từng thấy tuyết. Lúc xuống máy bay, em thấy bên ngoài trắng xóa, vui đến bật cười. Bên ngoài lạnh cực kỳ, lạnh hơn Bắc Kinh nhiều. Em mặc ba lớp áo mà vẫn thấy lạnh.","Buổi chiều, tụi em chơi trong tuyết suốt hai tiếng. Tụi em đắp một người tuyết rất to. Nó có hai con mắt đen láy, còn mặc chiếc áo đỏ của chị, đẹp lắm!","Buổi tối, tụi em đi ăn ở nhà hàng. Nhân viên phục vụ giới thiệu món thịt cừu và cá ở đây. Thịt cừu ngon tuyệt, lại không đắt, hai người tổng cộng chỉ hơn một trăm đồng.","Về đến phòng, em gọi điện cho mẹ: “Mẹ ơi, con thấy tuyết rồi!” Mẹ nói: “Thật hả? Chỗ con có lạnh không? Hôm nay ở nhà mình cũng lạnh lắm, mười lăm độ đấy!” Em và chị nghe xong đều phá lên cười."],"questions":[{"q":"这是“我”第一次做什么？","q_vi":"Đây là lần đầu tiên “tôi” làm gì?","options":["坐飞机","看见雪","吃羊肉","去北京"],"answer":1,"explain_vi":"Đoạn 2: “在越南，我没有看见过雪” – đây là lần đầu tiên thấy tuyết."},{"q":"雪人穿着什么衣服？","q_vi":"Người tuyết mặc áo gì?","options":["黑色的衣服","白色的衣服","姐姐的红衣服","妈妈的衣服"],"answer":2,"explain_vi":"Đoạn 3: “还穿着姐姐的红衣服” – mặc chiếc áo đỏ của chị."},{"q":"“我”和姐姐为什么笑了？","q_vi":"Vì sao “tôi” và chị gái bật cười?","options":["妈妈觉得十五度很冷，可是哈尔滨冷多了","妈妈也来了哈尔滨","羊肉太便宜了","妈妈没有听懂"],"answer":0,"explain_vi":"Mẹ ở Việt Nam thấy 15 độ đã là lạnh, trong khi Cáp Nhĩ Tân lạnh hơn rất nhiều – nên hai chị em thấy buồn cười."}],"beyond":[["哈尔滨","Hā'ěrbīn","CÁP NHĨ TÂN","Cáp Nhĩ Tân"],["越南","Yuènán","VIỆT NAM","Việt Nam"],["外面","wàimiàn","NGOẠI DIỆN","bên ngoài, phía ngoài"],["穿着","chuānzhuó","XUYÊN TRƯỚC","cách ăn mặc · trang phục, cách ăn mặc"]]},{"id":"h2-04","level":2,"title":"说真话的孩子","title_vi":"Cậu bé nói thật","topic":"ngụ ngôn","chars":222,"paragraphs":["天气非常热，路旁边有一个卖西瓜的孩子。他叫小林，今年十岁。他的西瓜很大，也很便宜，但是买的人不多。","一天下午，一个男人走过来，问：“小朋友，这个西瓜好吃吗？”小林看了看，说：“这个不好吃，里面太白了。您买旁边那个吧，那个好吃。”","男人笑了：“卖西瓜的人都说‘我的西瓜最好吃’，你为什么说‘这个不好吃’？”小林回答：“妈妈告诉我，卖东西的时候，要说真话。”","男人买了十个西瓜。第二天，他又来了，还和很多朋友一起来。他说：“我在前面开了一个饭馆。从今天开始，我的饭馆每天都要买你的西瓜！”","现在，小林的西瓜卖得非常快。大家都说：“买西瓜，就去找那个说真话的孩子！”"],"pinyin":["tiān qì fēi cháng rè lù páng biān yǒu yí gè mài xī guā de hái zi tā jiào xiǎo lín jīn nián shí suì tā de xī guā hěn dà yě hěn pián yi dàn shì mǎi de rén bù duō","yī tiān xià wǔ yí gè nán rén zǒu guò lái wèn xiǎo péng you zhè ge xī guā hǎo chī ma xiǎo lín kàn le kàn shuō zhè ge bù hǎo chī lǐ miàn tài bái le nín mǎi páng biān nà ge ba nà ge hǎo chī","nán rén xiào le mài xī guā de rén dōu shuō wǒ de xī guā zuì hǎo chī nǐ wèi shén me shuō zhè ge bù hǎo chī xiǎo lín huí dá mā ma gào su wǒ mài dōng xi de shí hou yào shuō zhēn huà","nán rén mǎi le shí gè xī guā dì èr tiān tā yòu lái le hái hé hěn duō péng you yī qǐ lái tā shuō wǒ zài qián miàn kāi le yí gè fàn guǎn cóng jīn tiān kāi shǐ wǒ de fàn guǎn měi tiān dōu yào mǎi nǐ de xī guā","xiàn zài xiǎo lín de xī guā mài dé fēi cháng kuài dà jiā dōu shuō mǎi xī guā jiù qù zhǎo nà ge shuō zhēn huà de hái zi"],"translations":["Trời nóng như đổ lửa, bên vệ đường có một cậu bé bán dưa hấu. Cậu tên là Tiểu Lâm, năm nay mười tuổi. Dưa của cậu rất to, lại rẻ, nhưng không mấy người mua.","Một buổi chiều, có một người đàn ông đi tới hỏi: “Cháu ơi, quả dưa này có ngon không?” Tiểu Lâm nhìn nhìn rồi nói: “Quả này không ngon đâu ạ, ruột trắng quá. Chú mua quả bên cạnh ấy, quả đó ngon.”","Người đàn ông bật cười: “Người bán dưa ai cũng nói ‘dưa của tôi ngon nhất’, sao cháu lại bảo ‘quả này không ngon’?” Tiểu Lâm đáp: “Mẹ cháu dặn, khi bán hàng phải nói thật.”","Người đàn ông mua mười quả dưa. Hôm sau ông lại đến, còn dẫn theo rất nhiều bạn bè. Ông nói: “Chú mở một nhà hàng ở phía trước. Từ hôm nay, ngày nào nhà hàng của chú cũng sẽ mua dưa của cháu!”","Bây giờ dưa của Tiểu Lâm bán rất chạy. Ai cũng nói: “Mua dưa hấu thì cứ tìm cậu bé nói thật ấy!”"],"questions":[{"q":"小林是做什么的？","q_vi":"Tiểu Lâm làm gì?","options":["在饭馆工作","卖鱼","开出租车","卖西瓜"],"answer":3,"explain_vi":"Đoạn 1: “路旁边有一个卖西瓜的孩子” – Tiểu Lâm bán dưa hấu bên đường."},{"q":"小林为什么说“这个不好吃”？","q_vi":"Vì sao Tiểu Lâm nói “quả này không ngon”?","options":["他想卖贵的西瓜","妈妈告诉他要说真话","他不喜欢那个男人","那个西瓜是他的"],"answer":1,"explain_vi":"Đoạn 3: mẹ dặn cậu khi bán hàng phải nói thật."},{"q":"这个故事想告诉我们什么？","q_vi":"Câu chuyện này muốn nói với chúng ta điều gì?","options":["说真话的人，大家都喜欢","白色的西瓜最好吃","卖东西一定要便宜","饭馆的西瓜很贵"],"answer":0,"explain_vi":"Nhờ trung thực, Tiểu Lâm được người khác tin tưởng và bán được nhiều dưa – nói thật sẽ được mọi người quý."}],"beyond":[["里面","lǐmiàn","LÝ DIỆN","bên trong, phía trong"]]},{"id":"h2-05","level":2,"title":"妈妈的新手机","title_vi":"Chiếc điện thoại mới của mẹ","topic":"xã hội hiện đại","chars":234,"paragraphs":["去年，我给妈妈买了一个新手机。妈妈说：“我已经五十多岁了，不会用这个。”我说：“没关系，我来帮助你。”","我每天晚上都帮妈妈：怎么打电话，怎么给朋友写东西，怎么看电影。妈妈学得很慢，一个问题要问三四次。","两个月过去了，妈妈什么都会了。她用手机买东西、听歌，还用手机学跳舞。她认识了很多跳舞的新朋友，每天晚上都和她们一起出去跳舞。","现在，妈妈早上一起床就看手机。吃饭的时候，她也看着手机笑。我问她：“妈妈，什么事情这么好笑？”她说：“你不懂！”","昨天晚上十一点，妈妈还在玩手机。我说：“妈妈，已经十一点了，别玩手机了，快去睡觉吧！”妈妈看着我，笑了：“你小的时候，我每天都对你说这个！”"],"pinyin":["qù nián wǒ gěi mā ma mǎi le yí gè xīn shǒu jī mā ma shuō wǒ yǐ jīng wǔ shí duō suì le bú huì yòng zhè ge wǒ shuō méi guān xì wǒ lái bāng zhù nǐ","wǒ měi tiān wǎn shang dōu bāng mā ma zěn me dǎ diàn huà zěn me gěi péng you xiě dōng xi zěn me kàn diàn yǐng mā ma xué dé hěn màn yí gè wèn tí yào wèn sān sì cì","liǎng gè yuè guò qù le mā ma shén me dū huì le tā yòng shǒu jī mǎi dōng xi tīng gē hái yòng shǒu jī xué tiào wǔ tā rèn shi le hěn duō tiào wǔ de xīn péng you měi tiān wǎn shang dōu hé tā men yì qǐ chū qù tiào wǔ","xiàn zài mā ma zǎo shang yī qǐ chuáng jiù kàn shǒu jī chī fàn de shí hou tā yě kàn zhe shǒu jī xiào wǒ wèn tā mā ma shén me shì qing zhè me hǎo xiào tā shuō nǐ bù dǒng","zuó tiān wǎn shang shí yì diǎn mā ma hái zài wán shǒu jī wǒ shuō mā ma yǐ jīng shí yì diǎn le bié wán shǒu jī le kuài qù shuì jiào ba mā ma kàn zhe wǒ xiào le nǐ xiǎo de shí hou wǒ měi tiān dōu duì nǐ shuō zhè ge"],"translations":["Năm ngoái, tôi mua cho mẹ một chiếc điện thoại mới. Mẹ nói: “Mẹ đã hơn năm mươi tuổi rồi, không biết dùng cái này đâu.” Tôi nói: “Không sao, để con giúp mẹ.”","Tối nào tôi cũng giúp mẹ: cách gọi điện, cách nhắn tin cho bạn bè, cách xem phim. Mẹ học rất chậm, một câu hỏi phải hỏi ba bốn lần.","Hai tháng trôi qua, mẹ đã biết làm mọi thứ. Mẹ dùng điện thoại để mua đồ, nghe nhạc, còn học nhảy trên điện thoại nữa. Mẹ quen được rất nhiều bạn mới cùng nhảy, tối nào cũng cùng họ ra ngoài nhảy.","Bây giờ, sáng ra mẹ vừa dậy là xem điện thoại ngay. Lúc ăn cơm, mẹ cũng nhìn điện thoại mà cười. Tôi hỏi: “Mẹ ơi, có chuyện gì buồn cười thế?” Mẹ bảo: “Con không hiểu đâu!”","Mười một giờ tối qua, mẹ vẫn còn chơi điện thoại. Tôi nói: “Mẹ ơi, mười một giờ rồi, đừng chơi điện thoại nữa, mau đi ngủ đi!” Mẹ nhìn tôi rồi cười: “Hồi con còn nhỏ, ngày nào mẹ cũng nói với con câu này!”"],"questions":[{"q":"开始的时候，妈妈为什么说不会用手机？","q_vi":"Lúc đầu, vì sao mẹ nói không biết dùng điện thoại?","options":["手机太贵了","她没有时间","她觉得自己年纪大了","她不喜欢新东西"],"answer":2,"explain_vi":"Đoạn 1: “我已经五十多岁了” – mẹ nghĩ mình đã lớn tuổi nên không học được."},{"q":"下面哪一个，妈妈没有用手机做？","q_vi":"Việc nào dưới đây mẹ KHÔNG dùng điện thoại để làm?","options":["买东西","学跳舞","听歌","打篮球"],"answer":3,"explain_vi":"Đoạn 3 nói mẹ dùng điện thoại mua đồ, nghe nhạc, học nhảy; không nhắc đến chơi bóng rổ."},{"q":"妈妈最后的话是什么意思？","q_vi":"Câu nói cuối cùng của mẹ có ý gì?","options":["以前是妈妈让孩子别玩，快睡觉","妈妈每天十一点睡觉","妈妈不想睡觉，想跳舞","孩子小的时候很喜欢手机"],"answer":0,"explain_vi":"Ngày xưa mẹ hay nhắc con đi ngủ, giờ đến lượt con nhắc mẹ – vai trò đã đảo ngược, rất hài hước."}],"beyond":[["新手","xīnshǒu","TÂN THỦ","người mới, tay mơ, lính mới"],["好笑","hǎoxiào","HẢO TIẾU","buồn cười, nực cười"]]},{"id":"h3-01","level":3,"title":"同一个月亮","title_vi":"Cùng một vầng trăng","topic":"văn hóa – phong tục","chars":416,"paragraphs":["每年秋天，中国人都要过一个重要的节日——中秋节。这一天晚上，月亮又大又圆，一家人会坐在一起，一边吃月饼，一边看月亮。","我叫小月，今年上三年级。我的名字就和月亮有关系。奶奶说，我是在中秋节的晚上出生的，那天的月亮特别漂亮，所以爸爸妈妈就叫我“小月”。","今年中秋节，爸爸妈妈在别的城市工作，太忙了，不能回家。我和爷爷奶奶住在一起。下午，奶奶在厨房里做月饼，我在旁边帮忙。奶奶做的月饼不太甜，里面有鸡蛋，还有一点儿肉。她说，以前大家都是自己在家里做月饼，现在人们习惯去商店买，可是她认为还是自己做的最好吃。","晚上，我们拿着月饼和水果，到楼下的小公园里看月亮。爷爷说，以前很多人在很远的地方工作，中秋节回不了家，他们就会在晚上看一看月亮。因为在世界上的每一个地方，大家看到的都是同一个月亮。","我听了以后，突然非常想爸爸妈妈。就在这时候，奶奶的手机响了，是爸爸妈妈打来的电话。妈妈笑着说：“小月，你看月亮了吗？我们也在看呢！”","我又看了看天上的月亮，觉得它比以前更大、更漂亮了。那天晚上我明白了：中秋节的月亮这么特别，是因为它能让住在不同地方的家人觉得，他们其实就在一起。"],"pinyin":["měi nián qiū tiān zhōng guó rén dōu yào guò yí gè zhòng yào de jié rì zhōng qiū jié zhè yī tiān wǎn shang yuè liang yòu dà yòu yuán yī jiā rén huì zuò zài yì qǐ yī biān chī yuè bǐng yī biān kàn yuè liang","wǒ jiào xiǎo yuè jīn nián shàng sān nián jí wǒ de míng zi jiù hé yuè liang yǒu guān xi nǎi nai shuō wǒ shì zài zhōng qiū jié de wǎn shang chū shēng de nà tiān de yuè liang tè bié piào liang suǒ yǐ bà ba mā ma jiù jiào wǒ xiǎo yuè","jīn nián zhōng qiū jié bà ba mā ma zài bié de chéng shì gōng zuò tài máng le bù néng huí jiā wǒ hé yé ye nǎi nai zhù zài yì qǐ xià wǔ nǎi nai zài chú fáng lǐ zuò yuè bǐng wǒ zài páng biān bāng máng nǎi nai zuò de yuè bǐng bù tài tián lǐ miàn yǒu jī dàn hái yǒu yì diǎn ér ròu tā shuō yǐ qián dà jiā dōu shì zì jǐ zài jiā lǐ zuò yuè bǐng xiàn zài rén men xí guàn qù shāng diàn mǎi kě shì tā rèn wéi hái shì zì jǐ zuò de zuì hǎo chī","wǎn shang wǒ men ná zhe yuè bǐng hé shuǐ guǒ dào lóu xià de xiǎo gōng yuán lǐ kàn yuè liang yé ye shuō yǐ qián hěn duō rén zài hěn yuǎn de dì fang gōng zuò zhōng qiū jié huí bù liǎo jiā tā men jiù huì zài wǎn shang kàn yī kàn yuè liang yīn wèi zài shì jiè shàng de měi yí gè dì fang dà jiā kàn dào de dōu shì tóng yī gè yuè liang","wǒ tīng le yǐ hòu tū rán fēi cháng xiǎng bà ba mā ma jiù zài zhè shí hou nǎi nai de shǒu jī xiǎng le shì bà ba mā ma dǎ lái de diàn huà mā ma xiào zhe shuō xiǎo yuè nǐ kàn yuè liang le ma wǒ men yě zài kàn ne","wǒ yòu kàn le kàn tiān shàng de yuè liang jué de tā bǐ yǐ qián gèng dà gèng piào liang le nà tiān wǎn shang wǒ míng bai le zhōng qiū jié de yuè liang zhè me tè bié shì yīn wèi tā néng ràng zhù zài bù tóng dì fang de jiā rén jué de tā men qí shí jiù zài yì qǐ"],"translations":["Mùa thu hằng năm, người Trung Quốc đều đón một ngày lễ quan trọng – Tết Trung thu. Tối hôm ấy, mặt trăng vừa to vừa tròn, cả nhà sẽ ngồi bên nhau, vừa ăn bánh trung thu vừa ngắm trăng.","Em tên là Tiểu Nguyệt, năm nay học lớp ba. Tên của em có liên quan đến mặt trăng. Bà nói em sinh vào tối Trung thu, hôm đó trăng đẹp lắm, nên bố mẹ gọi em là \"Tiểu Nguyệt\" (Trăng nhỏ).","Trung thu năm nay, bố mẹ làm việc ở thành phố khác, bận quá nên không về nhà được. Em ở cùng ông bà. Buổi chiều, bà làm bánh trung thu trong bếp, em đứng bên cạnh giúp. Bánh bà làm không ngọt lắm, bên trong có trứng và một chút thịt. Bà bảo ngày trước mọi người đều tự làm bánh ở nhà, bây giờ người ta quen ra cửa hàng mua, nhưng bà cho rằng bánh tự làm vẫn ngon nhất.","Buổi tối, chúng em mang bánh và hoa quả xuống công viên nhỏ dưới nhà ngắm trăng. Ông kể rằng ngày xưa nhiều người làm việc ở nơi rất xa, Trung thu không về nhà được, nên buổi tối họ sẽ ngắm trăng. Bởi vì dù ở nơi nào trên thế giới, mọi người cũng đều nhìn thấy cùng một vầng trăng.","Nghe xong, em bỗng nhớ bố mẹ vô cùng. Đúng lúc ấy, điện thoại của bà reo, là bố mẹ gọi tới. Mẹ cười nói: \"Tiểu Nguyệt, con ngắm trăng chưa? Bố mẹ cũng đang ngắm đây!\"","Em lại ngước nhìn mặt trăng trên trời, thấy nó to hơn, đẹp hơn trước. Tối hôm đó em hiểu ra: trăng Trung thu đặc biệt như vậy là vì nó khiến những người thân sống ở những nơi khác nhau cảm thấy họ thật ra đang ở bên nhau."],"questions":[{"q":"小月的名字是怎么来的？","q_vi":"Tên của Tiểu Nguyệt từ đâu mà có?","options":["她最喜欢看月亮","她是中秋节晚上出生的","奶奶喜欢吃月饼","她的家在月亮旁边"],"answer":1,"explain_vi":"Đoạn 2: bé sinh vào tối Trung thu, trăng rất đẹp nên được gọi là Tiểu Nguyệt."},{"q":"关于奶奶做的月饼，下面哪个是对的？","q_vi":"Về bánh trung thu bà làm, câu nào dưới đây đúng?","options":["是在商店买的","非常非常甜","里面有鸡蛋和一点儿肉","小月一个人做的"],"answer":2,"explain_vi":"Đoạn 3: bánh không ngọt lắm, bên trong có trứng và một chút thịt."},{"q":"爷爷为什么说以前的人中秋节会看月亮？","q_vi":"Vì sao ông nói người xưa ngắm trăng vào Trung thu?","options":["因为在哪儿看到的都是同一个月亮","因为那天晚上没有电视","因为月亮能告诉他们时间","因为他们不喜欢吃月饼"],"answer":0,"explain_vi":"Đoạn 4: dù ở đâu mọi người cũng thấy cùng một vầng trăng, nên ngắm trăng như nhớ về người nhà."},{"q":"这篇文章主要想告诉我们什么？","q_vi":"Bài văn chủ yếu muốn nói với chúng ta điều gì?","options":["月饼应该自己做","中秋节的月亮最大","小孩子不能一个人看月亮","中秋节的月亮让分开的家人觉得在一起"],"answer":3,"explain_vi":"Câu kết: trăng Trung thu khiến người thân ở xa nhau cảm thấy như đang ở bên nhau – đó là ý chính."}],"beyond":[["中秋节","Zhōngqiū Jié","TRUNG THU TIẾT","Tết Trung Thu"],["圆","yuán","VIÊN","hình tròn · tròn, hình tròn; hình tròn"],["一家人","yījiārén","NHẤT GIA NHÂN","người một nhà, cả gia đình"],["月饼","yuèbing","NGUYỆT BÍNH","bánh trung thu"],["同一","tóngyī","ĐỒNG NHẤT","đồng nhất, giống nhau · cùng một, giống nhau"]]},{"id":"h3-02","level":3,"title":"车站的老奶奶","title_vi":"Bà cụ ở bến xe buýt","topic":"truyện ngắn","chars":397,"paragraphs":["小王每天早上七点半坐公共汽车去上班。在车站，他总是能看见一位老奶奶。她的头发都白了，衣服很旧，可是非常干净，手里总是拿着一个小包。","奇怪的是，每次车来了，别人都上车，只有老奶奶不上。她就站在那里，看着车开走，然后笑一笑，再慢慢地走回家。","一个星期过去了，一个月过去了，每天都是这样。小王想：她是不是在等一个人？可能是她的老朋友，也可能是她的儿子。可是那个人为什么一直不来呢？小王越想越担心。","有一天下大雨，老奶奶还是来了。她没有带伞，就站在雨里。小王走过去，把自己的伞给她，问：“奶奶，您每天都在这儿等谁啊？天气这么不好，您还是回家吧。”","老奶奶笑了，说：“谢谢你，年轻人。我不是在等人，我是来看人的。”","“看人？看谁？”小王更不明白了。","这时候，公共汽车来了。老奶奶向开车的司机笑了笑，司机也笑着向她点了点头。","“那是我儿子。”老奶奶高兴地说，“他工作很忙，一年只能回家一次。可是他每天早上都会开着这辆车经过这里。我来车站，就是为了每天能看他一眼。”","那天上车以后，小王一直看着外面的雨。过了一会儿，他拿出手机，给很久没回家看过的妈妈打了一个电话。"],"pinyin":["xiǎo wáng měi tiān zǎo shang qī diǎn bàn zuò gōng gòng qì chē qù shàng bān zài chē zhàn tā zǒng shì néng kàn jiàn yī wèi lǎo nǎi nai tā de tóu fa dōu bái le yī fu hěn jiù kě shì fēi cháng gān jìng shǒu lǐ zǒng shì ná zhe yí gè xiǎo bāo","qí guài de shì měi cì chē lái le bié rén dōu shàng chē zhǐ yǒu lǎo nǎi nai bù shàng tā jiù zhàn zài nà lǐ kàn zhe chē kāi zǒu rán hòu xiào yī xiào zài màn màn de zǒu huí jiā","yí gè xīng qī guò qù le yí gè yuè guò qù le měi tiān dōu shì zhè yàng xiǎo wáng xiǎng tā shì bú shì zài děng yí gè rén kě néng shì tā de lǎo péng you yě kě néng shì tā de ér zi kě shì nà ge rén wèi shén me yì zhí bù lái ne xiǎo wáng yuè xiǎng yuè dān xīn","yǒu yī tiān xià dà yǔ lǎo nǎi nai hái shì lái le tā méi yǒu dài sǎn jiù zhàn zài yǔ lǐ xiǎo wáng zǒu guò qù bǎ zì jǐ de sǎn gěi tā wèn nǎi nai nín měi tiān dōu zài zhè ér děng shuí a tiān qì zhè me bù hǎo nín hái shì huí jiā ba","lǎo nǎi nai xiào le shuō xiè xiè nǐ nián qīng rén wǒ bú shì zài děng rén wǒ shì lái kàn rén de","kàn rén kàn shuí xiǎo wáng gèng bù míng bai le","zhè shí hou gōng gòng qì chē lái le lǎo nǎi nai xiàng kāi chē de sī jī xiào le xiào sī jī yě xiào zhe xiàng tā diǎn le diǎn tóu","nà shì wǒ ér zi lǎo nǎi nai gāo xìng dì shuō tā gōng zuò hěn máng yī nián zhǐ néng huí jiā yī cì kě shì tā měi tiān zǎo shang dū huì kāi zhe zhè liàng chē jīng guò zhè lǐ wǒ lái chē zhàn jiù shì wèi le měi tiān néng kàn tā yī yǎn","nà tiān shàng chē yǐ hòu xiǎo wáng yì zhí kàn zhe wài miàn de yǔ guò le yī huì er tā ná chū shǒu jī gěi hěn jiǔ méi huí jiā kàn guò de mā ma dǎ le yí gè diàn huà"],"translations":["Sáng nào Tiểu Vương cũng đi xe buýt lúc bảy rưỡi để đi làm. Ở bến xe, anh luôn thấy một bà cụ. Tóc bà đã bạc trắng, quần áo cũ nhưng rất sạch sẽ, tay lúc nào cũng cầm một chiếc túi nhỏ.","Điều lạ là mỗi lần xe đến, người khác đều lên xe, chỉ có bà cụ là không. Bà cứ đứng đó, nhìn xe chạy đi, rồi mỉm cười và thong thả đi về nhà.","Một tuần trôi qua, một tháng trôi qua, ngày nào cũng như vậy. Tiểu Vương nghĩ: có phải bà đang đợi ai đó không? Có thể là bạn cũ của bà, cũng có thể là con trai bà. Nhưng sao người đó mãi không đến? Tiểu Vương càng nghĩ càng lo.","Một hôm trời mưa to, bà cụ vẫn đến. Bà không mang ô, cứ đứng dưới mưa. Tiểu Vương bước tới, đưa ô của mình cho bà và hỏi: \"Bà ơi, ngày nào bà cũng đợi ai ở đây vậy? Thời tiết xấu thế này, bà về nhà đi ạ.\"","Bà cụ cười, nói: \"Cảm ơn cháu, chàng trai. Bà không đợi ai cả, bà đến để nhìn một người.\"","\"Nhìn người? Nhìn ai ạ?\" Tiểu Vương càng không hiểu.","Lúc ấy, xe buýt đến. Bà cụ mỉm cười với người tài xế, người tài xế cũng cười và gật đầu với bà.","\"Đó là con trai bà.\" Bà cụ vui vẻ nói. \"Nó bận việc lắm, mỗi năm chỉ về nhà được một lần. Nhưng sáng nào nó cũng lái chiếc xe này đi qua đây. Bà ra bến xe chính là để ngày nào cũng được nhìn nó một cái.\"","Hôm ấy lên xe rồi, Tiểu Vương cứ nhìn mưa ngoài cửa sổ. Một lúc sau, anh lấy điện thoại ra, gọi cho người mẹ mà đã lâu rồi anh không về thăm."],"questions":[{"q":"小王觉得老奶奶哪里很奇怪？","q_vi":"Tiểu Vương thấy bà cụ lạ ở điểm nào?","options":["她每天都穿新衣服","她每天来车站，可是从来不上车","她总是在车站唱歌","她每天坐车去很远的地方"],"answer":1,"explain_vi":"Đoạn 2: xe đến thì ai cũng lên, chỉ bà cụ không lên mà đứng nhìn xe đi."},{"q":"下大雨那天，小王做了什么？","q_vi":"Hôm trời mưa to, Tiểu Vương đã làm gì?","options":["送老奶奶回家","给老奶奶买了一把伞","把自己的伞给了老奶奶","没去上班"],"answer":2,"explain_vi":"Đoạn 4: Tiểu Vương đưa ô của mình cho bà cụ."},{"q":"老奶奶每天去车站是为了什么？","q_vi":"Bà cụ ra bến xe mỗi ngày để làm gì?","options":["看开车的儿子","等她的老朋友","坐车去医院","卖东西"],"answer":0,"explain_vi":"Đoạn 8: tài xế là con trai bà, bà ra bến để được nhìn con mỗi ngày."},{"q":"最后小王给妈妈打电话，最可能是因为：","q_vi":"Cuối cùng Tiểu Vương gọi điện cho mẹ, nhiều khả năng là vì:","options":["他忘了带伞","他上班要迟到了","妈妈给他打过很多电话","老奶奶的故事让他想起了自己的妈妈"],"answer":3,"explain_vi":"Câu chuyện của bà cụ về tình mẹ khiến anh nhớ tới mẹ mình, người đã lâu anh không về thăm – đây là câu hỏi suy luận."}],"beyond":[["手里","shǒu li","THỦ LÝ","trong tay"],["天下","tiānxià","THIÊN HẠ","thiên hạ · thiên hạ; thế gian; cả nước"],["一眼","yīyǎn","NHẤT NHÃN","một cái liếc mắt, một ánh nhìn, một mắt nhìn"]]},{"id":"h3-03","level":3,"title":"一盘特别的菜","title_vi":"Một đĩa thức ăn đặc biệt","topic":"nhật ký – gia đình","chars":409,"paragraphs":["三月八日 星期日 晴","今天是妈妈的生日。早上，妈妈有事去公司了。她刚出门，爸爸就小声对我说：“我们今天给妈妈做晚饭，让她高兴高兴，好不好？”我马上就同意了。","下午三点，我们去超市买了鱼、鸡蛋、西红柿和一些水果，还买了一个小蛋糕。回到家，爸爸说他做鱼，我做西红柿鸡蛋。这个菜我看妈妈做过很多次，我觉得一点儿也不难。","可是做起来我才发现，做饭真不简单！我一着急，把两个鸡蛋都打到了碗外面。爸爸那边也不太好，他做一条鱼就用了一个多小时，厨房里热得像夏天一样。最后，我们终于做好了三个菜，还把桌子也打扫得干干净净。","六点半，妈妈回来了。看到桌子上的菜和蛋糕，她非常高兴。她先吃了一口我做的西红柿鸡蛋，笑着说：“真好吃！有点儿甜，跟你外婆做的一样。”","我也吃了一口——啊，太甜了！我这才发现，我把糖当成了盐。我的脸一下子就红了。","可是妈妈笑着对我说：“别担心。我小时候第一次给你外婆做饭，也放错了。那天你外婆说的话，跟我今天说的一样。”爸爸听了，在旁边也笑了。","今天我明白了两件事：第一，做饭不是一件容易的事；第二，妈妈说菜好吃，不是因为它真的好吃，而是因为这个菜是我为她做的。"],"pinyin":["sān yuè bā rì xīng qī rì qíng","jīn tiān shì mā ma de shēng rì zǎo shang mā ma yǒu shì qù gōng sī le tā gāng chū mén bà ba jiù xiǎo shēng duì wǒ shuō wǒ men jīn tiān gěi mā ma zuò wǎn fàn ràng tā gāo xìng gāo xìng hǎo bù hǎo wǒ mǎ shàng jiù tóng yì le","xià wǔ sān diǎn wǒ men qù chāo shì mǎi le yú jī dàn xī hóng shì hé yī xiē shuǐ guǒ hái mǎi le yí gè xiǎo dàn gāo huí dào jiā bà ba shuō tā zuò yú wǒ zuò xī hóng shì jī dàn zhè ge cài wǒ kàn mā ma zuò guò hěn duō cì wǒ jué de yì diǎn ér yě bù nán","kě shì zuò qǐ lái wǒ cái fā xiàn zuò fàn zhēn bù jiǎn dān wǒ yī zháo jí bǎ liǎng gè jī dàn dōu dǎ dào le wǎn wài miàn bà ba nà biān yě bù tài hǎo tā zuò yī tiáo yú jiù yòng le yí gè duō xiǎo shí chú fáng lǐ rè dé xiàng xià tiān yī yàng zuì hòu wǒ men zhōng yú zuò hǎo le sān gè cài hái bǎ zhuō zi yě dǎ sǎo de gān gān jìng jìng","liù diǎn bàn mā ma huí lái le kàn dào zhuō zi shàng de cài hé dàn gāo tā fēi cháng gāo xìng tā xiān chī le yī kǒu wǒ zuò de xī hóng shì jī dàn xiào zhe shuō zhēn hǎo chī yǒu diǎn ér tián gēn nǐ wài pó zuò de yī yàng","wǒ yě chī le yī kǒu a tài tián le wǒ zhè cái fā xiàn wǒ bǎ táng dàng chéng le yán wǒ de liǎn yí xià zi jiù hóng le","kě shì mā ma xiào zhe duì wǒ shuō bié dān xīn wǒ xiǎo shí hou dì yī cì gěi nǐ wài pó zuò fàn yě fàng cuò le nà tiān nǐ wài pó shuō de huà gēn wǒ jīn tiān shuō de yī yàng bà ba tīng le zài páng biān yě xiào le","jīn tiān wǒ míng bai le liǎng jiàn shì dì yī zuò fàn bú shì yī jiàn róng yì de shì dì èr mā ma shuō cài hǎo chī bú shì yīn wèi tā zhēn de hǎo chī ér shì yīn wèi zhè ge cài shì wǒ wèi tā zuò de"],"translations":["Chủ nhật, ngày 8 tháng 3, trời nắng","Hôm nay là sinh nhật mẹ. Buổi sáng mẹ có việc phải lên công ty. Mẹ vừa ra khỏi nhà, bố đã nói nhỏ với tôi: \"Hôm nay hai bố con mình nấu một bữa tối cho mẹ, để mẹ vui một chút, được không?\" Tôi đồng ý ngay.","Ba giờ chiều, chúng tôi đi siêu thị mua cá, trứng, cà chua, ít hoa quả và một chiếc bánh kem nhỏ. Về đến nhà, bố bảo bố làm cá, còn tôi làm món cà chua xào trứng. Món này tôi đã xem mẹ làm rất nhiều lần, nên tôi thấy chẳng khó chút nào.","Nhưng bắt tay vào làm tôi mới nhận ra, nấu ăn thật không đơn giản! Tôi cuống lên, đập cả hai quả trứng ra ngoài bát. Bên phía bố cũng chẳng khá hơn, bố làm một con cá mà mất hơn một tiếng, căn bếp nóng như mùa hè. Cuối cùng, chúng tôi cũng làm xong ba món, còn lau dọn bàn sạch sẽ tinh tươm.","Sáu rưỡi mẹ về. Nhìn thấy thức ăn và bánh kem trên bàn, mẹ vui lắm. Mẹ ăn thử một miếng cà chua xào trứng tôi làm trước, rồi cười nói: \"Ngon quá! Hơi ngọt một chút, giống hệt bà ngoại con làm.\"","Tôi cũng ăn một miếng – trời ơi, ngọt quá! Lúc này tôi mới phát hiện mình đã nhầm đường thành muối. Mặt tôi đỏ bừng ngay lập tức.","Thế nhưng mẹ cười nói với tôi: \"Đừng lo. Hồi nhỏ lần đầu mẹ nấu cơm cho bà ngoại con, mẹ cũng nêm nhầm. Hôm đó bà ngoại nói với mẹ đúng y như những gì mẹ nói hôm nay.\" Bố nghe xong, ở bên cạnh cũng bật cười.","Hôm nay tôi hiểu ra hai điều: thứ nhất, nấu ăn không phải là việc dễ; thứ hai, mẹ khen món ăn ngon không phải vì nó thật sự ngon, mà vì đó là món tôi làm cho mẹ."],"questions":[{"q":"爸爸和“我”为什么要做晚饭？","q_vi":"Vì sao bố và \"tôi\" muốn nấu bữa tối?","options":["因为今天是妈妈的生日","因为妈妈生病了","因为家里没有饭馆","因为爸爸想学做菜"],"answer":0,"explain_vi":"Đoạn 2: hôm nay là sinh nhật mẹ, hai bố con muốn làm mẹ vui."},{"q":"“我”做的西红柿鸡蛋为什么很甜？","q_vi":"Vì sao món cà chua trứng \"tôi\" làm lại rất ngọt?","options":["因为放了很多水果","因为外婆告诉“我”要放糖","因为“我”把糖当成了盐","因为西红柿特别甜"],"answer":2,"explain_vi":"Đoạn 6: \"tôi\" nhầm đường thành muối."},{"q":"妈妈说“跟你外婆做的一样”，其实是什么意思？","q_vi":"Mẹ nói \"giống bà ngoại con làm\", thực ra có ý gì?","options":["外婆做菜比“我”好吃","妈妈小时候也犯过一样的错","外婆今天也来吃饭了","妈妈不喜欢吃甜的"],"answer":1,"explain_vi":"Đoạn 7: hồi nhỏ mẹ nấu cho bà ngoại cũng nêm nhầm – nên món \"ngọt\" giống bà ngoại là kỷ niệm của mẹ."},{"q":"这篇日记最想说的是什么？","q_vi":"Bài nhật ký này muốn nói điều gì nhất?","options":["西红柿鸡蛋很难做","爸爸做鱼做得很慢","去超市买东西要早点儿去","妈妈最高兴的是“我”为她做菜"],"answer":3,"explain_vi":"Đoạn cuối: mẹ khen ngon vì món đó do con làm cho mẹ – điều quý là tấm lòng."}],"beyond":[["有事","yǒushì","HỮU SỰ","bận việc, có chuyện, có việc bận"],["好不","hǎobù","HẢO BẤT","thật là, biết bao"],["西红柿","xī hóng shì","TÂY HỒNG THỊ","cà chua"],["多次","duō cì","ĐA THỨ","nhiều lần, nhiều"],["不难","bù nán","BẤT NAN","không khó"],["不简单","bù jiǎndān","BẤT GIẢN ĐƠN","không đơn giản, tài giỏi (không tầm thường, liễu bất khởi)"],["外婆","wàipó","NGOẠI BÀ","bà ngoại"],["当成","dàngchéng","ĐÁNG THÀNH","coi là, xem như là"],["盐","yán","DIÊM","muối"],["一下子","yīxiàzi","NHẤT HẠ TỬ","bỗng chốc, một thoáng, đột nhiên"],["而是","ér shì","NHI THỊ","mà là"]]},{"id":"h3-04","level":3,"title":"电梯坏了以后","title_vi":"Sau khi thang máy hỏng","topic":"xã hội – hàng xóm","chars":472,"paragraphs":["我家住在一个很高的楼里，一共有二十层。楼里住着一百多家人，可是我只认识住在旁边的一家。每天大家坐电梯上楼、下楼，在电梯里也很少说话，每个人都在看自己的手机。","上个星期一，电梯突然坏了。楼下的人说，最快也要一个星期才能修好。这下大家都着急了，特别是住在高层的人。","我家在十二层。第一天晚上，我提着一大包东西爬楼梯，爬到第八层的时候，我已经累得走不动了。这时候，一个年轻的男人从后面走上来，说：“我帮你拿吧，我住十五层，正好经过。”","第二天，我在楼梯上看见了一位老爷爷。他住在十八层，腿不太好，手里还拿着刚买的菜。我想起了那个帮过我的人，就走过去帮他拿菜，一边慢慢地走，一边和他说话。我这才知道，他一个人住，孩子们都在国外。","后来，楼里的人想了一个好办法：住在低层的人去超市的时候，就问问高层的邻居需要买什么，再帮他们带上来。每天晚上，楼梯上都很热闹，大家一边走一边说话，有的还在中间坐下来，一起喝一杯水，休息一会儿。","一个星期以后，电梯终于修好了。第一天坐电梯的时候，我发现电梯里的人不再只看手机了。大家都会笑着打招呼：“早！今天去哪儿啊？”“老爷爷，您的腿好点儿了吗？”","现在，我在这个楼里认识了很多人。有时候我想，电梯坏了的那个星期虽然很累，但是它让我们这些住得很近的人，第一次真的成了邻居。"],"pinyin":["wǒ jiā zhù zài yí gè hěn gāo de lóu lǐ yī gòng yǒu èr shí céng lóu lǐ zhù zhe yì bǎi duō jiā rén kě shì wǒ zhǐ rèn shi zhù zài páng biān de yī jiā měi tiān dà jiā zuò diàn tī shàng lóu xià lóu zài diàn tī lǐ yě hěn shǎo shuō huà měi gè rén dōu zài kàn zì jǐ de shǒu jī","shàng gè xīng qī yī diàn tī tū rán huài le lóu xià de rén shuō zuì kuài yě yào yí gè xīng qī cái néng xiū hǎo zhè xià dà jiā dōu zháo jí le tè bié shì zhù zài gāo céng de rén","wǒ jiā zài shí èr céng dì yī tiān wǎn shang wǒ tí zhe yī dà bāo dōng xi pá lóu tī pá dào dì bā céng de shí hou wǒ yǐ jīng lèi de zǒu bù dòng le zhè shí hou yí gè nián qīng de nán rén cóng hòu miàn zǒu shàng lái shuō wǒ bāng nǐ ná ba wǒ zhù shí wǔ céng zhèng hǎo jīng guò","dì èr tiān wǒ zài lóu tī shàng kàn jiàn le yī wèi lǎo yé ye tā zhù zài shí bā céng tuǐ bù tài hǎo shǒu lǐ hái ná zhe gāng mǎi de cài wǒ xiǎng qǐ le nà ge bāng guò wǒ de rén jiù zǒu guò qù bāng tā ná cài yī biān màn màn de zǒu yī biān hé tā shuō huà wǒ zhè cái zhī dao tā yí gè rén zhù hái zi men dōu zài guó wài","hòu lái lóu lǐ de rén xiǎng le yí gè hǎo bàn fǎ zhù zài dī céng de rén qù chāo shì de shí hou jiù wèn wèn gāo céng de lín jū xū yào mǎi shén me zài bāng tā men dài shàng lái měi tiān wǎn shang lóu tī shàng dōu hěn rè nao dà jiā yī biān zǒu yī biān shuō huà yǒu de hái zài zhōng jiān zuò xià lái yì qǐ hē yī bēi shuǐ xiū xī yī huì er","yí gè xīng qī yǐ hòu diàn tī zhōng yú xiū hǎo le dì yī tiān zuò diàn tī de shí hou wǒ fā xiàn diàn tī lǐ de rén bù zài zhǐ kàn shǒu jī le dà jiā dū huì xiào zhe dǎ zhāo hū zǎo jīn tiān qù nǎ ér a lǎo yé ye nín de tuǐ hǎo diǎn ér le ma","xiàn zài wǒ zài zhè ge lóu lǐ rèn shi le hěn duō rén yǒu shí hòu wǒ xiǎng diàn tī huài le de nà ge xīng qī suī rán hěn lèi dàn shì tā ràng wǒ men zhè xiē zhù de hěn jìn de rén dì yī cì zhēn de chéng le lín jū"],"translations":["Nhà tôi ở trong một tòa nhà rất cao, tổng cộng hai mươi tầng. Trong tòa nhà có hơn một trăm hộ, nhưng tôi chỉ quen nhà bên cạnh. Hằng ngày mọi người đi thang máy lên xuống, trong thang máy cũng rất ít nói chuyện, ai nấy đều cắm mặt vào điện thoại của mình.","Thứ Hai tuần trước, thang máy đột nhiên hỏng. Người ở tầng dưới nói nhanh nhất cũng phải một tuần mới sửa xong. Lần này ai cũng sốt ruột, nhất là những người sống ở tầng cao.","Nhà tôi ở tầng mười hai. Tối hôm đầu tiên, tôi xách một túi đồ to leo cầu thang, leo đến tầng tám thì đã mệt không bước nổi nữa. Lúc ấy, một người đàn ông trẻ từ phía sau đi lên, nói: \"Để tôi xách giúp cho, tôi ở tầng mười lăm, tiện đường.\"","Ngày thứ hai, tôi gặp một ông cụ trên cầu thang. Ông ở tầng mười tám, chân không được khỏe, tay còn cầm đồ ăn vừa mua. Tôi nhớ tới người đã giúp mình, liền bước tới xách giúp ông, vừa chậm rãi đi vừa trò chuyện với ông. Lúc ấy tôi mới biết ông sống một mình, con cái đều ở nước ngoài.","Sau đó, mọi người trong tòa nhà nghĩ ra một cách hay: người ở tầng thấp khi đi siêu thị thì hỏi hàng xóm tầng cao cần mua gì, rồi mang lên giúp. Tối nào cầu thang cũng rất náo nhiệt, mọi người vừa đi vừa nói chuyện, có người còn ngồi xuống giữa chừng, cùng uống cốc nước, nghỉ một lát.","Một tuần sau, thang máy cuối cùng cũng sửa xong. Ngày đầu tiên đi thang máy, tôi phát hiện mọi người trong thang không còn chỉ nhìn điện thoại nữa. Ai cũng cười chào nhau: \"Chào buổi sáng! Hôm nay đi đâu đấy?\" \"Ông ơi, chân ông đỡ hơn chưa ạ?\"","Bây giờ tôi đã quen rất nhiều người trong tòa nhà này. Có lúc tôi nghĩ, tuần thang máy hỏng tuy rất mệt, nhưng nó đã khiến những người sống rất gần nhau như chúng tôi lần đầu tiên thật sự trở thành hàng xóm."],"questions":[{"q":"电梯坏了以前，楼里的人在电梯里常常做什么？","q_vi":"Trước khi thang máy hỏng, mọi người trong tòa nhà thường làm gì trong thang máy?","options":["一起聊天","看自己的手机","帮别人拿东西","唱歌"],"answer":1,"explain_vi":"Đoạn 1: trong thang máy ít nói chuyện, ai cũng nhìn điện thoại của mình."},{"q":"“我”为什么帮老爷爷拿菜？","q_vi":"Vì sao \"tôi\" xách đồ ăn giúp ông cụ?","options":["因为老爷爷是“我”的爷爷","因为老爷爷给了“我”钱","因为“我”想起了别人也帮过自己","因为“我”也住在十八层"],"answer":2,"explain_vi":"Đoạn 4: \"tôi\" nhớ đến người đàn ông trẻ đã giúp mình hôm trước."},{"q":"楼里的人想了一个什么办法？","q_vi":"Mọi người trong tòa nhà đã nghĩ ra cách gì?","options":["自己修电梯","都搬到低层去住","不去超市买东西","低层的人帮高层的邻居带东西"],"answer":3,"explain_vi":"Đoạn 5: người ở tầng thấp đi siêu thị thì mua giúp và mang đồ lên cho hàng xóm tầng cao."},{"q":"作者最想告诉我们的是：","q_vi":"Điều tác giả muốn nói nhất là:","options":["一件坏事让邻居们真正认识了","住高楼很不方便","电梯应该常常检查","爬楼梯是很好的锻炼"],"answer":0,"explain_vi":"Đoạn cuối: tuần thang máy hỏng khiến mọi người lần đầu thật sự trở thành hàng xóm."}],"beyond":[["上楼","shàng lóu","THƯỢNG LÂU","lên tầng"],["下楼","xià lóu","HẠ LÂU","xuống lầu, xuống tầng dưới"],["高层","gāocéng","CAO TẦNG","tầng cao; cấp cao, lãnh đạo cấp cao"],["楼梯","lóutī","LÂU THÊ","cầu thang · cầu thang, thang bộ"],["手里","shǒu li","THỦ LÝ","trong tay"],["热闹","rè nào","NHIỆT NÁO","náo nhiệt · ồn ào náo nhiệt, sôi động; náo nhiệt"],["不再","bùzài","BẤT TÁI","không còn nữa, không lặp lại"],["打招呼","dǎ zhāo hū","ĐẢ CHIÊU HÔ","chào hỏi · chào, chào hỏi nhau (lúc gặp mặt gọi hoặc nói \"xin chào\", \"này\", hoặc thông qua động tác…"],["有时","yǒushí","HỮU THỜI","có lúc"]]},{"id":"h3-05","level":3,"title":"熊猫为什么总是在吃？","title_vi":"Vì sao gấu trúc lúc nào cũng ăn?","topic":"khoa học thường thức","chars":448,"paragraphs":["大熊猫是一种只住在中国的动物。它们的身体是黑白两种颜色，眼睛旁边是黑色的，看起来好像总是没睡好觉。很多人第一次见到熊猫，都会说：“太可爱了！”","熊猫最喜欢吃竹子。一只大熊猫一天要吃十几公斤竹子，一天里有一半的时间都在吃东西。除了吃，它们最喜欢做的事情就是睡觉。","为什么熊猫要吃这么多呢？其实，竹子对熊猫来说不是很好的东西。熊猫吃下去的竹子，身体只能用到很少的一点儿，所以它们必须多吃一些，才能不饿。","更有意思的是，很久很久以前，熊猫是吃肉的。后来，因为环境变了，能吃的肉越来越少，它们才慢慢地开始吃竹子。可是到了今天，熊猫的身体还是更像吃肉的动物，所以吃竹子对它们来说不是一件容易的事。","也是因为这样，熊猫不太喜欢运动。它们走路很慢，很少跑，也很少爬到很高的地方。这样做，它们就不会很快饿了。","熊猫妈妈一般一次只生一个孩子。刚出生的熊猫非常小，和一个苹果差不多大，身上几乎没有黑色。你很难想到，这么小的孩子，以后会长成一百多公斤的大熊猫。","今天，世界上很多国家的动物园里都有大熊猫。它们是中国送给世界的朋友，也是很多孩子最喜欢的动物。下次你去动物园看熊猫的时候，如果它正在吃竹子，别觉得它太胖，它只是在努力“工作”呢！"],"pinyin":["dà xióng māo shì yī zhǒng zhǐ zhù zài zhōng guó de dòng wù tā men de shēn tǐ shì hēi bái liǎng zhǒng yán sè yǎn jing páng biān shì hēi sè de kàn qǐ lái hǎo xiàng zǒng shì méi shuì hǎo jué hěn duō rén dì yī cì jiàn dào xióng māo dū huì shuō tài kě ài le","xióng māo zuì xǐ huan chī zhú zi yī zhī dà xióng māo yī tiān yào chī shí jǐ gōng jīn zhú zi yī tiān lǐ yǒu yí bàn de shí jiān dōu zài chī dōng xi chú le chī tā men zuì xǐ huan zuò de shì qing jiù shì shuì jiào","wèi shén me xióng māo yào chī zhè me duō ne qí shí zhú zi duì xióng māo lái shuō bú shì hěn hǎo de dōng xi xióng māo chī xià qù de zhú zi shēn tǐ zhǐ néng yòng dào hěn shǎo de yì diǎn ér suǒ yǐ tā men bì xū duō chī yī xiē cái néng bù è","gèng yǒu yì si de shì hěn jiǔ hěn jiǔ yǐ qián xióng māo shì chī ròu de hòu lái yīn wèi huán jìng biàn le néng chī de ròu yuè lái yuè shǎo tā men cái màn màn de kāi shǐ chī zhú zi kě shì dào le jīn tiān xióng māo de shēn tǐ hái shì gèng xiàng chī ròu de dòng wù suǒ yǐ chī zhú zi duì tā men lái shuō bú shì yī jiàn róng yì de shì","yě shì yīn wèi zhè yàng xióng māo bù tài xǐ huan yùn dòng tā men zǒu lù hěn màn hěn shǎo pǎo yě hěn shǎo pá dào hěn gāo de dì fang zhè yàng zuò tā men jiù bú huì hěn kuài è le","xióng māo mā ma yì bān yī cì zhǐ shēng yí gè hái zi gāng chū shēng de xióng māo fēi cháng xiǎo hé yí gè píng guǒ chà bu duō dà shēn shàng jī hū méi yǒu hēi sè nǐ hěn nán xiǎng dào zhè me xiǎo de hái zi yǐ hòu huì zhǎng chéng yì bǎi duō gōng jīn de dà xióng māo","jīn tiān shì jiè shàng hěn duō guó jiā de dòng wù yuán lǐ dōu yǒu dà xióng māo tā men shì zhōng guó sòng gěi shì jiè de péng you yě shì hěn duō hái zi zuì xǐ huan de dòng wù xià cì nǐ qù dòng wù yuán kàn xióng māo de shí hou rú guǒ tā zhèng zài chī zhú zi bié jué de tā tài pàng tā zhǐ shì zài nǔ lì gōng zuò ne"],"translations":["Gấu trúc lớn là một loài động vật chỉ sống ở Trung Quốc. Cơ thể chúng có hai màu đen trắng, quanh mắt màu đen, trông như lúc nào cũng thiếu ngủ. Nhiều người lần đầu nhìn thấy gấu trúc đều thốt lên: \"Dễ thương quá!\"","Gấu trúc thích ăn tre nhất. Một con gấu trúc lớn mỗi ngày ăn hơn mười cân tre, một nửa thời gian trong ngày là để ăn. Ngoài ăn ra, việc chúng thích làm nhất là ngủ.","Vì sao gấu trúc phải ăn nhiều như vậy? Thật ra, với gấu trúc, tre không phải là thức ăn tốt lắm. Tre gấu trúc ăn vào, cơ thể chỉ dùng được một phần rất nhỏ, nên chúng buộc phải ăn nhiều hơn mới không bị đói.","Thú vị hơn nữa là, rất rất lâu về trước, gấu trúc ăn thịt. Về sau, vì môi trường thay đổi, thịt có thể ăn ngày càng ít, chúng mới dần dần chuyển sang ăn tre. Nhưng đến tận hôm nay, cơ thể gấu trúc vẫn giống động vật ăn thịt hơn, nên ăn tre đối với chúng không phải chuyện dễ dàng.","Cũng vì vậy mà gấu trúc không thích vận động lắm. Chúng đi rất chậm, ít khi chạy, cũng ít khi trèo lên chỗ cao. Làm như vậy chúng sẽ không nhanh đói.","Gấu trúc mẹ thường mỗi lứa chỉ sinh một con. Gấu trúc con mới sinh rất nhỏ, to cỡ một quả táo, trên người hầu như chưa có màu đen. Bạn khó mà ngờ rằng một chú gấu nhỏ như thế sau này sẽ lớn thành con gấu trúc nặng hơn một trăm cân.","Ngày nay, vườn thú ở nhiều nước trên thế giới đều có gấu trúc. Chúng là những người bạn Trung Quốc gửi tặng thế giới, cũng là loài vật nhiều trẻ em yêu thích nhất. Lần sau đi vườn thú xem gấu trúc, nếu nó đang ăn tre, đừng nghĩ nó béo quá nhé, nó chỉ đang chăm chỉ \"làm việc\" thôi!"],"questions":[{"q":"熊猫一天大概用多少时间吃东西？","q_vi":"Mỗi ngày gấu trúc dành khoảng bao nhiêu thời gian để ăn?","options":["一个小时","两三个小时","一天里一半的时间","差不多一整天都不吃"],"answer":2,"explain_vi":"Đoạn 2: một nửa thời gian trong ngày gấu trúc dành để ăn."},{"q":"熊猫为什么要吃很多竹子？","q_vi":"Vì sao gấu trúc phải ăn nhiều tre?","options":["因为身体只能用到竹子的很少一部分","因为竹子特别好吃","因为它们每天运动很多","因为动物园要求它们吃"],"answer":0,"explain_vi":"Đoạn 3: cơ thể gấu trúc chỉ dùng được rất ít từ tre nên phải ăn nhiều mới no."},{"q":"根据文章，下面哪句话是对的？","q_vi":"Theo bài, câu nào dưới đây đúng?","options":["熊猫一直都是吃竹子的","刚出生的熊猫和苹果差不多大","熊猫很喜欢跑和爬高","熊猫妈妈一次生很多孩子"],"answer":1,"explain_vi":"Đoạn 6: gấu trúc con mới sinh to cỡ quả táo. Các ý khác đều trái với bài."},{"q":"最后一段说熊猫在努力“工作”，意思是：","q_vi":"Đoạn cuối nói gấu trúc đang chăm chỉ \"làm việc\", ý là:","options":["熊猫在动物园里上班","熊猫在帮人做事","熊猫想变得更胖","多吃竹子是熊猫必须做的事"],"answer":3,"explain_vi":"Vì tre ít dinh dưỡng, ăn nhiều là việc bắt buộc để sống – tác giả nói vui đó là \"công việc\" của gấu trúc."}],"beyond":[["大熊猫","dàxióngmāo","ĐẠI HÙNG MIÊU","gấu trúc"],["黑白","hēibái","HẮC BẠCH","đen trắng; đúng sai phải trái"],["竹子","zhú zi","TRÚC TỬ","cây trúc"],["会长","huìzhǎng","HỘI TRƯỞNG","hội trưởng, chủ tịch hội"]]},{"id":"h4-01","level":4,"title":"爷爷的红包","title_vi":"Bao lì xì của ông nội","topic":"văn hóa – phong tục","chars":658,"paragraphs":["春节是中国最重要的节日。每到春节，不管离家多远，人们都会想办法回到父母身边，和家人一起吃年夜饭、看电视、聊天。对孩子们来说，春节最让人兴奋的事情，大概就是收红包了。","红包就是一个红色的小纸袋，里面放着钱。一般是年纪大的人给年纪小的人，比如爷爷奶奶给孙子孙女，父母给孩子。在中国人看来，红色能带来好运气，所以红包不只是钱，还是大人对孩子的祝福：希望他们在新的一年里健康、平安、快乐。","我小时候，每年除夕晚上，爷爷都会把我叫到他身边，从口袋里拿出一个红包，认真地对我说：“又长大一岁了，要好好学习，听爸爸妈妈的话。”那时候红包里的钱并不多，可是我总是把它放在床边的小盒子里，过好几天才打开。","这几年，过年的方式发生了很大的变化。很多人开始用手机发红包。除夕晚上，我们一家人有一个微信群，大家一边看春节晚会，一边在群里“抢红包”。红包里的钱也许只有几块，但是抢到的人会特别高兴，没抢到的人就大声叫：“再发一个！”整个客厅都是笑声。","只有爷爷不参加。他说自己年纪大了，看不清手机上的字，也学不会这些新东西。每次大家抢红包的时候，他就坐在沙发上，笑着看我们。我发现，他的笑里好像有一点儿孤单。","去年春节前，我决定教爷爷用手机发红包。一开始，他总是按错，有一次还差点儿把一千块发给了一个不认识的人。我耐心地教了他一遍又一遍，还把每一步都写在一张纸上，放在他的桌子上。","除夕那天晚上，正当大家聊得热闹的时候，手机上突然出现了一个红包，上面写着：“爷爷祝大家新年快乐！”整个客厅一下子安静了，接着大家都叫了起来。那是爷爷第一次在手机上发红包。","我打开红包，里面只有八块八毛八。可是对我来说，这是我收到过的最特别的红包。我突然明白了：红包的样子可以变，里面的钱可以多，也可以少，但是一家人互相关心的那份心意，是永远不会变的。"],"pinyin":["chūn jié shì zhōng guó zuì zhòng yào de jié rì měi dào chūn jié bù guǎn lí jiā duō yuǎn rén men dū huì xiǎng bàn fǎ huí dào fù mǔ shēn biān hé jiā rén yì qǐ chī nián yè fàn kàn diàn shì liáo tiān duì hái zi men lái shuō chūn jié zuì ràng rén xīng fèn de shì qing dà gài jiù shì shōu hóng bāo le","hóng bāo jiù shì yí gè hóng sè de xiǎo zhǐ dài lǐ miàn fàng zhe qián yì bān shì nián jì dà de rén gěi nián jì xiǎo de rén bǐ rú yé ye nǎi nai gěi sūn zi sūn nǚ fù mǔ gěi hái zi zài zhōng guó rén kàn lái hóng sè néng dài lái hǎo yùn qì suǒ yǐ hóng bāo bù zhǐ shì qián hái shì dà rén duì hái zi de zhù fú xī wàng tā men zài xīn de yī nián lǐ jiàn kāng píng ān kuài lè","wǒ xiǎo shí hou měi nián chú xī wǎn shang yé ye dū huì bǎ wǒ jiào dào tā shēn biān cóng kǒu dài lǐ ná chū yí gè hóng bāo rèn zhēn de duì wǒ shuō yòu zhǎng dà yī suì le yào hǎo hǎo xué xí tīng bà ba mā ma de huà nà shí hou hóng bāo lǐ de qián bìng bù duō kě shì wǒ zǒng shì bǎ tā fàng zài chuáng biān de xiǎo hé zi lǐ guò hǎo jǐ tiān cái dǎ kāi","zhè jǐ nián guò nián de fāng shì fā shēng le hěn dà de biàn huà hěn duō rén kāi shǐ yòng shǒu jī fā hóng bāo chú xī wǎn shang wǒ men yī jiā rén yǒu yí gè wēi xìn qún dà jiā yī biān kàn chūn jié wǎn huì yī biān zài qún lǐ qiǎng hóng bāo hóng bāo lǐ de qián yě xǔ zhǐ yǒu jǐ kuài dàn shì qiǎng dào de rén huì tè bié gāo xìng méi qiǎng dào de rén jiù dà shēng jiào zài fā yí gè zhěng gè kè tīng dōu shì xiào shēng","zhǐ yǒu yé ye bù cān jiā tā shuō zì jǐ nián jì dà le kàn bù qīng shǒu jī shàng de zì yě xué bú huì zhè xiē xīn dōng xi měi cì dà jiā qiǎng hóng bāo de shí hou tā jiù zuò zài shā fā shàng xiào zhe kàn wǒ men wǒ fā xiàn tā de xiào lǐ hǎo xiàng yǒu yì diǎn ér gū dān","qù nián chūn jié qián wǒ jué dìng jiào yé ye yòng shǒu jī fā hóng bāo yī kāi shǐ tā zǒng shì àn cuò yǒu yī cì hái chà diǎn ér bǎ yī qiān kuài fā gěi le yí gè bù rèn shi de rén wǒ nài xīn dì jiào le tā yī biàn yòu yī biàn hái bǎ měi yī bù dōu xiě zài yī zhāng zhǐ shàng fàng zài tā de zhuō zi shàng","chú xī nà tiān wǎn shang zhèng dāng dà jiā liáo dé rè nao de shí hou shǒu jī shàng tū rán chū xiàn le yí gè hóng bāo shàng miàn xiě zhe yé ye zhù dà jiā xīn nián kuài lè zhěng gè kè tīng yí xià zi ān jìng le jiē zhe dà jiā dōu jiào le qǐ lái nà shì yé ye dì yī cì zài shǒu jī shàng fā hóng bāo","wǒ dǎ kāi hóng bāo lǐ miàn zhǐ yǒu bā kuài bā máo bā kě shì duì wǒ lái shuō zhè shì wǒ shōu dào guò de zuì tè bié de hóng bāo wǒ tū rán míng bai le hóng bāo de yàng zi kě yǐ biàn lǐ miàn de qián kě yǐ duō yě kě yǐ shǎo dàn shì yī jiā rén hù xiāng guān xīn de nà fèn xīn yì shì yǒng yuǎn bú huì biàn de"],"translations":["Tết Nguyên đán là ngày lễ quan trọng nhất của Trung Quốc. Mỗi dịp Tết đến, dù xa nhà đến đâu, mọi người cũng tìm cách trở về bên cha mẹ, cùng gia đình ăn bữa cơm tất niên, xem tivi, trò chuyện. Với trẻ con, điều khiến chúng háo hức nhất ngày Tết có lẽ là được nhận lì xì.","Bao lì xì là một chiếc túi giấy nhỏ màu đỏ, bên trong đựng tiền. Thường là người lớn tuổi cho người nhỏ tuổi, chẳng hạn ông bà cho cháu, cha mẹ cho con. Theo quan niệm của người Trung Quốc, màu đỏ tượng trưng cho may mắn, nên bao lì xì không chỉ là tiền mà còn là lời chúc của người lớn dành cho trẻ nhỏ: mong các con một năm mới khỏe mạnh, bình an, vui vẻ.","Hồi nhỏ, tối giao thừa năm nào ông nội cũng gọi tôi lại bên cạnh, lấy từ túi áo ra một bao lì xì, nghiêm túc dặn: \"Lại lớn thêm một tuổi rồi, phải chăm học, nghe lời bố mẹ.\" Hồi ấy tiền trong bao không nhiều, nhưng tôi luôn cất nó trong chiếc hộp nhỏ cạnh giường, mấy ngày sau mới mở ra.","Mấy năm gần đây, cách đón Tết đã thay đổi rất nhiều. Nhiều người bắt đầu gửi lì xì qua điện thoại. Tối giao thừa, cả nhà tôi có một nhóm WeChat, mọi người vừa xem chương trình Gala mừng xuân vừa \"giành lì xì\" trong nhóm. Tiền trong bao có khi chỉ vài đồng, nhưng ai giành được thì vui lắm, ai không giành được thì hét to: \"Phát cái nữa đi!\" Cả phòng khách rộn tiếng cười.","Chỉ có ông là không tham gia. Ông nói mình già rồi, không nhìn rõ chữ trên điện thoại, cũng không học nổi mấy thứ mới mẻ này. Mỗi lần mọi người giành lì xì, ông lại ngồi trên sofa cười nhìn chúng tôi. Tôi nhận ra trong nụ cười ấy dường như có chút cô đơn.","Trước Tết năm ngoái, tôi quyết định dạy ông gửi lì xì bằng điện thoại. Lúc đầu ông toàn bấm nhầm, có lần suýt nữa gửi một nghìn tệ cho một người lạ. Tôi kiên nhẫn dạy ông hết lần này đến lần khác, còn viết từng bước ra một tờ giấy, đặt trên bàn của ông.","Tối giao thừa hôm ấy, đúng lúc mọi người đang trò chuyện rôm rả, trên điện thoại bỗng xuất hiện một bao lì xì, trên đó viết: \"Ông chúc cả nhà năm mới vui vẻ!\" Cả phòng khách lập tức im phăng phắc, rồi ai nấy đều reo lên. Đó là lần đầu tiên ông gửi lì xì trên điện thoại.","Tôi mở bao lì xì, bên trong chỉ có tám tệ tám hào tám xu. Nhưng với tôi, đó là bao lì xì đặc biệt nhất tôi từng nhận. Tôi chợt hiểu ra: hình thức bao lì xì có thể thay đổi, tiền bên trong có thể nhiều hay ít, nhưng tấm lòng quan tâm lẫn nhau của người một nhà thì mãi mãi không thay đổi."],"questions":[{"q":"根据文章，人们为什么喜欢用红色的纸袋装钱？","q_vi":"Theo bài, vì sao người ta thích dùng túi giấy màu đỏ để đựng tiền?","options":["因为红色的纸袋比较便宜","因为红色代表好运气","因为孩子们最喜欢红色","因为红色的纸袋不容易丢"],"answer":1,"explain_vi":"Đoạn 2: màu đỏ tượng trưng cho may mắn, nên bao lì xì còn là lời chúc."},{"q":"爷爷以前为什么不参加“抢红包”？","q_vi":"Trước đây vì sao ông không tham gia \"giành lì xì\"?","options":["他不会用手机发红包","他觉得抢红包很浪费钱","他不喜欢热闹","他要去厨房做饭"],"answer":0,"explain_vi":"Đoạn 5: ông nói mình già, nhìn không rõ chữ, không học được thứ mới – tức là không biết dùng."},{"q":"“我发现，他的笑里好像有一点儿孤单”，这说明：","q_vi":"\"Tôi nhận ra trong nụ cười của ông dường như có chút cô đơn\" cho thấy:","options":["爷爷身体不舒服","爷爷对“我”很生气","爷爷其实也想参加大家的活动","爷爷不喜欢过春节"],"answer":2,"explain_vi":"Ông ngồi nhìn mọi người vui mà không tham gia được, nên có chút cô đơn – ông thật ra cũng muốn hòa vào."},{"q":"作者为什么说八块八毛八的红包“最特别”？","q_vi":"Vì sao tác giả nói bao lì xì 8,88 tệ là \"đặc biệt nhất\"?","options":["因为数字“八”能带来很多钱","因为那是爷爷最后一次给红包","因为别人都没抢到","因为它包含了爷爷努力学习后对家人的关心"],"answer":3,"explain_vi":"Ông đã cố học cách gửi lì xì để chúc cả nhà – giá trị nằm ở tấm lòng, không ở số tiền."}],"beyond":[["年夜饭","niányèfàn","NIÊN DẠ PHẠN","cơm tất niên"],["好运","hǎoyùn","HẢO VẬN","may mắn; vận may"],["除夕","chú xī","TRỪ TỊCH","giao thừa · đêm giao thừa; giao thừa"],["一家人","yījiārén","NHẤT GIA NHÂN","người một nhà, cả gia đình"],["抢","qiǎng","THƯƠNG","cướp · cướp, tranh, giật; giành trước; gấp gáp, tranh thủ thời gian; cướp"],["笑声","xiàoshēng","TIẾU THANH","tiếng cười"],["孤单","gūdān","CÔ ĐƠN","cô đơn; cô độc; lẻ loi"],["一下子","yīxiàzi","NHẤT HẠ TỬ","bỗng chốc, một thoáng, đột nhiên"],["心意","xīnyì","TÂM Ý","tấm lòng, thành ý, tâm ý"]]},{"id":"h4-02","level":4,"title":"网上的“老李”","title_vi":"\"Lão Lý\" trên mạng","topic":"truyện ngắn","chars":665,"paragraphs":["张明今年二十八岁，在上海一家公司做程序员。他每天早上九点上班，晚上常常十点以后才能下班。回到租的房子里，他累得什么都不想做，只想一个人安安静静地下一盘棋。","他是在一个下棋的网站上认识“老李”的。老李的棋下得不算特别好，但是很有耐心，从来不着急。两个人下了几次以后，就开始一边下棋一边聊天。","慢慢地，张明发现自己什么都想跟老李说：工作压力大，经理总是批评他；女朋友跟他分手了；房租又贵了……老李总是安静地听，然后说一些很简单的话：“别着急，事情会慢慢好起来的。”“工作再忙，饭也要按时吃。”这些话不特别，可是张明每次听了，心里都觉得很温暖。","有一次，张明问老李：“你是做什么工作的？”老李说：“我已经退休了，在一个小城市住，每天就是看看书，散散步。”张明又问：“那你有孩子吗？”过了很久，老李才回答：“有一个儿子，在外地工作，很少回家。我们俩都不太会说话，一打电话就不知道说什么。”","张明看着这句话，想起了自己的父亲。他已经快一年没回家了。每次父亲打电话来，问的总是那几个问题：“吃饭了吗？”“工作累不累？”他总是回答“挺好的”，然后就说自己很忙，挂了电话。","国庆节放假，张明终于决定回家一趟。走之前，他跟老李说：“我要回老家几天，可能没时间下棋了。”老李马上回答：“好啊！回家好！多陪陪你爸爸。”","回到家的那天晚上，母亲做了一桌子他爱吃的菜。吃完饭，父亲像平时一样走进书房。张明经过书房门口的时候，看见父亲正戴着眼镜，认真地看着电脑。电脑上是一个他非常熟悉的网站——那个下棋的网站。","他愣住了。父亲的用户名，正是“老李”。原来，父亲不知道怎么跟儿子聊天，就让儿子的表妹打听到了张明常去的网站，又花了两个月学会了下棋。父亲转过头，看见站在门口的儿子，有点儿不好意思地笑了：“我……我就是想知道你过得好不好。”","那天晚上，父子俩在书房里坐了很久。这一次，他们没有在网上，而是面对面地下了一盘棋。"],"pinyin":["zhāng míng jīn nián èr shí bā suì zài shàng hǎi yī jiā gōng sī zuò chéng xù yuán tā měi tiān zǎo shang jiǔ diǎn shàng bān wǎn shang cháng cháng shí diǎn yǐ hòu cái néng xià bān huí dào zū de fáng zi lǐ tā lèi dé shén me dōu bù xiǎng zuò zhǐ xiǎng yí gè rén ān ān jìng jìng dì xià yī pán qí","tā shì zài yí gè xià qí de wǎng zhàn shàng rèn shi lǎo lǐ de lǎo lǐ de qí xià de bù suàn tè bié hǎo dàn shì hěn yǒu nài xīn cóng lái bù zháo jí liǎng gè rén xià le jǐ cì yǐ hòu jiù kāi shǐ yī biān xià qí yī biān liáo tiān","màn màn de zhāng míng fā xiàn zì jǐ shén me dōu xiǎng gēn lǎo lǐ shuō gōng zuò yā lì dà jīng lǐ zǒng shì pī píng tā nǚ péng yǒu gēn tā fēn shǒu le fáng zū yòu guì le lǎo lǐ zǒng shì ān jìng de tīng rán hòu shuō yī xiē hěn jiǎn dān de huà bié zháo jí shì qing huì màn màn hǎo qǐ lái de gōng zuò zài máng fàn yě yào àn shí chī zhè xiē huà bù tè bié kě shì zhāng míng měi cì tīng le xīn lǐ dōu jué de hěn wēn nuǎn","yǒu yī cì zhāng míng wèn lǎo lǐ nǐ shì zuò shén me gōng zuò de lǎo lǐ shuō wǒ yǐ jīng tuì xiū le zài yí gè xiǎo chéng shì zhù měi tiān jiù shì kàn kàn shū sàn sàn bù zhāng míng yòu wèn nà nǐ yǒu hái zi ma guò le hěn jiǔ lǎo lǐ cái huí dá yǒu yí gè ér zi zài wài dì gōng zuò hěn shǎo huí jiā wǒ men liǎ dōu bù tài huì shuō huà yī dǎ diàn huà jiù bù zhī dao shuō shén me","zhāng míng kàn zhe zhè jù huà xiǎng qǐ le zì jǐ de fù qīn tā yǐ jīng kuài yī nián méi huí jiā le měi cì fù qīn dǎ diàn huà lái wèn de zǒng shì nà jǐ gè wèn tí chī fàn le ma gōng zuò lèi bù lèi tā zǒng shì huí dá tǐng hǎo de rán hòu jiù shuō zì jǐ hěn máng guà le diàn huà","guó qìng jié fàng jià zhāng míng zhōng yú jué dìng huí jiā yī tàng zǒu zhī qián tā gēn lǎo lǐ shuō wǒ yào huí lǎo jiā jǐ tiān kě néng méi shí jiān xià qí le lǎo lǐ mǎ shàng huí dá hǎo a huí jiā hǎo duō péi péi nǐ bà ba","huí dào jiā de nà tiān wǎn shang mǔ qīn zuò le yī zhuō zi tā ài chī de cài chī wán fàn fù qīn xiàng píng shí yī yàng zǒu jìn shū fáng zhāng míng jīng guò shū fáng mén kǒu de shí hou kàn jiàn fù qīn zhèng dài zhe yǎn jìng rèn zhēn de kàn zhe diàn nǎo diàn nǎo shàng shì yí gè tā fēi cháng shú xī de wǎng zhàn nà ge xià qí de wǎng zhàn","tā lèng zhù le fù qīn de yòng hù míng zhèng shì lǎo lǐ yuán lái fù qīn bù zhī dao zěn me gēn ér zi liáo tiān jiù ràng ér zi de biǎo mèi dǎ tīng dào le zhāng míng cháng qù de wǎng zhàn yòu huā le liǎng gè yuè xué huì le xià qí fù qīn zhuǎn guò tóu kàn jiàn zhàn zài mén kǒu de ér zi yǒu diǎn ér bù hǎo yì sī dì xiào le wǒ wǒ jiù shì xiǎng zhī dao nǐ guò de hǎo bù hǎo","nà tiān wǎn shang fù zǐ liǎ zài shū fáng lǐ zuò le hěn jiǔ zhè yī cì tā men méi yǒu zài wǎng shàng ér shì miàn duì miàn dì xià le yī pán qí"],"translations":["Trương Minh năm nay hai mươi tám tuổi, làm lập trình viên ở một công ty tại Thượng Hải. Sáng nào anh cũng đi làm lúc chín giờ, tối thường sau mười giờ mới tan làm. Về đến căn phòng thuê, anh mệt đến mức chẳng muốn làm gì, chỉ muốn một mình yên lặng chơi một ván cờ.","Anh quen \"Lão Lý\" trên một trang web chơi cờ. Lão Lý chơi cờ không hẳn là giỏi, nhưng rất kiên nhẫn, chưa bao giờ vội vàng. Hai người chơi vài lần, rồi bắt đầu vừa chơi cờ vừa trò chuyện.","Dần dần, Trương Minh thấy chuyện gì mình cũng muốn kể với Lão Lý: áp lực công việc lớn, sếp hay phê bình anh; bạn gái chia tay anh; tiền thuê nhà lại đắt hơn… Lão Lý luôn lặng lẽ lắng nghe, rồi nói vài câu rất đơn giản: \"Đừng vội, mọi chuyện rồi sẽ dần tốt lên.\" \"Bận mấy cũng phải ăn cơm đúng giờ.\" Những câu ấy không có gì đặc biệt, nhưng mỗi lần nghe, Trương Minh đều thấy lòng ấm áp.","Có lần Trương Minh hỏi Lão Lý: \"Bác làm nghề gì ạ?\" Lão Lý đáp: \"Tôi nghỉ hưu rồi, sống ở một thành phố nhỏ, ngày nào cũng chỉ đọc sách, đi dạo.\" Trương Minh lại hỏi: \"Thế bác có con không?\" Một lúc lâu sau Lão Lý mới trả lời: \"Có một thằng con trai, làm việc ở tỉnh khác, ít khi về nhà. Hai bố con đều không giỏi ăn nói, cứ gọi điện là chẳng biết nói gì.\"","Trương Minh nhìn câu ấy, nhớ tới bố mình. Đã gần một năm anh không về nhà. Mỗi lần bố gọi điện, hỏi lúc nào cũng mấy câu ấy: \"Ăn cơm chưa?\" \"Công việc có mệt không?\" Anh luôn trả lời \"Ổn cả ạ\", rồi bảo mình bận, cúp máy.","Nghỉ lễ Quốc khánh, Trương Minh cuối cùng cũng quyết định về nhà một chuyến. Trước khi đi, anh nói với Lão Lý: \"Cháu về quê mấy hôm, chắc không có thời gian chơi cờ.\" Lão Lý trả lời ngay: \"Tốt quá! Về nhà là tốt! Ở bên bố cháu nhiều vào.\"","Tối hôm về đến nhà, mẹ nấu cả một bàn đầy món anh thích. Ăn xong, bố như thường lệ đi vào phòng sách. Lúc Trương Minh đi ngang cửa phòng sách, anh thấy bố đang đeo kính, chăm chú nhìn máy tính. Trên màn hình là một trang web anh vô cùng quen thuộc – chính là trang web chơi cờ ấy.","Anh sững người. Tên tài khoản của bố chính là \"Lão Lý\". Hóa ra bố không biết trò chuyện với con thế nào, bèn nhờ cô em họ của anh dò hỏi trang web anh hay vào, rồi bỏ ra hai tháng học chơi cờ. Bố quay đầu lại, thấy con trai đứng ở cửa, hơi ngượng ngùng mỉm cười: \"Bố… bố chỉ muốn biết con sống có tốt không.\"","Tối hôm đó, hai bố con ngồi trong phòng sách rất lâu. Lần này họ không chơi trên mạng, mà ngồi đối diện nhau đánh một ván cờ."],"questions":[{"q":"张明为什么喜欢跟老李聊天？","q_vi":"Vì sao Trương Minh thích trò chuyện với Lão Lý?","options":["老李能帮他找到新工作","老李很耐心，他的话让张明觉得温暖","老李的棋下得特别好","老李给他介绍了女朋友"],"answer":1,"explain_vi":"Đoạn 2–3: Lão Lý kiên nhẫn lắng nghe, những lời giản dị khiến anh thấy ấm lòng."},{"q":"老李说自己和儿子“一打电话就不知道说什么”，张明听了以后想到了什么？","q_vi":"Lão Lý nói hai bố con \"cứ gọi điện là không biết nói gì\", Trương Minh nghe xong nghĩ đến điều gì?","options":["自己的经理","自己的女朋友","老李住的城市","自己和父亲的关系"],"answer":3,"explain_vi":"Đoạn 5: anh nhớ tới bố mình, mỗi lần bố gọi anh đều trả lời qua loa rồi cúp máy."},{"q":"张明为什么“愣住了”？","q_vi":"Vì sao Trương Minh \"sững người\"?","options":["他发现老李就是自己的父亲","父亲的电脑坏了","父亲在网上玩游戏","母亲做的菜不好吃"],"answer":0,"explain_vi":"Đoạn 8: tên tài khoản của bố chính là \"Lão Lý\" – đây là cái kết bất ngờ."},{"q":"关于父亲，下面哪一项是正确的？","q_vi":"Về người bố, câu nào dưới đây đúng?","options":["他年轻的时候就是下棋高手","他让张明的表妹教他用电脑","他为了了解儿子，专门学会了下棋","他不想让张明回家"],"answer":2,"explain_vi":"Đoạn 9: bố mất hai tháng học chơi cờ chỉ để được trò chuyện, biết con sống thế nào."}],"beyond":[["棋","qí","KỲ","cờ (cờ tướng, cờ vua, cờ vây)"],["下棋","xiàqí","HẠ KỲ","đánh cờ, chơi cờ"],["不算","bù suàn","BẤT TOÁN","không tính, không coi là, chưa tính là"],["国庆节","guó qìng jié","QUỐC KHÁNH TIẾT","quốc khánh"],["书房","shūfáng","THƯ PHÒNG","thư phòng, phòng sách · phòng đọc sách, thư phòng"],["愣","lèng","LĂNG","Ngây ra, sững sờ · ngây ra, đờ ra (vì kinh ngạc, sững sờ mà ngẩn người)"],["用户","yònghù","DỤNG HỘ","Người dùng"],["学会","xuéhuì","HỌC HỘI","hội học thuật, hội chuyên môn"],["好不","hǎobù","HẢO BẤT","thật là, biết bao"],["父子","fùzǐ","PHỤ TỬ","cha và con trai"],["面对面","miànduìmiàn","DIỆN ĐỐI DIỆN","mặt đối mặt, trực diện"]]},{"id":"h4-03","level":4,"title":"写给十年后的自己","title_vi":"Gửi chính mình mười năm sau","topic":"thư từ – học tập","chars":619,"paragraphs":["十年后的我：","你好！现在是二〇二六年九月一日，我刚刚到北京，开始了留学生活。这是我第一次离开越南，第一次一个人住在国外。今天晚上，宿舍里很安静，我的同屋已经睡着了，我却怎么也睡不着，所以决定给你写一封信。等你读到这封信的时候，你应该已经三十岁了吧？","先说说我现在的情况吧。说实话，今天我有点儿失望。在越南的时候，我的汉语成绩一直很好，老师和同学都说我的发音很标准。可是今天下了飞机，出租车司机跟我说了一句话，我一个字也没听懂。在食堂买饭的时候，我想要一碗面条，最后却拿到了一碗米饭。我站在那里，脸红得像一个西红柿。","但是，今天也发生了一件让我很感动的事。我拿着很重的行李找不到宿舍楼，一个中国女孩儿主动走过来问我需不需要帮助。她不但帮我把行李送到了房间，还把她的手机号码留给了我，说：“有什么不明白的，随时问我。”她叫林小雨，是中文系的学生。我们约好了，以后我教她越南语，她帮我练习口语。","我想问你几个问题：你现在的汉语说得怎么样？能不能跟中国人自然地聊天、开玩笑？你有没有像今天计划的那样，成为一名翻译？你还和林小雨保持联系吗？还有，你还记得爸爸妈妈在机场送我时说的话吗？他们说：“不要怕犯错误，怕的是不敢开口。”","我也想给你提几个要求。第一，不管工作多忙，都要每年回家看看爸爸妈妈；第二，不要放弃学习，世界很大，还有很多值得去了解的东西；第三，如果你现在遇到了困难，请想一想今天的我：一个连面条和米饭都说不清楚的女孩儿，都敢一个人来到这么远的地方，你还有什么好害怕的呢？","最后，我想对你说一声“谢谢”。谢谢你没有放弃，一直努力地往前走。不管你现在成功还是失败，我都为你感到骄傲。","祝你一切都好！","二〇二六年的你 阮秋河"],"pinyin":["shí nián hòu de wǒ","nǐ hǎo xiàn zài shì èr èr liù nián jiǔ yuè yī rì wǒ gāng gāng dào běi jīng kāi shǐ le liú xué shēng huó zhè shì wǒ dì yī cì lí kāi yuè nán dì yī cì yí gè rén zhù zài guó wài jīn tiān wǎn shang sù shè lǐ hěn ān jìng wǒ de tóng wū yǐ jīng shuì zháo le wǒ què zěn me yě shuì bù zhe suǒ yǐ jué dìng gěi nǐ xiě yī fēng xìn děng nǐ dú dào zhè fēng xìn de shí hou nǐ yīng gāi yǐ jīng sān shí suì le ba","xiān shuō shuō wǒ xiàn zài de qíng kuàng ba shuō shí huà jīn tiān wǒ yǒu diǎn ér shī wàng zài yuè nán de shí hou wǒ de hàn yǔ chéng jì yì zhí hěn hǎo lǎo shī hé tóng xué dōu shuō wǒ de fā yīn hěn biāo zhǔn kě shì jīn tiān xià le fēi jī chū zū chē sī jī gēn wǒ shuō le yī jù huà wǒ yí gè zì yě méi tīng dǒng zài shí táng mǎi fàn de shí hou wǒ xiǎng yào yī wǎn miàn tiáo zuì hòu què ná dào le yī wǎn mǐ fàn wǒ zhàn zài nà lǐ liǎn hóng de xiàng yí gè xī hóng shì","dàn shì jīn tiān yě fā shēng le yī jiàn ràng wǒ hěn gǎn dòng de shì wǒ ná zhe hěn zhòng de xíng lǐ zhǎo bú dào sù shè lóu yí gè zhōng guó nǚ hái ér zhǔ dòng zǒu guò lái wèn wǒ xū bù xū yào bāng zhù tā bù dàn bāng wǒ bǎ xíng lǐ sòng dào le fáng jiān hái bǎ tā de shǒu jī hào mǎ liú gěi le wǒ shuō yǒu shén me bù míng bai de suí shí wèn wǒ tā jiào lín xiǎo yǔ shì zhōng wén xì de xué sheng wǒ men yuē hǎo le yǐ hòu wǒ jiào tā yuè nán yǔ tā bāng wǒ liàn xí kǒu yǔ","wǒ xiǎng wèn nǐ jǐ gè wèn tí nǐ xiàn zài de hàn yǔ shuō de zěn me yàng néng bù néng gēn zhōng guó rén zì rán de liáo tiān kāi wán xiào nǐ yǒu méi yǒu xiàng jīn tiān jì huà de nà yàng chéng wéi yī míng fān yì nǐ hái hé lín xiǎo yǔ bǎo chí lián xì ma hái yǒu nǐ hái jì de bà ba mā ma zài jī chǎng sòng wǒ shí shuō de huà ma tā men shuō bú yào pà fàn cuò wù pà de shì bù gǎn kāi kǒu","wǒ yě xiǎng gěi nǐ tí jǐ gè yāo qiú dì yī bù guǎn gōng zuò duō máng dōu yào měi nián huí jiā kàn kàn bà ba mā ma dì èr bú yào fàng qì xué xí shì jiè hěn dà hái yǒu hěn duō zhí de qù liǎo jiě de dōng xi dì sān rú guǒ nǐ xiàn zài yù dào le kùn nán qǐng xiǎng yī xiǎng jīn tiān de wǒ yí gè lián miàn tiáo hé mǐ fàn dōu shuō bù qīng chǔ de nǚ hái ér dōu gǎn yí gè rén lái dào zhè me yuǎn de dì fang nǐ hái yǒu shén me hǎo hài pà de ne","zuì hòu wǒ xiǎng duì nǐ shuō yī shēng xiè xiè xiè xiè nǐ méi yǒu fàng qì yì zhí nǔ lì de wǎng qián zǒu bù guǎn nǐ xiàn zài chéng gōng hái shì shī bài wǒ dōu wèi nǐ gǎn dào jiāo ào","zhù nǐ yī qiè dōu hǎo","èr èr liù nián de nǐ ruǎn qiū hé"],"translations":["Gửi tôi của mười năm sau:","Chào bạn! Bây giờ là ngày 1 tháng 9 năm 2026, tôi vừa đến Bắc Kinh, bắt đầu cuộc sống du học. Đây là lần đầu tiên tôi rời Việt Nam, lần đầu tiên sống một mình ở nước ngoài. Tối nay ký túc xá rất yên tĩnh, bạn cùng phòng đã ngủ say, còn tôi thì mãi không ngủ được, nên quyết định viết cho bạn một lá thư. Khi bạn đọc lá thư này, chắc bạn đã ba mươi tuổi rồi nhỉ?","Kể trước tình hình hiện giờ của tôi nhé. Nói thật, hôm nay tôi hơi thất vọng. Hồi ở Việt Nam, điểm tiếng Trung của tôi lúc nào cũng tốt, thầy cô và bạn bè đều khen tôi phát âm rất chuẩn. Vậy mà hôm nay xuống máy bay, bác tài xế taxi nói với tôi một câu, tôi không nghe hiểu chữ nào. Lúc mua cơm ở căng tin, tôi muốn gọi một bát mì, cuối cùng lại nhận được một bát cơm trắng. Tôi đứng đó, mặt đỏ như quả cà chua.","Nhưng hôm nay cũng có một chuyện khiến tôi rất cảm động. Tôi xách hành lý nặng trịch mà không tìm thấy khu ký túc xá, một cô gái Trung Quốc chủ động đến hỏi tôi có cần giúp không. Cô ấy không chỉ giúp tôi mang hành lý lên tận phòng, mà còn để lại số điện thoại cho tôi, nói: \"Có gì không hiểu thì cứ hỏi mình bất cứ lúc nào.\" Cô ấy tên Lâm Tiểu Vũ, là sinh viên khoa tiếng Trung. Chúng tôi hẹn nhau sau này tôi dạy cô ấy tiếng Việt, cô ấy giúp tôi luyện khẩu ngữ.","Tôi muốn hỏi bạn vài câu: bây giờ tiếng Trung của bạn thế nào rồi? Có thể trò chuyện, đùa giỡn tự nhiên với người Trung Quốc chưa? Bạn có trở thành phiên dịch viên như kế hoạch hôm nay không? Bạn còn giữ liên lạc với Lâm Tiểu Vũ chứ? Còn nữa, bạn còn nhớ câu bố mẹ dặn khi tiễn tôi ở sân bay không? Bố mẹ nói: \"Đừng sợ mắc lỗi, đáng sợ là không dám mở miệng.\"","Tôi cũng muốn đưa ra cho bạn vài yêu cầu. Thứ nhất, dù công việc bận đến đâu, năm nào cũng phải về thăm bố mẹ; thứ hai, đừng bỏ việc học, thế giới rất rộng lớn, còn rất nhiều điều đáng để tìm hiểu; thứ ba, nếu bây giờ bạn đang gặp khó khăn, hãy nghĩ đến tôi của hôm nay: một cô gái đến mì với cơm còn nói không rõ mà vẫn dám một mình đến nơi xa thế này, thì bạn còn gì phải sợ nữa chứ?","Cuối cùng, tôi muốn nói với bạn một tiếng \"cảm ơn\". Cảm ơn bạn đã không bỏ cuộc, luôn nỗ lực bước về phía trước. Dù bây giờ bạn thành công hay thất bại, tôi đều tự hào về bạn.","Chúc bạn mọi điều tốt đẹp!","Bạn của năm 2026, Nguyễn Thu Hà"],"questions":[{"q":"作者写这封信的时候在哪里？","q_vi":"Khi viết lá thư này tác giả đang ở đâu?","options":["越南的家里","北京的宿舍里","机场","林小雨的家里"],"answer":1,"explain_vi":"Đoạn 2: tác giả vừa đến Bắc Kinh, viết thư vào buổi tối trong ký túc xá."},{"q":"作者为什么说今天“有点儿失望”？","q_vi":"Vì sao tác giả nói hôm nay \"hơi thất vọng\"?","options":["她找不到宿舍","食堂的饭不好吃","她发现自己的汉语在实际生活中不太够用","同屋不太友好"],"answer":2,"explain_vi":"Đoạn 3: ở Việt Nam học giỏi, nhưng đến nơi thì không nghe hiểu tài xế, gọi mì lại ra cơm."},{"q":"爸爸妈妈说的“怕的是不敢开口”是什么意思？","q_vi":"Câu bố mẹ nói \"đáng sợ là không dám mở miệng\" có ý gì?","options":["学语言最重要的是敢说","说话要小心，不要说错","在国外不要随便跟别人说话","开口说话很危险"],"answer":0,"explain_vi":"Ý là đừng sợ sai, điều quan trọng khi học ngoại ngữ là dám nói."},{"q":"关于这封信，下面哪一项是正确的？","q_vi":"Về lá thư này, câu nào dưới đây đúng?","options":["作者已经成为了一名翻译","林小雨是作者的越南朋友","作者觉得留学太难，想回国","作者希望十年后的自己不要害怕困难"],"answer":3,"explain_vi":"Đoạn 6: tác giả nhắn nhủ nếu gặp khó khăn thì hãy nhớ cô gái dũng cảm hôm nay – đừng sợ."}],"beyond":[["越南","Yuènán","VIỆT NAM","Việt Nam"],["宿舍","sù shè","TÚC XÁ","ký túc xá · ký túc xá, nhà ở tập thể; ký túc xá"],["说实话","shuō shíhuà","THUYẾT THỰC THOẠI","nói thật lòng, nói thật"],["一句话","yī jù huà","NHẤT CÚ THOẠI","một câu, một lời nói"],["有没有","yǒu méiyǒu","HỮU MỘT HỮU","có... không, có hay không"],["犯","fàn","PHẠM","phạm, phạm phải (tội, lỗi); tái phát"],["开口","kāi kǒu","KHAI KHẨU","mở miệng, lên tiếng · mở lời, mở miệng nói, cất lời"]]},{"id":"h4-04","level":4,"title":"午睡的学问","title_vi":"Ngủ trưa cũng là một môn học","topic":"khoa học thường thức","chars":636,"paragraphs":["在中国，很多人都有午睡的习惯。不少学校中午会给学生留出一段休息时间，有的公司也允许员工吃完午饭后在座位上睡一会儿。可是也有人认为，白天睡觉是浪费时间，而且越睡越累。那么，午睡到底有没有好处呢？","科学家发现，人在一天里的精神并不是一样的。除了晚上，下午一点到三点左右，人也特别容易觉得困。这不完全是因为吃饱了饭，而是我们身体本来的规律。所以，就算不吃午饭，很多人到了下午也会想睡觉。","研究证明，一次合适的午睡可以让人的精神变好，记忆力也会提高。对学生来说，午睡以后再学习，往往学得更快、记得更清楚；对司机来说，在困的时候睡十几分钟，可以减少交通事故。","不过，午睡并不是越长越好。很多人都有过这样的经历：中午本来只想睡一会儿，结果一下子睡了一个多小时，醒来以后不但没有精神，反而头很重，心情也不好。这是为什么呢？","原来，人睡着以后，会慢慢地从“浅睡”进入“深睡”。一般来说，睡着二三十分钟以后，人就会开始进入深睡。如果正好在深睡的时候被叫醒，大脑还没有准备好，人就会觉得特别难受。所以专家建议，午睡最好不要超过二三十分钟。","那么，怎样才能不睡过头呢？有一个有趣的方法：午睡之前先喝一杯咖啡，然后马上睡觉。听起来很奇怪，对吧？其实，咖啡喝下去以后，要过大约二十分钟才会起作用。等你睡了二十分钟，咖啡正好开始让你变得清醒，你就能轻松地醒过来了。当然，晚上睡得不好的人最好别试这个方法。","另外，午睡的方式也很重要。很多上班族习惯在桌子上睡，时间长了，身体会很不舒服。如果条件允许，最好能躺下来，或者在椅子上舒舒服服地坐着睡。","总的来说，午睡就像给手机充电：充十几分钟，就能用一个下午；可是如果一直充个不停，也不一定是好事。找到适合自己的方法，才能让午睡真正帮到你。"],"pinyin":["zài zhōng guó hěn duō rén dōu yǒu wǔ shuì de xí guàn bù shǎo xué xiào zhōng wǔ huì gěi xué sheng liú chū yī duàn xiū xī shí jiān yǒu de gōng sī yě yǔn xǔ yuán gōng chī wán wǔ fàn hòu zài zuò wèi shàng shuì yī huì er kě shì yě yǒu rén rèn wéi bái tiān shuì jiào shì làng fèi shí jiān ér qiě yuè shuì yuè lèi nà me wǔ shuì dào dǐ yǒu méi yǒu hǎo chù ne","kē xué jiā fā xiàn rén zài yī tiān lǐ de jīng shén bìng bú shì yī yàng de chú le wǎn shang xià wǔ yì diǎn dào sān diǎn zuǒ yòu rén yě tè bié róng yì jué de kùn zhè bù wán quán shì yīn wèi chī bǎo le fàn ér shì wǒ men shēn tǐ běn lái de guī lǜ suǒ yǐ jiù suàn bù chī wǔ fàn hěn duō rén dào le xià wǔ yě huì xiǎng shuì jiào","yán jiū zhèng míng yī cì hé shì de wǔ shuì kě yǐ ràng rén de jīng shén biàn hǎo jì yì lì yě huì tí gāo duì xué sheng lái shuō wǔ shuì yǐ hòu zài xué xí wǎng wǎng xué dé gèng kuài jì de gèng qīng chu duì sī jī lái shuō zài kùn de shí hou shuì shí jǐ fēn zhōng kě yǐ jiǎn shǎo jiāo tōng shì gù","bù guò wǔ shuì bìng bú shì yuè zhǎng yuè hǎo hěn duō rén dōu yǒu guò zhè yàng de jīng lì zhōng wǔ běn lái zhǐ xiǎng shuì yī huì er jié guǒ yí xià zi shuì le yí gè duō xiǎo shí xǐng lái yǐ hòu bù dàn méi yǒu jīng shén fǎn ér tóu hěn zhòng xīn qíng yě bù hǎo zhè shì wèi shén me ne","yuán lái rén shuì zháo yǐ hòu huì màn màn de cóng qiǎn shuì jìn rù shēn shuì yì bān lái shuō shuì zháo èr sān shí fēn zhōng yǐ hòu rén jiù huì kāi shǐ jìn rù shēn shuì rú guǒ zhèng hǎo zài shēn shuì de shí hou bèi jiào xǐng dà nǎo hái méi yǒu zhǔn bèi hǎo rén jiù huì jué de tè bié nán shòu suǒ yǐ zhuān jiā jiàn yì wǔ shuì zuì hǎo bú yào chāo guò èr sān shí fēn zhōng","nà me zěn yàng cái néng bù shuì guò tóu ne yǒu yí gè yǒu qù de fāng fǎ wǔ shuì zhī qián xiān hē yī bēi kā fēi rán hòu mǎ shàng shuì jiào tīng qǐ lái hěn qí guài duì ba qí shí kā fēi hē xià qù yǐ hòu yào guò dà yuē èr shí fēn zhōng cái huì qǐ zuò yòng děng nǐ shuì le èr shí fēn zhōng kā fēi zhèng hǎo kāi shǐ ràng nǐ biàn dé qīng xǐng nǐ jiù néng qīng sōng de xǐng guò lái le dāng rán wǎn shang shuì dé bù hǎo de rén zuì hǎo bié shì zhè ge fāng fǎ","lìng wài wǔ shuì de fāng shì yě hěn zhòng yào hěn duō shàng bān zú xí guàn zài zhuō zi shàng shuì shí jiān zhǎng le shēn tǐ huì hěn bù shū fu rú guǒ tiáo jiàn yǔn xǔ zuì hǎo néng tǎng xià lái huò zhě zài yǐ zi shàng shū shū fu fú de zuò zhe shuì","zǒng de lái shuō wǔ shuì jiù xiàng gěi shǒu jī chōng diàn chōng shí jǐ fēn zhōng jiù néng yòng yí gè xià wǔ kě shì rú guǒ yì zhí chōng gè bù tíng yě bù yí dìng shì hǎo shì zhǎo dào shì hé zì jǐ de fāng fǎ cái néng ràng wǔ shuì zhēn zhèng bāng dào nǐ"],"translations":["Ở Trung Quốc, nhiều người có thói quen ngủ trưa. Không ít trường học dành cho học sinh một khoảng thời gian nghỉ vào buổi trưa, có công ty cũng cho phép nhân viên ăn trưa xong được ngủ một lát tại chỗ ngồi. Thế nhưng cũng có người cho rằng ngủ ban ngày là lãng phí thời gian, mà càng ngủ càng mệt. Vậy rốt cuộc ngủ trưa có lợi hay không?","Các nhà khoa học phát hiện, tinh thần của con người trong một ngày không phải lúc nào cũng như nhau. Ngoài buổi tối ra, khoảng từ một đến ba giờ chiều con người cũng rất dễ buồn ngủ. Điều này không hoàn toàn do ăn no, mà là quy luật vốn có của cơ thể. Vì thế, dù không ăn trưa, nhiều người đến chiều vẫn muốn ngủ.","Nghiên cứu chứng minh, một giấc ngủ trưa hợp lý có thể giúp tinh thần tốt lên, trí nhớ cũng được cải thiện. Với học sinh, ngủ trưa xong rồi học thường học nhanh hơn, nhớ lâu hơn; với tài xế, ngủ mười mấy phút khi buồn ngủ có thể giảm tai nạn giao thông.","Tuy nhiên, ngủ trưa không phải càng dài càng tốt. Nhiều người từng trải qua chuyện này: buổi trưa định chỉ ngủ một lát, kết quả một mạch ngủ hơn một tiếng, tỉnh dậy chẳng những không tỉnh táo mà đầu còn nặng trĩu, tâm trạng cũng không tốt. Vì sao vậy?","Thì ra, sau khi ngủ, con người sẽ dần đi từ \"ngủ nông\" vào \"ngủ sâu\". Thông thường, sau khi ngủ khoảng hai ba mươi phút, người ta sẽ bắt đầu vào giấc ngủ sâu. Nếu bị gọi dậy đúng lúc đang ngủ sâu, não chưa chuẩn bị xong, người ta sẽ thấy rất khó chịu. Vì vậy chuyên gia khuyên ngủ trưa tốt nhất đừng quá hai ba mươi phút.","Vậy làm sao để không ngủ quá giờ? Có một cách thú vị: trước khi ngủ trưa hãy uống một cốc cà phê, rồi đi ngủ ngay. Nghe có vẻ kỳ lạ, đúng không? Thật ra, cà phê uống vào phải khoảng hai mươi phút sau mới phát huy tác dụng. Đợi bạn ngủ được hai mươi phút, cà phê vừa bắt đầu khiến bạn tỉnh táo, bạn sẽ dễ dàng thức dậy. Đương nhiên, người buổi tối ngủ không ngon thì tốt nhất đừng thử cách này.","Ngoài ra, cách ngủ trưa cũng rất quan trọng. Nhiều người đi làm quen ngủ gục trên bàn, lâu ngày cơ thể sẽ rất khó chịu. Nếu điều kiện cho phép, tốt nhất nên nằm xuống, hoặc ngồi thoải mái trên ghế mà ngủ.","Nói tóm lại, ngủ trưa giống như sạc điện thoại: sạc mười mấy phút là dùng được cả buổi chiều; nhưng nếu cứ sạc mãi không ngừng thì cũng chưa chắc đã tốt. Tìm được cách phù hợp với bản thân thì giấc ngủ trưa mới thật sự giúp được bạn."],"questions":[{"q":"根据第二段，人下午容易困的主要原因是什么？","q_vi":"Theo đoạn 2, nguyên nhân chính khiến con người dễ buồn ngủ vào buổi chiều là gì?","options":["午饭吃得太多","晚上睡得太晚","身体本来就有这样的规律","下午的工作太无聊"],"answer":2,"explain_vi":"Đoạn 2: không hoàn toàn do ăn no, mà là quy luật vốn có của cơ thể."},{"q":"为什么午睡时间太长，醒来以后反而不舒服？","q_vi":"Vì sao ngủ trưa quá lâu, tỉnh dậy lại thấy khó chịu?","options":["因为可能在深睡的时候醒来","因为咖啡喝得太多","因为睡觉的地方太热","因为午饭没有吃饱"],"answer":0,"explain_vi":"Đoạn 5: ngủ quá 20–30 phút sẽ vào giấc ngủ sâu, bị đánh thức lúc đó thì não chưa sẵn sàng nên khó chịu."},{"q":"“午睡前喝咖啡”这个方法为什么有用？","q_vi":"Vì sao cách \"uống cà phê trước khi ngủ trưa\" lại có tác dụng?","options":["因为咖啡能让人马上睡着","因为咖啡大约二十分钟后才起作用，正好帮人醒来","因为咖啡可以让人睡得更久","因为喝了咖啡晚上就不用睡觉了"],"answer":1,"explain_vi":"Đoạn 6: cà phê cần khoảng 20 phút mới có tác dụng, đúng lúc cần thức dậy."},{"q":"作者把午睡比作“给手机充电”，想说明什么？","q_vi":"Tác giả ví ngủ trưa như \"sạc điện thoại\" để nói lên điều gì?","options":["午睡的时候应该给手机充电","不午睡的人手机用得更多","午睡时间越长越好","午睡时间短效果好，太长不一定好"],"answer":3,"explain_vi":"Đoạn cuối: sạc ít phút dùng cả buổi chiều, cắm mãi chưa chắc tốt – ngủ ngắn có lợi, ngủ quá dài không tốt."}],"beyond":[["有没有","yǒu méiyǒu","HỮU MỘT HỮU","có... không, có hay không"],["就算","jiùsuàn","TỰU TOÁN","cho dù, dẫu cho · cho dù; dẫu rằng; ngay cả khi"],["记忆力","jìyìlì","KÝ ỨC LỰC","trí nhớ"],["一下子","yīxiàzi","NHẤT HẠ TỬ","bỗng chốc, một thoáng, đột nhiên"],["醒来","xǐnglai","TỈNH LAI","tỉnh dậy, thức giấc, tỉnh ngộ"],["大脑","dànǎo","ĐẠI NÃO","não bộ, đại não"],["过头","guò tóu","QUÁ ĐẦU","quá mức, quá đà · quá mức, quá đà, thái quá"],["总的来说","zǒngde lái shuō","TỔNG ĐÍCH LAI THUYẾT","nói tóm lại, nhìn chung mà nói"],["不停","bùtíng","BẤT ĐÌNH","liên tục, không ngừng · suốt; liên tục, không ngừng"]]},{"id":"h4-05","level":4,"title":"没有手机的一天","title_vi":"Một ngày không có điện thoại","topic":"du lịch","chars":667,"paragraphs":["去年暑假，我一个人去西安旅游。西安是一座有三千多年历史的古城，到处都是名胜古迹。出发前，我在手机上查好了所有的信息：住哪个酒店、坐几路公共汽车、去哪家饭馆吃饭……我觉得，只要有手机，在中国旅游就一点儿问题也没有。","到西安的第二天，我打车去看兵马俑。下车的时候，我一边跟司机说“谢谢”，一边拿着地图往外走。车开走了大概五分钟，我才发现：我的手机不见了！","我马上紧张起来。在中国，手机实在太重要了。买票、坐车、吃饭、买水，几乎都是用手机付款，很多年轻人身上根本不带现金。我翻了翻钱包，里面只有二十块钱和一张银行卡。","那天下午，我在景区门口用二十块钱买了一个面包和一瓶水，然后坐公共汽车回到了市里。天快黑的时候，我又累又饿，走进酒店附近的一家小面馆。我不好意思地对老板说：“对不起，我的手机丢了，身上没有钱。我能先吃一碗面，明天再来付钱吗？”","老板是一位五十多岁的阿姨。她看了看我，什么也没问，就给我拿来了一大碗热乎乎的面，上面还放了一个鸡蛋。她说：“吃吧，出门在外，谁都会遇到麻烦。”我一边吃，一边差点儿哭了出来。","吃完饭，阿姨还用她的手机帮我给我的手机打了电话。电话响了很久，终于有人接了，原来是那位出租车司机！他说他也发现了座位上的手机，正在想办法联系我。第二天早上，他专门开车把手机送到了我住的酒店，一分钱也不要。","拿回手机以后，我第一件事就是去面馆付钱。可是阿姨笑着摆了摆手：“一碗面而已，不用了。”我坚持要给，她就说：“那你以后要是看到别人需要帮忙，也帮一把吧。”","离开西安的那天，我没有拍很多照片，可是这座城市留给我的印象比任何一张照片都深刻。我原来以为，旅游最重要的是看风景，后来才明白，让我们记住一个地方的，常常是那里的人。","现在，每次看到路上有人问路，或者有人在商店门口着急地找东西，我都会想起那碗面，然后走过去问一句：“需要帮忙吗？”"],"pinyin":["qù nián shǔ jià wǒ yí gè rén qù xī ān lǚ yóu xī ān shì yī zuò yǒu sān qiān duō nián lì shǐ de gǔ chéng dào chù dōu shì míng shèng gǔ jì chū fā qián wǒ zài shǒu jī shàng chá hǎo le suǒ yǒu de xìn xī zhù nǎ ge jiǔ diàn zuò jǐ lù gōng gòng qì chē qù nǎ jiā fàn guǎn chī fàn wǒ jué de zhǐ yào yǒu shǒu jī zài zhōng guó lǚ yóu jiù yì diǎn ér wèn tí yě méi yǒu","dào xī ān de dì èr tiān wǒ dǎ chē qù kàn bīng mǎ yǒng xià chē de shí hou wǒ yī biān gēn sī jī shuō xiè xiè yī biān ná zhe dì tú wǎng wài zǒu chē kāi zǒu le dà gài wǔ fēn zhōng wǒ cái fā xiàn wǒ de shǒu jī bú jiàn le","wǒ mǎ shàng jǐn zhāng qǐ lái zài zhōng guó shǒu jī shí zài tài zhòng yào le mǎi piào zuò chē chī fàn mǎi shuǐ jī hū dōu shì yòng shǒu jī fù kuǎn hěn duō nián qīng rén shēn shàng gēn běn bù dài xiàn jīn wǒ fān le fān qián bāo lǐ miàn zhǐ yǒu èr shí kuài qián hé yī zhāng yín háng kǎ","nà tiān xià wǔ wǒ zài jǐng qū mén kǒu yòng èr shí kuài qián mǎi le yí gè miàn bāo hé yī píng shuǐ rán hòu zuò gōng gòng qì chē huí dào le shì lǐ tiān kuài hēi de shí hou wǒ yòu lèi yòu è zǒu jìn jiǔ diàn fù jìn de yī jiā xiǎo miàn guǎn wǒ bù hǎo yì sī de duì lǎo bǎn shuō duì bù qǐ wǒ de shǒu jī diū le shēn shàng méi yǒu qián wǒ néng xiān chī yī wǎn miàn míng tiān zài lái fù qián ma","lǎo bǎn shì yī wèi wǔ shí duō suì de ā yí tā kàn le kàn wǒ shén me yě méi wèn jiù gěi wǒ ná lái le yī dà wǎn rè hū hū de miàn shàng miàn hái fàng le yí gè jī dàn tā shuō chī ba chū mén zài wài shuí dū huì yù dào má fan wǒ yī biān chī yī biān chà diǎn ér kū le chū lái","chī wán fàn ā yí hái yòng tā de shǒu jī bāng wǒ gěi wǒ de shǒu jī dǎ le diàn huà diàn huà xiǎng le hěn jiǔ zhōng yú yǒu rén jiē le yuán lái shì nà wèi chū zū chē sī jī tā shuō tā yě fā xiàn le zuò wèi shàng de shǒu jī zhèng zài xiǎng bàn fǎ lián xì wǒ dì èr tiān zǎo shang tā zhuān mén kāi chē bǎ shǒu jī sòng dào le wǒ zhù de jiǔ diàn yī fēn qián yě bú yào","ná huí shǒu jī yǐ hòu wǒ dì yī jiàn shì jiù shì qù miàn guǎn fù qián kě shì ā yí xiào zhe bǎi le bǎi shǒu yī wǎn miàn ér yǐ bù yòng le wǒ jiān chí yào gěi tā jiù shuō nà nǐ yǐ hòu yào shì kàn dào bié rén xū yào bāng máng yě bāng yī bǎ ba","lí kāi xī ān de nà tiān wǒ méi yǒu pāi hěn duō zhào piān kě shì zhè zuò chéng shì liú gěi wǒ de yìn xiàng bǐ rèn hé yī zhāng zhào piān dōu shēn kè wǒ yuán lái yǐ wéi lǚ yóu zuì zhòng yào de shì kàn fēng jǐng hòu lái cái míng bai ràng wǒ men jì zhù yí gè dì fang de cháng cháng shì nà lǐ de rén","xiàn zài měi cì kàn dào lù shàng yǒu rén wèn lù huò zhě yǒu rén zài shāng diàn mén kǒu zháo jí de zhǎo dōng xi wǒ dū huì xiǎng qǐ nà wǎn miàn rán hòu zǒu guò qù wèn yī jù xū yào bāng máng ma"],"translations":["Kỳ nghỉ hè năm ngoái, tôi đi du lịch Tây An một mình. Tây An là một cố đô có lịch sử hơn ba nghìn năm, đâu đâu cũng là danh lam thắng cảnh, di tích cổ. Trước khi đi, tôi đã tra sẵn mọi thông tin trên điện thoại: ở khách sạn nào, đi xe buýt số mấy, ăn ở quán nào… Tôi nghĩ, chỉ cần có điện thoại thì du lịch ở Trung Quốc chẳng có vấn đề gì cả.","Ngày thứ hai ở Tây An, tôi bắt taxi đi xem tượng binh mã. Lúc xuống xe, tôi vừa nói \"cảm ơn\" với bác tài vừa cầm bản đồ bước ra. Xe chạy đi được chừng năm phút, tôi mới phát hiện: điện thoại của tôi biến mất rồi!","Tôi lập tức cuống lên. Ở Trung Quốc, điện thoại thật sự quá quan trọng. Mua vé, đi xe, ăn uống, mua nước, hầu như đều thanh toán bằng điện thoại, nhiều người trẻ hoàn toàn không mang tiền mặt. Tôi lục ví, trong đó chỉ có hai mươi tệ và một chiếc thẻ ngân hàng.","Chiều hôm đó, tôi dùng hai mươi tệ mua một cái bánh mì và một chai nước ở cổng khu tham quan, rồi đi xe buýt về thành phố. Trời gần tối, tôi vừa mệt vừa đói, bước vào một quán mì nhỏ gần khách sạn. Tôi ngại ngùng nói với chủ quán: \"Xin lỗi, cháu mất điện thoại, trên người không có tiền. Cháu ăn trước một bát mì, mai quay lại trả tiền được không ạ?\"","Chủ quán là một cô ngoài năm mươi tuổi. Cô nhìn tôi, chẳng hỏi gì, liền bưng ra một bát mì to nóng hổi, bên trên còn đặt một quả trứng. Cô nói: \"Ăn đi cháu, ra ngoài xa nhà, ai mà chẳng có lúc gặp rắc rối.\" Tôi vừa ăn vừa suýt bật khóc.","Ăn xong, cô còn dùng điện thoại của cô gọi vào máy của tôi giúp. Chuông đổ rất lâu, cuối cùng cũng có người nhấc máy, hóa ra là bác tài xế taxi! Bác nói bác cũng đã thấy chiếc điện thoại trên ghế, đang tìm cách liên lạc với tôi. Sáng hôm sau, bác đặc biệt lái xe mang điện thoại đến tận khách sạn tôi ở, một đồng cũng không chịu nhận.","Lấy lại điện thoại xong, việc đầu tiên tôi làm là đến quán mì trả tiền. Nhưng cô cười xua tay: \"Có bát mì thôi mà, không cần đâu.\" Tôi nhất quyết đòi trả, cô bèn nói: \"Vậy sau này nếu cháu thấy ai cần giúp đỡ thì giúp người ta một tay nhé.\"","Hôm rời Tây An, tôi không chụp được nhiều ảnh, nhưng ấn tượng thành phố này để lại cho tôi còn sâu đậm hơn bất kỳ tấm ảnh nào. Trước đây tôi cứ nghĩ đi du lịch quan trọng nhất là ngắm cảnh, về sau mới hiểu, thứ khiến ta nhớ mãi một nơi thường là con người ở đó.","Bây giờ, mỗi lần thấy ai đó hỏi đường trên phố, hay có người cuống quýt tìm đồ trước cửa hàng, tôi đều nhớ đến bát mì ấy, rồi bước tới hỏi một câu: \"Bạn có cần giúp không?\""],"questions":[{"q":"作者丢了手机以后为什么特别着急？","q_vi":"Vì sao sau khi mất điện thoại, tác giả đặc biệt sốt ruột?","options":["手机是朋友送的礼物","手机里有很多照片","在中国买东西几乎都用手机付款，她身上钱很少","她不认识回酒店的路"],"answer":2,"explain_vi":"Đoạn 3: ở Trung Quốc hầu như mọi thứ đều trả bằng điện thoại, trong ví cô chỉ có 20 tệ."},{"q":"面馆的阿姨是怎么做的？","q_vi":"Cô chủ quán mì đã làm gì?","options":["先让作者吃面，还帮她打电话找手机","让作者去银行取钱","让作者帮她洗碗","给作者打了一辆出租车"],"answer":0,"explain_vi":"Đoạn 5–6: cô cho ăn mì không hỏi han gì, sau đó còn dùng máy mình gọi vào số của tác giả."},{"q":"阿姨最后为什么不收作者的钱？","q_vi":"Cuối cùng vì sao cô chủ quán không nhận tiền của tác giả?","options":["因为面很便宜","因为作者是外国人","因为司机已经替作者付了钱","因为她希望作者以后也去帮助别人"],"answer":3,"explain_vi":"Đoạn 7: cô bảo sau này thấy ai cần giúp thì giúp người ta – cô muốn lòng tốt được truyền đi."},{"q":"这篇文章主要想表达什么？","q_vi":"Bài văn chủ yếu muốn thể hiện điều gì?","options":["去西安旅游一定要带现金","让人记住一个地方的常常是那里的人","出租车司机都很诚实","旅游的时候不应该用手机"],"answer":1,"explain_vi":"Đoạn 8: điều khiến ta nhớ một nơi thường là con người ở đó – đây là ý chính."}],"beyond":[["西安","Xī'ān","TÂY AN","Tây An"],["名胜古迹","míng shèng gǔ jì","DANH THẮNG CỔ TÍCH","danh lam thắng cảnh"],["不见","bùjiàn","BẤT KIẾN","không thấy, biến mất; không gặp"],["景区","jǐngqū","CẢNH KHU","khu thắng cảnh, khu du lịch ngắm cảnh"],["而已","ér yǐ","NHI DĨ","chỉ vậy thôi · mà thôi"]]},{"id":"h5-01","level":5,"title":"旧书店里的纸条","title_vi":"Những mảnh giấy trong hiệu sách cũ","topic":"truyện ngắn","chars":1192,"paragraphs":["小林大学毕业以后，一个人来到南方的一座城市工作。周末的时候，同事们都有自己的安排，他却不知道该去哪儿。这座城市很热闹，可是他觉得自己像一片落在河里的叶子，跟着水流走，却没有人注意到他。","一个下雨的星期六，他为了躲雨，走进了一家旧书店。书店不大，书架一直排到屋顶，空气里有一股旧纸的味道。柜台后面坐着一位头发花白的老人，正戴着眼镜看报纸。老人抬头看了他一眼，没有向他推荐任何东西。小林很喜欢这种安静，就在书架之间慢慢地转了起来。","他挑了一本散文集，价格很便宜，只要八块钱。回到家打开一看，他发现书里夹着一张小纸条，上面的字写得很整齐：“读到这里的人，你好。这本书的第三十七页是我最喜欢的一段。如果你也有喜欢的句子，可以写在纸条上，放进店里那本蓝色封面的《海边的灯》里。我会看到的。”","小林觉得很有意思，翻到第三十七页，那一段写的是一个人在外地过春节的感受。他读了好几遍，心里忽然有点儿难过，又有点儿温暖。第二个周末，他又去了那家书店，找到那本蓝色的书，把自己写的纸条放了进去。他写道：“我刚来这座城市半年，还没有一个朋友。读了那一段，我才知道原来孤单的人不止我一个。”","一个星期以后，他在同一本书里找到了回信：“孤单并不可怕，它让人有时间认识自己。你可以试着每天做一件小事，比如早上换一条路去上班。慢慢地，这座城市就会变成你的城市。”","就这样，他们开始了一种特别的通信。小林在纸条上写工作上的烦恼：老板批评他做事太慢，同事抢了他的成绩，他想辞职又不敢。对方的回信总是不长，却很有道理。有一次，对方写道：“别急着证明自己比别人强，先把手里的事做好。时间会替你说话。”小林把这句话抄在了笔记本的第一页上。","他越来越好奇，写纸条的到底是什么人。从字上看，对方应该是一个细心的人；从内容看，好像读过很多书，也经历过很多事。他甚至想象，对方也许是一位和他差不多大的姑娘，每个周末也会来这家书店。有好几次，他故意在店里待到很晚，可是什么也没发现。","三个月后，他终于鼓起勇气，在纸条上写：“我们能见一面吗？我想当面谢谢你。”回信很快就来了：“好啊，下周六下午三点，就在书店里。”","那个星期六，小林特意换上了新买的衬衫，两点半就到了书店。他站在那个书架前，心跳得很快。三点到了，店里除了他，只有柜台后面的那位老人。三点十分，三点二十，门口一直没有人进来。他有点儿失望，正准备离开，老人却摘下眼镜，慢慢走过来，从口袋里拿出一张纸条，递给了他。纸条上只有一句话：“年轻人，你好，我就是你要找的人。”","小林一下子呆住了。那熟悉的字，他已经看了整整三个月。老人请他坐下，给他倒了一杯茶，说：“我以前是中学语文老师，退休以后开了这家小店。来这儿的年轻人，很多都和你一样，一个人在外地奋斗。我老了，帮不上什么大忙，只能写几句话。”他笑着补充道：“其实，这些年给我回过纸条的人有二十多个，你是第一个约我见面的。”","后来，小林成了书店的常客，也成了老人的好朋友。他换了一个更合适的工作，也交了几个朋友。又过了一年，老人搬到北方和儿子一起生活，书店交给了别人。离开前，老人把那本蓝色的书送给了小林。","现在，每当小林在街上看到一个拿着行李、一脸紧张的年轻人，他就会想起那个下雨的星期六。他的包里总放着几张空白的纸条。他知道，有时候，一句陌生人的问候，就能让一座冷冰冰的城市变得温暖起来。"],"pinyin":["xiǎo lín dà xué bì yè yǐ hòu yí gè rén lái dào nán fāng de yī zuò chéng shì gōng zuò zhōu mò de shí hou tóng shì men dōu yǒu zì jǐ de ān pái tā què bù zhī dao gāi qù nǎ ér zhè zuò chéng shì hěn rè nao kě shì tā jué de zì jǐ xiàng yī piàn luò zài hé lǐ de yè zi gēn zhe shuǐ liú zǒu què méi yǒu rén zhù yì dào tā","yí gè xià yǔ de xīng qī liù tā wèi le duǒ yǔ zǒu jìn le yī jiā jiù shū diàn shū diàn bù dà shū jià yì zhí pái dào wū dǐng kōng qì lǐ yǒu yī gǔ jiù zhǐ de wèi dào guì tái hòu miàn zuò zhe yī wèi tóu fa huā bái de lǎo rén zhèng dài zhe yǎn jìng kàn bào zhǐ lǎo rén tái tóu kàn le tā yī yǎn méi yǒu xiàng tā tuī jiàn rèn hé dōng xi xiǎo lín hěn xǐ huan zhè zhǒng ān jìng jiù zài shū jià zhī jiān màn màn dì zhuǎn le qǐ lái","tā tiāo le yī běn sǎn wén jí jià gé hěn pián yi zhǐ yào bā kuài qián huí dào jiā dǎ kāi yī kàn tā fā xiàn shū lǐ jiā zhe yī zhāng xiǎo zhǐ tiáo shàng miàn de zì xiě de hěn zhěng qí dú dào zhè lǐ de rén nǐ hǎo zhè běn shū de dì sān shí qī yè shì wǒ zuì xǐ huan de yī duàn rú guǒ nǐ yě yǒu xǐ huan de jù zi kě yǐ xiě zài zhǐ tiáo shàng fàng jìn diàn lǐ nà běn lán sè fēng miàn de hǎi biān de dēng lǐ wǒ huì kàn dào de","xiǎo lín jué de hěn yǒu yì si fān dào dì sān shí qī yè nà yī duàn xiě de shì yí gè rén zài wài dì guò chūn jié de gǎn shòu tā dú le hǎo jǐ biàn xīn lǐ hū rán yǒu diǎn ér nán guò yòu yǒu diǎn ér wēn nuǎn dì èr gè zhōu mò tā yòu qù le nà jiā shū diàn zhǎo dào nà běn lán sè de shū bǎ zì jǐ xiě de zhǐ tiáo fàng le jìn qù tā xiě dào wǒ gāng lái zhè zuò chéng shì bàn nián hái méi yǒu yí gè péng you dú le nà yī duàn wǒ cái zhī dao yuán lái gū dān de rén bù zhǐ wǒ yí gè","yí gè xīng qī yǐ hòu tā zài tóng yī běn shū lǐ zhǎo dào le huí xìn gū dān bìng bù kě pà tā ràng rén yǒu shí jiān rèn shi zì jǐ nǐ kě yǐ shì zhe měi tiān zuò yī jiàn xiǎo shì bǐ rú zǎo shang huàn yī tiáo lù qù shàng bān màn màn de zhè zuò chéng shì jiù huì biàn chéng nǐ de chéng shì","jiù zhè yàng tā men kāi shǐ le yī zhǒng tè bié de tōng xìn xiǎo lín zài zhǐ tiáo shàng xiě gōng zuò shàng de fán nǎo lǎo bǎn pī píng tā zuò shì tài màn tóng shì qiǎng le tā de chéng jì tā xiǎng cí zhí yòu bù gǎn duì fāng de huí xìn zǒng shì bù zhǎng què hěn yǒu dào lǐ yǒu yī cì duì fāng xiě dào bié jí zhe zhèng míng zì jǐ bǐ bié rén qiáng xiān bǎ shǒu lǐ de shì zuò hǎo shí jiān huì tì nǐ shuō huà xiǎo lín bǎ zhè jù huà chāo zài le bǐ jì běn de dì yī yè shàng","tā yuè lái yuè hào qí xiě zhǐ tiáo de dào dǐ shì shén me rén cóng zì shàng kàn duì fāng yīng gāi shì yí gè xì xīn de rén cóng nèi róng kàn hǎo xiàng dú guò hěn duō shū yě jīng lì guò hěn duō shì tā shèn zhì xiǎng xiàng duì fāng yě xǔ shì yī wèi hé tā chà bu duō dà de gū niang měi gè zhōu mò yě huì lái zhè jiā shū diàn yǒu hǎo jǐ cì tā gù yì zài diàn lǐ dài dào hěn wǎn kě shì shén me yě méi fā xiàn","sān gè yuè hòu tā zhōng yú gǔ qǐ yǒng qì zài zhǐ tiáo shàng xiě wǒ men néng jiàn yí miàn ma wǒ xiǎng dāng miàn xiè xiè nǐ huí xìn hěn kuài jiù lái le hǎo a xià zhōu liù xià wǔ sān diǎn jiù zài shū diàn lǐ","nà ge xīng qī liù xiǎo lín tè yì huàn shàng le xīn mǎi de chèn shān liǎng diǎn bàn jiù dào le shū diàn tā zhàn zài nà ge shū jià qián xīn tiào de hěn kuài sān diǎn dào le diàn lǐ chú le tā zhǐ yǒu guì tái hòu miàn de nà wèi lǎo rén sān diǎn shí fēn sān diǎn èr shí mén kǒu yì zhí méi yǒu rén jìn lái tā yǒu diǎn ér shī wàng zhèng zhǔn bèi lí kāi lǎo rén què zhāi xià yǎn jìng màn màn zǒu guò lái cóng kǒu dài lǐ ná chū yī zhāng zhǐ tiáo dì gěi le tā zhǐ tiáo shàng zhǐ yǒu yī jù huà nián qīng rén nǐ hǎo wǒ jiù shì nǐ yào zhǎo de rén","xiǎo lín yí xià zi dāi zhù le nà shú xī de zì tā yǐ jīng kàn le zhěng zhěng sān gè yuè lǎo rén qǐng tā zuò xià gěi tā dào le yī bēi chá shuō wǒ yǐ qián shì zhōng xué yǔ wén lǎo shī tuì xiū yǐ hòu kāi le zhè jiā xiǎo diàn lái zhè ér de nián qīng rén hěn duō dōu hé nǐ yī yàng yí gè rén zài wài dì fèn dòu wǒ lǎo le bāng bù shàng shén me dà máng zhǐ néng xiě jǐ jù huà tā xiào zhe bǔ chōng dào qí shí zhè xiē nián gěi wǒ huí guò zhǐ tiáo de rén yǒu èr shí duō gè nǐ shì dì yí gè yuē wǒ jiàn miàn de","hòu lái xiǎo lín chéng le shū diàn de cháng kè yě chéng le lǎo rén de hǎo péng you tā huàn le yí gè gèng hé shì de gōng zuò yě jiāo le jǐ gè péng you yòu guò le yī nián lǎo rén bān dào běi fāng hé ér zi yì qǐ shēng huó shū diàn jiāo gěi le bié rén lí kāi qián lǎo rén bǎ nà běn lán sè de shū sòng gěi le xiǎo lín","xiàn zài měi dāng xiǎo lín zài jiē shàng kàn dào yí gè ná zhe xíng lǐ yī liǎn jǐn zhāng de nián qīng rén tā jiù huì xiǎng qǐ nà ge xià yǔ de xīng qī liù tā de bāo lǐ zǒng fàng zhe jǐ zhāng kòng bái de zhǐ tiáo tā zhī dao yǒu shí hòu yī jù mò shēng rén de wèn hòu jiù néng ràng yī zuò lěng bīng bīng de chéng shì biàn dé wēn nuǎn qǐ lái"],"translations":["Sau khi tốt nghiệp đại học, Tiểu Lâm một mình đến làm việc ở một thành phố phía Nam. Cuối tuần, đồng nghiệp ai cũng có kế hoạch riêng, còn anh thì chẳng biết nên đi đâu. Thành phố này rất náo nhiệt, nhưng anh thấy mình như một chiếc lá rơi xuống sông, trôi theo dòng nước mà chẳng ai để ý tới.","Một ngày thứ Bảy mưa, để trú mưa, anh bước vào một hiệu sách cũ. Hiệu sách không lớn, giá sách xếp cao tới tận mái nhà, trong không khí thoang thoảng mùi giấy cũ. Sau quầy có một ông cụ tóc hoa râm đang đeo kính đọc báo. Ông ngẩng lên nhìn anh một cái, không giới thiệu cho anh món gì cả. Tiểu Lâm rất thích sự yên tĩnh ấy, liền thong thả dạo giữa các giá sách.","Anh chọn một tập tản văn, giá rất rẻ, chỉ tám đồng. Về nhà mở ra xem, anh phát hiện trong sách kẹp một mảnh giấy nhỏ, chữ viết rất ngay ngắn: \"Chào người đọc đến đây. Trang ba mươi bảy của cuốn sách này là đoạn tôi thích nhất. Nếu bạn cũng có câu mình thích, có thể viết lên giấy rồi bỏ vào cuốn 'Ngọn đèn bên bờ biển' bìa xanh trong tiệm. Tôi sẽ đọc được.\"","Tiểu Lâm thấy rất thú vị, lật đến trang ba mươi bảy; đoạn đó viết về cảm giác của một người đón Tết nơi đất khách. Anh đọc đi đọc lại mấy lần, trong lòng bỗng thấy hơi buồn mà cũng hơi ấm áp. Cuối tuần sau, anh lại đến hiệu sách, tìm cuốn sách màu xanh và kẹp mảnh giấy mình viết vào. Anh viết: \"Tôi mới đến thành phố này được nửa năm, vẫn chưa có một người bạn nào. Đọc đoạn ấy, tôi mới biết hóa ra người cô đơn không chỉ có mình tôi.\"","Một tuần sau, anh tìm thấy thư trả lời trong chính cuốn sách đó: \"Cô đơn không đáng sợ, nó cho con người thời gian để hiểu chính mình. Bạn có thể thử mỗi ngày làm một việc nhỏ, chẳng hạn buổi sáng đi làm bằng một con đường khác. Dần dần, thành phố này sẽ trở thành thành phố của bạn.\"","Cứ như vậy, họ bắt đầu một kiểu thư từ đặc biệt. Tiểu Lâm viết lên giấy những phiền muộn trong công việc: sếp chê anh làm việc quá chậm, đồng nghiệp giành mất thành tích của anh, anh muốn nghỉ việc mà không dám. Thư trả lời của đối phương lúc nào cũng ngắn nhưng rất có lý. Có lần, người ấy viết: \"Đừng vội chứng minh mình giỏi hơn người khác, hãy làm tốt việc trong tay trước đã. Thời gian sẽ nói thay bạn.\" Tiểu Lâm chép câu ấy vào trang đầu tiên của cuốn sổ.","Anh ngày càng tò mò người viết những mảnh giấy rốt cuộc là ai. Nhìn nét chữ thì người đó hẳn là người tỉ mỉ; nhìn nội dung thì dường như đã đọc nhiều sách, cũng trải qua nhiều chuyện. Anh thậm chí còn tưởng tượng người ấy có lẽ là một cô gái trạc tuổi mình, cuối tuần nào cũng đến hiệu sách này. Đã mấy lần anh cố ý ở lại tiệm đến rất muộn, nhưng chẳng phát hiện được gì.","Ba tháng sau, cuối cùng anh lấy hết can đảm viết lên giấy: \"Chúng ta có thể gặp nhau một lần không? Tôi muốn cảm ơn bạn trực tiếp.\" Thư trả lời đến rất nhanh: \"Được thôi, ba giờ chiều thứ Bảy tuần sau, ngay tại hiệu sách.\"","Thứ Bảy hôm ấy, Tiểu Lâm cố ý mặc chiếc áo sơ mi mới mua, hai rưỡi đã có mặt ở hiệu sách. Anh đứng trước giá sách đó, tim đập rất nhanh. Ba giờ đến, trong tiệm ngoài anh ra chỉ có ông cụ sau quầy. Ba giờ mười, ba giờ hai mươi, ngoài cửa vẫn không có ai bước vào. Anh hơi thất vọng, vừa định ra về thì ông cụ tháo kính, chậm rãi bước tới, lấy từ trong túi ra một mảnh giấy đưa cho anh. Trên giấy chỉ có một câu: \"Chào chàng trai, tôi chính là người cậu đang tìm.\"","Tiểu Lâm sững người. Nét chữ quen thuộc ấy anh đã đọc tròn ba tháng. Ông cụ mời anh ngồi, rót cho anh một chén trà rồi nói: \"Trước đây tôi là giáo viên ngữ văn cấp hai, nghỉ hưu thì mở tiệm nhỏ này. Những người trẻ đến đây, nhiều người cũng giống cậu, một mình phấn đấu nơi đất khách. Tôi già rồi, chẳng giúp được việc gì lớn, chỉ có thể viết vài câu.\" Ông cười nói thêm: \"Thật ra, mấy năm nay có hơn hai mươi người viết thư trả lời tôi, cậu là người đầu tiên hẹn gặp tôi.\"","Về sau, Tiểu Lâm trở thành khách quen của hiệu sách, cũng thành bạn thân của ông cụ. Anh chuyển sang một công việc phù hợp hơn, cũng kết bạn được với vài người. Thêm một năm nữa, ông cụ chuyển lên phía Bắc sống cùng con trai, hiệu sách giao lại cho người khác. Trước khi đi, ông tặng Tiểu Lâm cuốn sách màu xanh ấy.","Giờ đây, mỗi khi thấy trên phố một người trẻ xách hành lý, mặt đầy căng thẳng, Tiểu Lâm lại nhớ đến ngày thứ Bảy mưa năm ấy. Trong túi anh lúc nào cũng có vài mảnh giấy trắng. Anh biết rằng, đôi khi chỉ một lời hỏi thăm của người lạ cũng có thể khiến một thành phố lạnh lẽo trở nên ấm áp."],"questions":[{"q":"小林刚到这座城市时，生活怎么样？","q_vi":"Khi Tiểu Lâm mới đến thành phố này, cuộc sống của anh thế nào?","options":["工作轻松，朋友很多","没有朋友，感到孤单","常常和同事去旅行","每天都去书店看书"],"answer":1,"explain_vi":"Đoạn 1: cuối tuần không biết đi đâu, thấy mình như chiếc lá trôi trên sông mà không ai để ý — tức là cô đơn."},{"q":"小林和写纸条的人是怎么联系的？","q_vi":"Tiểu Lâm liên lạc với người viết giấy bằng cách nào?","options":["打电话","在网上聊天","把纸条放在一本蓝色的书里","请老人帮忙寄信"],"answer":2,"explain_vi":"Đoạn 3–5: hai bên kẹp giấy vào cuốn sách bìa xanh 《海边的灯》 trong tiệm."},{"q":"见面以前，小林以为写纸条的人可能是谁？","q_vi":"Trước khi gặp, Tiểu Lâm nghĩ người viết giấy có thể là ai?","options":["一位和他年纪差不多的姑娘","书店的老板","公司的老板","他的大学同学"],"answer":0,"explain_vi":"Đoạn 7: anh tưởng tượng đó là một cô gái trạc tuổi mình."},{"q":"老人为什么要在书里留纸条？","q_vi":"Vì sao ông cụ để lại giấy trong sách?","options":["想多卖几本书","想找一个年轻人帮他管书店","想练习写字","想帮助在外地孤单的年轻人"],"answer":3,"explain_vi":"Đoạn 10: ông nói nhiều người trẻ một mình phấn đấu nơi đất khách, ông chỉ có thể viết vài câu để giúp họ."},{"q":"最后一段说明了什么？","q_vi":"Đoạn cuối cho thấy điều gì?","options":["小林后来也开了一家书店","小林也想像老人一样去温暖陌生人","小林很想念北方的生活","小林不再喜欢这座城市了"],"answer":1,"explain_vi":"Anh luôn mang theo giấy trắng và tin rằng một lời hỏi thăm của người lạ có thể sưởi ấm thành phố — anh muốn tiếp nối việc làm của ông cụ."}],"beyond":[["屋顶","wūdǐng","ỐC ĐỈNH","mái nhà, nóc nhà"],["一眼","yīyǎn","NHẤT NHÃN","một cái liếc mắt, một ánh nhìn, một mắt nhìn"],["封面","fēngmiàn","PHONG DIỆN","bìa sách báo, trang bìa"],["孤单","gūdān","CÔ ĐƠN","cô đơn; cô độc; lẻ loi"],["同一","tóngyī","ĐỒNG NHẤT","đồng nhất, giống nhau · cùng một, giống nhau"],["细心","xìxīn","TẾ TÂM","cẩn thận, tỉ mỉ, chu đáo · cẩn thận, chu đáo, tỉ mỉ"],["一面","yīmiàn","NHẤT DIỆN","một mặt; vừa... vừa...; một lần gặp"],["当面","dāng miàn","ĐƯƠNG DIỆN","trước mặt"],["特意","tèyì","ĐẶC Ý","đặc ý, cố ý, có tâm (Biểu thị hành động được thực hiện dành riêng cho một mục đích cụ thể… · cố ý; đặc ý; riêng để"],["每当","měidāng","MỖI ĐƯƠNG","mỗi khi, mỗi dịp, mỗi độ"],["空白","kòng bái","KHÔNG BẠCH","chỗ trống, khoảng trống"],["有时","yǒushí","HỮU THỜI","có lúc"],["冷冰冰","lěngbīngbīng","LÃNH BĂNG BĂNG","lạnh lùng, lạnh tanh"]]},{"id":"h5-02","level":5,"title":"植物也会“说话”吗？","title_vi":"Thực vật cũng biết \"nói chuyện\" sao?","topic":"khoa học thường thức","chars":1041,"paragraphs":["说到“交流”，人们首先想到的是语言、表情和动作。动物也有自己的交流方式：狗用叫声表达情绪，蜜蜂用跳舞告诉同伴哪里有花。可是植物呢？它们不能走，也不能叫，一辈子站在同一个地方，看起来好像什么都不会“说”。然而，近几十年的科学研究发现，植物其实一直在用自己的方式“说话”，只是我们听不见而已。","最早引起科学家注意的，是发生在非洲草原上的一种现象。当地有一种动物特别喜欢吃某种树的叶子。人们发现，这些动物吃一会儿叶子，就会走到很远的另一棵树那儿去吃，而不是把附近的树都吃一遍。这是为什么呢？","经过研究，科学家找到了答案。原来，当树叶被吃的时候，树会很快在叶子里产生一种让动物觉得很苦的物质。不仅如此，受伤的树还会向空气中放出一种特殊的气体。附近的树“闻”到这种气体以后，也会提前做好准备，让自己的叶子变苦。动物吃了几口就觉得味道不对，只好走到远处去，找那些还没有“收到消息”的树。","这个发现让许多人感到吃惊：难道树和树之间也会互相提醒吗？后来，越来越多的实验证明，这种现象并不少见。比如，西红柿的叶子被虫子咬了以后，也会放出一种气味，附近的西红柿收到这个“信号”，就会提前产生一些虫子不喜欢的物质。从某种意义上说，这就像一个村子里的人发现了小偷，大声喊“小心”，让邻居们赶快关好门窗。","植物不仅能通过空气“说话”，还能通过地下“打电话”。在森林的土里，生活着大量非常细小的生物。它们和树根连在一起，组成了一张看不见的大网。科学家通过实验发现，营养和信息都可以通过这张网，从一棵树传到另一棵树。有人给它起了一个很形象的名字——“森林的互联网”。","更有意思的是，这张网还会帮助“家人”。研究人员发现，一些高大的老树会通过地下的网，把多余的营养送给附近的小树，特别是那些长在大树下面、晒不到太阳的小树。而当一棵老树快要死的时候，它会把身体里剩下的营养尽量送出去。因此，有的科学家把这些老树叫作“树妈妈”。","当然，也有科学家提醒大家，不要把植物想象得和人一样。植物没有大脑，它们的“交流”并不是有意识的行为，而是在漫长的时间里慢慢形成的一种保护自己的本领。用“说话”“帮助”“妈妈”这样的词来描写植物，只是为了让普通人更容易理解，并不代表植物真的有感情。","即使这样，这些研究也改变了我们看待自然的方式。过去，人们常常把一棵树当作一个单独的个体；现在我们知道，森林更像是一个紧密联系的大家庭。砍掉一棵老树，影响的可能不只是这一棵树，而是周围许多植物的生活。","这些发现对农业也有实际的用处。如果能弄清楚植物之间是怎样传递信号的，农民也许就能少用一些农药，让庄稼自己“提醒”自己提前防虫。目前，已经有科学家在这方面进行试验了。","下次走进公园或者森林的时候，你不妨停下来，安静地站一会儿。也许就在你身边，树木和花草正在进行着一场热闹的“谈话”。只不过，它们用的不是声音，而是一种我们还没有完全读懂的语言。"],"pinyin":["shuō dào jiāo liú rén men shǒu xiān xiǎng dào de shì yǔ yán biǎo qíng hé dòng zuò dòng wù yě yǒu zì jǐ de jiāo liú fāng shì gǒu yòng jiào shēng biǎo dá qíng xù mì fēng yòng tiào wǔ gào su tóng bàn nǎ lǐ yǒu huā kě shì zhí wù ne tā men bù néng zǒu yě bù néng jiào yī bèi zi zhàn zài tóng yī gè dì fang kàn qǐ lái hǎo xiàng shén me dōu bú huì shuō rán ér jìn jǐ shí nián de kē xué yán jiū fā xiàn zhí wù qí shí yì zhí zài yòng zì jǐ de fāng shì shuō huà zhǐ shì wǒ men tīng bú jiàn ér yǐ","zuì zǎo yǐn qǐ kē xué jiā zhù yì de shì fā shēng zài fēi zhōu cǎo yuán shàng de yī zhǒng xiàn xiàng dāng dì yǒu yī zhǒng dòng wù tè bié xǐ huan chī mǒu zhǒng shù de yè zi rén men fā xiàn zhè xiē dòng wù chī yī huì er yè zi jiù huì zǒu dào hěn yuǎn de lìng yī kē shù nà ér qù chī ér bú shì bǎ fù jìn de shù dōu chī yī biàn zhè shì wèi shén me ne","jīng guò yán jiū kē xué jiā zhǎo dào le dá àn yuán lái dāng shù yè bèi chī de shí hou shù huì hěn kuài zài yè zi lǐ chǎn shēng yī zhǒng ràng dòng wù jué de hěn kǔ de wù zhì bù jǐn rú cǐ shòu shāng de shù hái huì xiàng kōng qì zhōng fàng chū yī zhǒng tè shū de qì tǐ fù jìn de shù wén dào zhè zhǒng qì tǐ yǐ hòu yě huì tí qián zuò hǎo zhǔn bèi ràng zì jǐ de yè zi biàn kǔ dòng wù chī le jǐ kǒu jiù jué de wèi dào bú duì zhǐ hǎo zǒu dào yuǎn chù qù zhǎo nà xiē hái méi yǒu shōu dào xiāo xi de shù","zhè ge fā xiàn ràng xǔ duō rén gǎn dào chī jīng nán dào shù hé shù zhī jiān yě huì hù xiāng tí xǐng ma hòu lái yuè lái yuè duō de shí yàn zhèng míng zhè zhǒng xiàn xiàng bìng bù shǎo jiàn bǐ rú xī hóng shì de yè zi bèi chóng zi yǎo le yǐ hòu yě huì fàng chū yī zhǒng qì wèi fù jìn de xī hóng shì shōu dào zhè ge xìn hào jiù huì tí qián chǎn shēng yī xiē chóng zi bù xǐ huan de wù zhì cóng mǒu zhǒng yì yì shàng shuō zhè jiù xiàng yí gè cūn zi lǐ de rén fā xiàn le xiǎo tōu dà shēng hǎn xiǎo xīn ràng lín jū men gǎn kuài guān hǎo mén chuāng","zhí wù bù jǐn néng tōng guò kōng qì shuō huà hái néng tōng guò dì xià dǎ diàn huà zài sēn lín de tǔ lǐ shēng huó zhe dà liàng fēi cháng xì xiǎo de shēng wù tā men hé shù gēn lián zài yì qǐ zǔ chéng le yī zhāng kàn bú jiàn de dà wǎng kē xué jiā tōng guò shí yàn fā xiàn yíng yǎng hé xìn xī dōu kě yǐ tōng guò zhè zhāng wǎng cóng yī kē shù chuán dào lìng yī kē shù yǒu rén gěi tā qǐ le yí gè hěn xíng xiàng de míng zi sēn lín de hù lián wǎng","gèng yǒu yì si de shì zhè zhāng wǎng hái huì bāng zhù jiā rén yán jiū rén yuán fā xiàn yī xiē gāo dà de lǎo shù huì tōng guò dì xià de wǎng bǎ duō yú de yíng yǎng sòng gěi fù jìn de xiǎo shù tè bié shì nà xiē zhǎng zài dà shù xià miàn shài bú dào tài yáng de xiǎo shù ér dāng yī kē lǎo shù kuài yào sǐ de shí hou tā huì bǎ shēn tǐ lǐ shèng xià de yíng yǎng jǐn liàng sòng chū qù yīn cǐ yǒu de kē xué jiā bǎ zhè xiē lǎo shù jiào zuò shù mā ma","dāng rán yě yǒu kē xué jiā tí xǐng dà jiā bú yào bǎ zhí wù xiǎng xiàng de hé rén yī yàng zhí wù méi yǒu dà nǎo tā men de jiāo liú bìng bú shì yǒu yì shí de xíng wéi ér shì zài màn cháng de shí jiān lǐ màn màn xíng chéng de yī zhǒng bǎo hù zì jǐ de běn lǐng yòng shuō huà bāng zhù mā ma zhè yàng de cí lái miáo xiě zhí wù zhǐ shì wèi le ràng pǔ tōng rén gèng róng yì lǐ jiě bìng bù dài biǎo zhí wù zhēn de yǒu gǎn qíng","jí shǐ zhè yàng zhè xiē yán jiū yě gǎi biàn le wǒ men kàn dài zì rán de fāng shì guò qù rén men cháng cháng bǎ yī kē shù dàng zuò yí gè dān dú de gè tǐ xiàn zài wǒ men zhī dao sēn lín gèng xiàng shì yí gè jǐn mì lián xì de dà jiā tíng kǎn diào yī kē lǎo shù yǐng xiǎng de kě néng bù zhǐ shì zhè yī kē shù ér shì zhōu wéi xǔ duō zhí wù de shēng huó","zhè xiē fā xiàn duì nóng yè yě yǒu shí jì de yòng chǔ rú guǒ néng nòng qīng chu zhí wù zhī jiān shì zěn yàng chuán dì xìn hào de nóng mín yě xǔ jiù néng shǎo yòng yī xiē nóng yào ràng zhuāng jià zì jǐ tí xǐng zì jǐ tí qián fáng chóng mù qián yǐ jīng yǒu kē xué jiā zài zhè fāng miàn jìn xíng shì yàn le","xià cì zǒu jìn gōng yuán huò zhě sēn lín de shí hou nǐ bù fáng tíng xià lái ān jìng dì zhàn yī huì er yě xǔ jiù zài nǐ shēn biān shù mù hé huā cǎo zhèng zài jìn xíng zhe yī cháng rè nao de tán huà zhǐ bù guò tā men yòng de bú shì shēng yīn ér shì yī zhǒng wǒ men hái méi yǒu wán quán dú dǒng de yǔ yán"],"translations":["Nói đến \"giao tiếp\", người ta trước hết nghĩ tới ngôn ngữ, nét mặt và động tác. Động vật cũng có cách giao tiếp riêng: chó dùng tiếng sủa để bày tỏ cảm xúc, ong dùng điệu nhảy để báo cho đồng loại biết chỗ nào có hoa. Còn thực vật thì sao? Chúng không đi được, cũng không kêu được, cả đời đứng một chỗ, trông như chẳng biết \"nói\" gì. Thế nhưng, các nghiên cứu khoa học mấy chục năm gần đây cho thấy thực vật thật ra vẫn luôn \"nói chuyện\" theo cách riêng của chúng, chỉ là chúng ta không nghe thấy mà thôi.","Điều đầu tiên thu hút sự chú ý của các nhà khoa học là một hiện tượng xảy ra trên thảo nguyên châu Phi. Ở đó có một loài động vật rất thích ăn lá của một loại cây. Người ta phát hiện những con vật này ăn lá một lúc thì lại đi rất xa sang một cây khác để ăn, chứ không ăn hết lượt các cây ở gần. Tại sao vậy?","Qua nghiên cứu, các nhà khoa học đã tìm ra câu trả lời. Hóa ra, khi lá bị ăn, cây sẽ nhanh chóng tạo ra trong lá một chất khiến con vật thấy rất đắng. Không chỉ thế, cây bị thương còn thải vào không khí một loại khí đặc biệt. Những cây gần đó \"ngửi\" thấy khí này cũng sẽ chuẩn bị trước, làm cho lá của mình trở nên đắng. Con vật ăn vài miếng thấy vị không ổn, đành đi ra xa tìm những cây chưa \"nhận được tin\".","Phát hiện này khiến nhiều người kinh ngạc: lẽ nào giữa cây với cây cũng biết nhắc nhở nhau? Về sau, ngày càng nhiều thí nghiệm chứng minh hiện tượng này không hề hiếm. Chẳng hạn, lá cà chua bị sâu cắn cũng sẽ tỏa ra một mùi, những cây cà chua gần đó nhận được \"tín hiệu\" này sẽ tạo ra trước một số chất mà sâu không thích. Theo một nghĩa nào đó, điều này giống như người trong làng phát hiện có trộm, hô to \"Cẩn thận!\" để hàng xóm mau đóng kỹ cửa.","Thực vật không chỉ \"nói chuyện\" qua không khí mà còn \"gọi điện\" dưới lòng đất. Trong đất rừng có vô số sinh vật cực kỳ nhỏ bé. Chúng gắn liền với rễ cây, tạo thành một tấm lưới lớn vô hình. Qua thí nghiệm, các nhà khoa học phát hiện chất dinh dưỡng và thông tin đều có thể truyền qua tấm lưới này từ cây này sang cây khác. Có người đặt cho nó một cái tên rất hình tượng: \"Internet của rừng\".","Thú vị hơn nữa là tấm lưới này còn giúp đỡ \"người nhà\". Các nhà nghiên cứu phát hiện một số cây cổ thụ cao lớn sẽ thông qua mạng lưới dưới đất mà chuyển chất dinh dưỡng dư thừa cho những cây non gần đó, nhất là những cây mọc dưới tán cây lớn, không được phơi nắng. Còn khi một cây già sắp chết, nó sẽ cố gắng chuyển hết chất dinh dưỡng còn lại trong cơ thể ra ngoài. Vì vậy, có nhà khoa học gọi những cây già này là \"cây mẹ\".","Tất nhiên, cũng có nhà khoa học nhắc mọi người đừng tưởng tượng thực vật giống như con người. Thực vật không có não, sự \"giao tiếp\" của chúng không phải hành vi có ý thức, mà là một khả năng tự bảo vệ dần hình thành qua thời gian dài đằng đẵng. Dùng những từ như \"nói chuyện\", \"giúp đỡ\", \"mẹ\" để miêu tả thực vật chỉ là để người bình thường dễ hiểu hơn, chứ không có nghĩa thực vật thật sự có tình cảm.","Dù vậy, những nghiên cứu này cũng đã thay đổi cách chúng ta nhìn nhận tự nhiên. Trước đây, người ta thường coi một cái cây là một cá thể riêng lẻ; giờ đây chúng ta biết rằng khu rừng giống một đại gia đình gắn bó chặt chẽ hơn. Chặt đi một cây cổ thụ, thứ bị ảnh hưởng có thể không chỉ là cây đó, mà là cuộc sống của rất nhiều cây cối xung quanh.","Những phát hiện này cũng có ích thực tế cho nông nghiệp. Nếu hiểu rõ thực vật truyền tín hiệu cho nhau như thế nào, có lẽ nông dân sẽ dùng ít thuốc trừ sâu hơn, để cây trồng tự \"nhắc\" nhau phòng sâu từ sớm. Hiện nay, đã có nhà khoa học tiến hành thử nghiệm về mặt này.","Lần tới khi bước vào công viên hay khu rừng, bạn thử dừng lại, lặng lẽ đứng một lúc xem. Biết đâu ngay bên cạnh bạn, cây cối và hoa cỏ đang có một cuộc \"trò chuyện\" rôm rả. Chỉ có điều, thứ chúng dùng không phải âm thanh, mà là một thứ ngôn ngữ chúng ta vẫn chưa hoàn toàn hiểu được."],"questions":[{"q":"非洲草原上的动物为什么吃一会儿就换一棵树？","q_vi":"Vì sao con vật trên thảo nguyên châu Phi ăn một lúc lại đổi sang cây khác?","options":["因为附近的树叶已经吃完了","因为附近的树叶变苦了","因为它们喜欢走路","因为远处的树更高"],"answer":1,"explain_vi":"Đoạn 3: cây bị ăn tạo chất đắng và tỏa khí báo hiệu, cây gần đó cũng làm lá đắng nên con vật phải đi xa."},{"q":"“森林的互联网”指的是什么？","q_vi":"\"Internet của rừng\" chỉ cái gì?","options":["森林里的电话线","树叶放出的气体","动物之间的叫声","地下由树根和细小生物组成的网"],"answer":3,"explain_vi":"Đoạn 5: sinh vật nhỏ trong đất gắn với rễ cây tạo thành mạng lưới vô hình truyền dinh dưỡng và thông tin."},{"q":"关于“树妈妈”，下面哪一项是正确的？","q_vi":"Về \"cây mẹ\", điều nào dưới đây đúng?","options":["老树会把营养送给附近的小树","老树会阻止小树长大","老树会自己走到小树旁边","老树只照顾自己的孩子"],"answer":0,"explain_vi":"Đoạn 6: cây già chuyển dinh dưỡng dư thừa cho cây non gần đó, nên được gọi là \"cây mẹ\"."},{"q":"第七段作者想提醒读者什么？","q_vi":"Ở đoạn 7, tác giả muốn nhắc người đọc điều gì?","options":["植物比人更聪明","植物的交流方式还没有被证明","植物的“交流”不是有意识的，不能和人完全一样看待","研究植物没有什么意义"],"answer":2,"explain_vi":"Đoạn 7: thực vật không có não, \"giao tiếp\" của chúng không có ý thức; các từ như \"mẹ\" chỉ để dễ hiểu."},{"q":"这篇文章主要想告诉我们什么？","q_vi":"Bài viết chủ yếu muốn nói với chúng ta điều gì?","options":["怎样种好西红柿","植物之间存在着我们过去不了解的联系方式","非洲草原上的动物生活","怎样保护森林里的动物"],"answer":1,"explain_vi":"Toàn bài giới thiệu các cách thực vật \"trò chuyện\" với nhau qua không khí và lòng đất — điều trước đây ta không biết."}],"beyond":[["同伴","tóngbàn","ĐỒNG BẠN","bạn đồng hành, bạn bè, bạn cùng nhóm"],["同一","tóngyī","ĐỒNG NHẤT","đồng nhất, giống nhau · cùng một, giống nhau"],["不见","bùjiàn","BẤT KIẾN","không thấy, biến mất; không gặp"],["而已","ér yǐ","NHI DĨ","chỉ vậy thôi · mà thôi"],["非洲","Fēizhōu","PHI CHÂU","Châu Phi"],["气味","qìwèi","KHÍ VỊ","Mùi hương, mùi vị · mùi"],["生物","shēngwù","SINH VẬT","Sinh vật"],["有意识","yǒuyìshí","HỮU Ý THỨC","có chủ ý, có ý thức"],["普通人","pǔtōng rén","PHỔ THÔNG NHÂN","người bình thường, dân thường"],["当作","dàngzuò","ĐÁNG TÁC","coi là, xem như là"],["大家庭","dàjiātíng","ĐẠI GIA ĐÌNH","đại gia đình, tập thể lớn đoàn kết"],["用处","yòngchù","DỤNG XỬ","công dụng, tác dụng, ích lợi"],["庄稼","zhuāngjia","TRANG GIÁ","hoa màu, cây trồng nông nghiệp"],["不妨","bù fáng","BẤT PHƯƠNG","không ngại, có thể · chẳng ngại, có thể làm xem sao (Biểu thị có thể làm như vậy, không có gì trở ngại cả)"],["树木","shùmù","THỤ MỘC","cây cối"]]},{"id":"h5-03","level":5,"title":"外卖时代的厨房","title_vi":"Căn bếp trong thời đại đồ ăn giao tận nơi","topic":"xã hội hiện đại","chars":1065,"paragraphs":["晚上七点，办公楼的电梯门一开，几个年轻人提着刚送到的外卖走了出来。对今天的很多城市人来说，这是再普通不过的画面。打开手机，动动手指，半个小时以后，热腾腾的饭菜就送到了门口。外卖的出现，让“吃饭”这件事比以前方便多了。","根据一些调查，在大城市里，相当一部分年轻人每周点外卖超过五次，有的人甚至一日三餐都靠外卖解决。家里的厨房越来越干净，不是因为主人爱打扫，而是因为它几乎没有被使用过。有人开玩笑说，现在不少年轻人的冰箱里，除了饮料，就只剩下几个过期的鸡蛋。","外卖受欢迎，原因并不难理解。首先是节省时间。在快节奏的城市里，很多人下班回家已经很累了，再去买菜、洗菜、做饭、洗碗，至少要花一个多小时。其次是选择多。一个人做饭，往往只能做一两个菜，而在外卖软件上，可以吃到来自全国各地甚至世界各国的美食。另外，对于不会做饭的人来说，外卖几乎是唯一的选择。","然而，外卖带来的问题也越来越明显。第一是健康问题。为了让味道更吸引人，一些外卖的油和盐放得特别多；而且长期吃外卖的人，往往蔬菜吃得少，营养不够全面。第二是环境问题。每一份外卖都离不开塑料盒、塑料袋和用完就扔的筷子，每天产生的垃圾数量十分惊人。","除此以外，还有一个不太容易被注意到的问题：我们正在失去一种生活的能力，以及这种能力带来的乐趣。做饭不仅仅是为了吃饱。挑选新鲜的材料，按照自己的口味调整做法，看着一盘菜从无到有，这个过程本身就能让人放松。很多人回忆起小时候，印象最深的不是去过什么高级饭店，而是妈妈在厨房里忙来忙去的背影和满屋子的饭菜香。","我的朋友小周就是一个例子。她曾经是“外卖专家”，手机里装着四五个外卖软件，每个月光外卖就要花掉两三千块钱。去年体检的时候，有几项结果不太理想，医生建议她改变饮食习惯。她这才下决心学做饭。刚开始，她不是把菜炒糊了，就是把汤做得太咸，有好几次差点儿放弃。","半年后，小周已经能做出一桌像样的家常菜了。她说，最大的变化不是省了钱，也不是瘦了几斤，而是生活的节奏慢了下来。“以前下班回家就躺在沙发上玩手机，等外卖。现在我会一边听音乐一边切菜，做饭的那一个小时，是我一天中最安静的时候。”周末，她还经常请朋友来家里吃饭，原来冷冷清清的出租房变得热闹了起来。","当然，我们并不需要因此完全拒绝外卖。对于工作忙碌的人来说，外卖确实是一种解决问题的好办法；它也给成千上万的送餐员提供了工作机会。问题不在于外卖本身，而在于我们是不是把它当成了唯一的选择。","也许，我们可以试着找到一种平衡：工作日忙的时候点外卖，周末有空的时候自己下厨；点外卖时选择少油少盐的饭菜，并主动告诉商家不需要筷子。这些小小的改变，既不会让生活变得麻烦，又能让我们吃得更健康，也给地球减少一点儿负担。","毕竟，厨房不只是一个做饭的地方，它还连着我们和家人、和朋友、和自己的生活。偶尔让厨房重新热闹起来，也许你会发现，最好吃的那顿饭，就是自己亲手做的。"],"pinyin":["wǎn shang qī diǎn bàn gōng lóu de diàn tī mén yī kāi jǐ gè nián qīng rén tí zhe gāng sòng dào de wài mài zǒu le chū lái duì jīn tiān de hěn duō chéng shì rén lái shuō zhè shì zài pǔ tōng bù guò de huà miàn dǎ kāi shǒu jī dòng dòng shǒu zhǐ bàn gè xiǎo shí yǐ hòu rè téng téng de fàn cài jiù sòng dào le mén kǒu wài mài de chū xiàn ràng chī fàn zhè jiàn shì bǐ yǐ qián fāng biàn duō le","gēn jù yī xiē diào chá zài dà chéng shì lǐ xiāng dāng yī bù fen nián qīng rén měi zhōu diǎn wài mài chāo guò wǔ cì yǒu de rén shèn zhì yī rì sān cān dōu kào wài mài jiě jué jiā lǐ de chú fáng yuè lái yuè gān jìng bú shì yīn wèi zhǔ rén ài dǎ sǎo ér shì yīn wèi tā jī hū méi yǒu bèi shǐ yòng guò yǒu rén kāi wán xiào shuō xiàn zài bù shǎo nián qīng rén de bīng xiāng lǐ chú le yǐn liào jiù zhǐ shèng xià jǐ gè guò qī de jī dàn","wài mài shòu huān yíng yuán yīn bìng bù nán lǐ jiě shǒu xiān shì jié shěng shí jiān zài kuài jié zòu de chéng shì lǐ hěn duō rén xià bān huí jiā yǐ jīng hěn lèi le zài qù mǎi cài xǐ cài zuò fàn xǐ wǎn zhì shǎo yào huā yí gè duō xiǎo shí qí cì shì xuǎn zé duō yí gè rén zuò fàn wǎng wǎng zhǐ néng zuò yī liǎng gè cài ér zài wài mài ruǎn jiàn shàng kě yǐ chī dào lái zì quán guó gè dì shèn zhì shì jiè gè guó de měi shí lìng wài duì yú bú huì zuò fàn de rén lái shuō wài mài jī hū shì wéi yī de xuǎn zé","rán ér wài mài dài lái de wèn tí yě yuè lái yuè míng xiǎn dì yī shì jiàn kāng wèn tí wèi le ràng wèi dào gèng xī yǐn rén yī xiē wài mài de yóu hé yán fàng dé tè bié duō ér qiě cháng qī chī wài mài de rén wǎng wǎng shū cài chī de shǎo yíng yǎng bù gòu quán miàn dì èr shì huán jìng wèn tí měi yī fèn wài mài dōu lí bù kāi sù liào hé sù liào dài hé yòng wán jiù rēng de kuài zi měi tiān chǎn shēng de lā jī shù liàng shí fēn jīng rén","chú cǐ yǐ wài hái yǒu yí gè bù tài róng yì bèi zhù yì dào de wèn tí wǒ men zhèng zài shī qù yī zhǒng shēng huó de néng lì yǐ jí zhè zhǒng néng lì dài lái de lè qù zuò fàn bù jǐn jǐn shì wèi le chī bǎo tiāo xuǎn xīn xiān de cái liào àn zhào zì jǐ de kǒu wèi tiáo zhěng zuò fǎ kàn zhe yī pán cài cóng wú dào yǒu zhè ge guò chéng běn shēn jiù néng ràng rén fàng sōng hěn duō rén huí yì qǐ xiǎo shí hou yìn xiàng zuì shēn de bú shì qù guò shén me gāo jí fàn diàn ér shì mā ma zài chú fáng lǐ máng lái máng qù de bèi yǐng hé mǎn wū zi de fàn cài xiāng","wǒ de péng you xiǎo zhōu jiù shì yí gè lì zi tā céng jīng shì wài mài zhuān jiā shǒu jī lǐ zhuāng zhe sì wǔ gè wài mài ruǎn jiàn měi gè yuè guāng wài mài jiù yào huā diào liǎng sān qiān kuài qián qù nián tǐ jiǎn de shí hou yǒu jǐ xiàng jié guǒ bù tài lǐ xiǎng yī shēng jiàn yì tā gǎi biàn yǐn shí xí guàn tā zhè cái xià jué xīn xué zuò fàn gāng kāi shǐ tā bú shì bǎ cài chǎo hú le jiù shì bǎ tāng zuò de tài xián yǒu hǎo jǐ cì chà diǎn ér fàng qì","bàn nián hòu xiǎo zhōu yǐ jīng néng zuò chū yī zhuō xiàng yàng de jiā cháng cài le tā shuō zuì dà de biàn huà bú shì shěng le qián yě bú shì shòu le jǐ jīn ér shì shēng huó de jié zòu màn le xià lái yǐ qián xià bān huí jiā jiù tǎng zài shā fā shàng wán shǒu jī děng wài mài xiàn zài wǒ huì yī biān tīng yīn yuè yī biān qiè cài zuò fàn de nà yí gè xiǎo shí shì wǒ yī tiān zhōng zuì ān jìng de shí hou zhōu mò tā hái jīng cháng qǐng péng you lái jiā lǐ chī fàn yuán lái lěng lěng qīng qīng de chū zū fáng biàn dé rè nao le qǐ lái","dāng rán wǒ men bìng bù xū yào yīn cǐ wán quán jù jué wài mài duì yú gōng zuò máng lù de rén lái shuō wài mài què shí shì yī zhǒng jiě jué wèn tí de hǎo bàn fǎ tā yě gěi chéng qiān shàng wàn de sòng cān yuán tí gōng le gōng zuò jī huì wèn tí bù zài yú wài mài běn shēn ér zài yú wǒ men shì bú shì bǎ tā dàng chéng le wéi yī de xuǎn zé","yě xǔ wǒ men kě yǐ shì zhe zhǎo dào yī zhǒng píng héng gōng zuò rì máng de shí hou diǎn wài mài zhōu mò yǒu kòng de shí hou zì jǐ xià chú diǎn wài mài shí xuǎn zé shǎo yóu shǎo yán de fàn cài bìng zhǔ dòng gào su shāng jiā bù xū yào kuài zi zhè xiē xiǎo xiǎo de gǎi biàn jì bú huì ràng shēng huó biàn dé má fan yòu néng ràng wǒ men chī de gèng jiàn kāng yě gěi dì qiú jiǎn shǎo yì diǎn ér fù dān","bì jìng chú fáng bù zhǐ shì yí gè zuò fàn de dì fang tā hái lián zhe wǒ men hé jiā rén hé péng you hé zì jǐ de shēng huó ǒu ěr ràng chú fáng chóng xīn rè nao qǐ lái yě xǔ nǐ huì fā xiàn zuì hǎo chī de nà dùn fàn jiù shì zì jǐ qīn shǒu zuò de"],"translations":["Bảy giờ tối, cửa thang máy của tòa văn phòng vừa mở, mấy người trẻ xách đồ ăn vừa được giao tới bước ra. Với nhiều người thành phố ngày nay, đây là cảnh tượng bình thường không thể bình thường hơn. Mở điện thoại, động vài ngón tay, nửa tiếng sau cơm canh nóng hổi đã được đưa tới tận cửa. Sự xuất hiện của dịch vụ giao đồ ăn khiến chuyện \"ăn cơm\" tiện hơn trước rất nhiều.","Theo một số khảo sát, ở các thành phố lớn, khá nhiều người trẻ đặt đồ ăn hơn năm lần mỗi tuần, có người thậm chí ba bữa một ngày đều trông cả vào đồ ăn giao tận nơi. Căn bếp trong nhà ngày càng sạch sẽ, không phải vì chủ nhà chăm dọn dẹp mà vì nó gần như chưa từng được dùng đến. Có người đùa rằng, tủ lạnh của nhiều bạn trẻ bây giờ ngoài đồ uống ra thì chỉ còn mấy quả trứng đã quá hạn.","Đồ ăn giao tận nơi được ưa chuộng, lý do không khó hiểu. Trước hết là tiết kiệm thời gian. Ở thành phố nhịp sống nhanh, nhiều người tan làm về nhà đã rất mệt, nếu còn đi chợ, rửa rau, nấu cơm, rửa bát thì ít nhất mất hơn một tiếng. Thứ hai là nhiều lựa chọn. Một người nấu ăn thường chỉ làm được một hai món, còn trên ứng dụng giao đồ ăn có thể ăn món ngon từ khắp cả nước, thậm chí khắp thế giới. Ngoài ra, với người không biết nấu ăn, đồ ăn giao tận nơi gần như là lựa chọn duy nhất.","Thế nhưng, những vấn đề do đồ ăn giao tận nơi mang lại cũng ngày càng rõ. Thứ nhất là sức khỏe. Để món ăn hấp dẫn hơn, một số quán cho rất nhiều dầu và muối; hơn nữa người ăn đồ giao lâu ngày thường ăn ít rau, dinh dưỡng không đầy đủ. Thứ hai là môi trường. Mỗi suất ăn đều không thể thiếu hộp nhựa, túi nhựa và đũa dùng một lần, lượng rác thải ra mỗi ngày nhiều đến kinh ngạc.","Ngoài ra còn một vấn đề không dễ nhận ra: chúng ta đang đánh mất một kỹ năng sống, cùng với niềm vui mà kỹ năng ấy đem lại. Nấu ăn không chỉ để no bụng. Chọn nguyên liệu tươi, điều chỉnh cách nấu theo khẩu vị của mình, nhìn một đĩa thức ăn từ không thành có — bản thân quá trình ấy đã giúp người ta thư giãn. Nhiều người nhớ lại thời thơ ấu, ấn tượng sâu sắc nhất không phải là từng đến nhà hàng sang trọng nào, mà là bóng lưng mẹ tất bật trong bếp và mùi thơm cơm canh khắp nhà.","Cô bạn Tiểu Chu của tôi là một ví dụ. Cô từng là \"chuyên gia đặt đồ ăn\", điện thoại cài bốn năm ứng dụng giao đồ ăn, mỗi tháng riêng tiền đồ ăn đã tiêu mất hai ba nghìn tệ. Năm ngoái khi khám sức khỏe, có vài chỉ số không được tốt, bác sĩ khuyên cô thay đổi thói quen ăn uống. Lúc ấy cô mới quyết tâm học nấu ăn. Ban đầu, không phải xào cháy món ăn thì cũng nấu canh quá mặn, mấy lần suýt bỏ cuộc.","Nửa năm sau, Tiểu Chu đã nấu được một mâm cơm nhà ra trò. Cô nói, thay đổi lớn nhất không phải tiết kiệm được tiền hay gầy đi mấy cân, mà là nhịp sống chậm lại. \"Trước đây tan làm về là nằm dài trên sofa nghịch điện thoại chờ đồ ăn. Giờ tôi vừa nghe nhạc vừa thái rau, một tiếng nấu ăn ấy là lúc yên tĩnh nhất trong ngày của tôi.\" Cuối tuần, cô còn hay mời bạn bè đến nhà ăn cơm, căn phòng thuê vốn vắng vẻ nay trở nên rộn ràng.","Tất nhiên, chúng ta không cần vì thế mà hoàn toàn từ chối đồ ăn giao tận nơi. Với người bận rộn, đó quả thực là một cách giải quyết tốt; nó cũng mang lại việc làm cho hàng nghìn hàng vạn người giao hàng. Vấn đề không nằm ở bản thân việc giao đồ ăn, mà ở chỗ chúng ta có coi nó là lựa chọn duy nhất hay không.","Có lẽ chúng ta có thể thử tìm một sự cân bằng: ngày làm việc bận thì đặt đồ ăn, cuối tuần rảnh thì tự vào bếp; khi đặt thì chọn món ít dầu ít muối, và chủ động báo cửa hàng không cần đũa. Những thay đổi nho nhỏ ấy vừa không làm cuộc sống phiền phức, lại giúp ta ăn uống lành mạnh hơn, cũng giảm bớt một chút gánh nặng cho Trái Đất.","Suy cho cùng, căn bếp không chỉ là nơi nấu ăn, nó còn nối chúng ta với gia đình, với bạn bè và với cuộc sống của chính mình. Thỉnh thoảng để căn bếp náo nhiệt trở lại, có lẽ bạn sẽ phát hiện ra bữa cơm ngon nhất chính là bữa do tự tay mình nấu."],"questions":[{"q":"第二段中“冰箱里只剩下几个过期的鸡蛋”说明了什么？","q_vi":"Câu \"tủ lạnh chỉ còn mấy quả trứng quá hạn\" ở đoạn 2 cho thấy điều gì?","options":["年轻人很喜欢吃鸡蛋","年轻人很少在家做饭","年轻人的冰箱太小了","鸡蛋的价格越来越高"],"answer":1,"explain_vi":"Đây là câu nói đùa minh họa việc bếp gần như không được dùng, tức người trẻ hiếm khi tự nấu."},{"q":"下面哪一项不是文章提到的外卖受欢迎的原因？","q_vi":"Điều nào dưới đây KHÔNG phải lý do được nhắc đến khiến đồ ăn giao tận nơi được ưa chuộng?","options":["节省时间","选择很多","比自己做饭更健康","不会做饭的人也能吃好"],"answer":2,"explain_vi":"Đoạn 3 nêu: tiết kiệm thời gian, nhiều lựa chọn, người không biết nấu cũng có cái ăn. Còn sức khỏe lại là một vấn đề của đồ ăn giao (đoạn 4)."},{"q":"小周为什么开始学做饭？","q_vi":"Vì sao Tiểu Chu bắt đầu học nấu ăn?","options":["体检结果不太好，医生建议她改变饮食习惯","外卖软件都不能用了","她想开一家饭店","她的朋友都会做饭"],"answer":0,"explain_vi":"Đoạn 6: khám sức khỏe có vài chỉ số không tốt, bác sĩ khuyên đổi thói quen ăn uống."},{"q":"对小周来说，学会做饭后最大的变化是什么？","q_vi":"Với Tiểu Chu, thay đổi lớn nhất sau khi biết nấu ăn là gì?","options":["省了很多钱","瘦了几斤","找到了新工作","生活的节奏慢了下来"],"answer":3,"explain_vi":"Đoạn 7: cô nói thay đổi lớn nhất không phải tiết kiệm tiền hay giảm cân, mà là nhịp sống chậm lại."},{"q":"作者对外卖的态度是什么？","q_vi":"Thái độ của tác giả đối với đồ ăn giao tận nơi là gì?","options":["应该完全拒绝外卖","外卖没有任何问题","可以点外卖，但不要把它当成唯一的选择","只有周末才能点外卖"],"answer":2,"explain_vi":"Đoạn 8–9: không cần từ chối hoàn toàn, vấn đề là đừng coi nó là lựa chọn duy nhất, nên tìm sự cân bằng."}],"beyond":[["办公","bàngōng","BIỆN CÔNG","làm việc văn phòng, xử lý công vụ"],["热腾腾","rèténgténg","NHIỆT ĐẰNG ĐẰNG","nóng hổi, nóng hôi hổi, bốc khói nghi ngút"],["不难","bù nán","BẤT NAN","không khó"],["节奏","jié zòu","TIẾT TẤU","nhịp điệu, tiết tấu · nhịp điệu, tiết tấu, nhịp (sự xuất hiện đan xen có quy luật của các hiện tượng mạnh yếu…"],["惊人","jīngrén","KINH NHÂN","kinh ngạc, đáng sửng sốt, phi thường"],["不仅仅","bù jǐnjǐn","BẤT CẬN CẬN","không chỉ, không đơn thuần"],["本身","běn shēn","BẢN THÂN","bản thân · bản thân, tự mình"],["背影","bèiyǐng","BỐI ẢNH","bóng dáng từ phía sau, bóng lưng (Hình ảnh cơ thể nhìn từ phía mặt sau lưng)"],["下决心","xià juéxīn","HẠ QUYẾT TÂM","hạ quyết tâm, quyết tâm"],["像样","xiàngyàng","TƯỢNG DẠNG","ra hồn, đàng hoàng, coi được"],["家常","jiā cháng","GIA THƯỜNG","thường ngày"],["忙碌","mánglù","MANG LỤC","Bận rộn"],["成千上万","chéngqiān-shàngwàn","THÀNH THIÊN THƯỢNG VẠN","hàng ngàn hàng vạn; vô số kể; hàng vạn"],["当成","dàngchéng","ĐÁNG THÀNH","coi là, xem như là"],["亲手","qīnshǒu","THÂN THỦ","đích thân, tự tay"]]},{"id":"h5-04","level":5,"title":"爷爷的“时间表”","title_vi":"\"Thời gian biểu\" của ông nội","topic":"văn hóa Trung Quốc","chars":1027,"paragraphs":["小时候，我在农村跟爷爷奶奶生活过几年。爷爷认识的字不多，却能准确地说出什么时候该种什么、收什么。每到一个特别的日子，他就会说一句：“清明前后，种瓜种豆。”那时我不明白，这些听起来像儿歌一样的话是从哪儿来的。长大后我才知道，爷爷说的，是中国古人留下的“二十四节气”。","所谓节气，简单地说，就是古人根据太阳在一年中位置的变化，把一年分成二十四段，每一段大约十五天，并给每一段起一个名字。比如“立春”表示春天开始了，“雨水”说明下雨的日子渐渐多了起来，“惊蛰”的意思是天上开始打雷，把在土里睡了一冬的小虫子都叫醒了。","二十四节气产生于黄河一带，已经有两千多年的历史。在没有天气预报的古代，农民主要靠它来安排一年的农活：什么时候种地，什么时候浇水，什么时候收粮食，都和节气有着密切的关系。可以说，节气就是古代农民手中的一张“时间表”。","有趣的是，节气不仅对农业有用，也和人们的日常生活紧紧地连在一起。很多节气都有自己的风俗和美食。立春这一天，北方人要吃春饼，表示迎接春天；冬至这一天，北方人吃饺子，南方人吃汤圆，民间还有“冬至大如年”的说法。到了立秋，有的地方要吃肉，意思是夏天天气热，人吃得少、瘦了，秋天要把肉补回来。","节气里还藏着古人对自然的仔细观察。古人把每个节气又分成三小段，每段五天，每一段都对应一种自然现象。例如，在立春的十五天里，先是春风吹来，冰开始化了；接着，睡了一冬的虫子开始动了；最后，鱼游到水面上，好像背着还没化完的冰块。读到这些描写，你不得不佩服古人观察的耐心。","那么，在现代社会，二十四节气还有用吗？有人认为，现在有了科学的天气预报，农业也越来越现代化，节气已经过时了。而且由于全球气候变化，有些节气的说法和实际情况并不完全一样。比如到了“小雪”，南方很多城市的人可能还穿着短袖。","不过，更多的人认为，节气的价值并不只在于指导农业。2016年，二十四节气被正式列为世界非物质文化遗产，这说明它已经被看作人类共同的文化财富。对生活在城市里的人来说，节气提醒我们：在高楼大厦之间，仍然有季节的变化，仍然有自然的节奏。","这些年，我发现身边越来越多的年轻人开始关注节气。有人每到一个节气就在网上分享一张照片，有人按照节气调整自己的饮食，比如夏天多喝绿豆汤，秋天多吃梨。还有一些学校把节气的知识带进课堂，带孩子们去田里看麦子怎样一天天变黄。","去年冬至，我特意回了一趟老家。爷爷已经八十多岁了，耳朵也不太好，可是一说到节气，他的眼睛就亮了起来。他一边包饺子，一边给我讲“数九”的老规矩：从冬至这天开始，每九天为一个“九”，数完九个“九”，春天就来了。“到那时候啊，天暖和了，地里又该忙起来了。”他说完，得意地笑了。","那一刻我忽然明白，节气不是书本上冷冰冰的知识，而是一代又一代人对生活的记忆。它让我们记住，人是自然的一部分；无论时代怎么变，冬天过去，春天总会到来。"],"pinyin":["xiǎo shí hou wǒ zài nóng cūn gēn yé ye nǎi nai shēng huó guò jǐ nián yé ye rèn shi de zì bù duō què néng zhǔn què de shuō chū shén me shí hou gāi zhǒng shén me shōu shén me měi dào yí gè tè bié de rì zi tā jiù huì shuō yī jù qīng míng qián hòu zhǒng guā zhǒng dòu nà shí wǒ bù míng bai zhè xiē tīng qǐ lái xiàng ér gē yī yàng de huà shì cóng nǎ ér lái de zhǎng dà hòu wǒ cái zhī dao yé ye shuō de shì zhōng guó gǔ rén liú xià de èr shí sì jié qì","suǒ wèi jié qì jiǎn dān dì shuō jiù shì gǔ rén gēn jù tài yáng zài yī nián zhōng wèi zhì de biàn huà bǎ yī nián fēn chéng èr shí sì duàn měi yī duàn dà yuē shí wǔ tiān bìng gěi měi yī duàn qǐ yí gè míng zi bǐ rú lì chūn biǎo shì chūn tiān kāi shǐ le yǔ shuǐ shuō míng xià yǔ de rì zi jiàn jiàn duō le qǐ lái jīng zhé de yì si shì tiān shàng kāi shǐ dǎ léi bǎ zài tǔ lǐ shuì le yī dōng de xiǎo chóng zi dōu jiào xǐng le","èr shí sì jié qì chǎn shēng yú huáng hé yī dài yǐ jīng yǒu liǎng qiān duō nián de lì shǐ zài méi yǒu tiān qì yù bào de gǔ dài nóng mín zhǔ yào kào tā lái ān pái yī nián de nóng huó shén me shí hou zhòng dì shén me shí hou jiāo shuǐ shén me shí hou shōu liáng shí dōu hé jié qì yǒu zhe mì qiè de guān xi kě yǐ shuō jié qì jiù shì gǔ dài nóng mín shǒu zhōng de yī zhāng shí jiān biǎo","yǒu qù de shì jié qì bù jǐn duì nóng yè yǒu yòng yě hé rén men de rì cháng shēng huó jǐn jǐn de lián zài yì qǐ hěn duō jié qì dōu yǒu zì jǐ de fēng sú hé měi shí lì chūn zhè yī tiān běi fāng rén yào chī chūn bǐng biǎo shì yíng jiē chūn tiān dōng zhì zhè yī tiān běi fāng rén chī jiǎo zi nán fāng rén chī tāng yuán mín jiān hái yǒu dōng zhì dà rú nián de shuō fǎ dào le lì qiū yǒu de dì fang yào chī ròu yì si shì xià tiān tiān qì rè rén chī de shǎo shòu le qiū tiān yào bǎ ròu bǔ huí lái","jié qì lǐ hái cáng zhe gǔ rén duì zì rán de zǐ xì guān chá gǔ rén bǎ měi gè jié qì yòu fēn chéng sān xiǎo duàn měi duàn wǔ tiān měi yī duàn dōu duì yìng yī zhǒng zì rán xiàn xiàng lì rú zài lì chūn de shí wǔ tiān lǐ xiān shì chūn fēng chuī lái bīng kāi shǐ huà le jiē zhe shuì le yī dōng de chóng zi kāi shǐ dòng le zuì hòu yú yóu dào shuǐ miàn shàng hǎo xiàng bèi zhe hái méi huà wán de bīng kuài dú dào zhè xiē miáo xiě nǐ bù dé bù pèi fú gǔ rén guān chá de nài xīn","nà me zài xiàn dài shè huì èr shí sì jié qì hái yǒu yòng ma yǒu rén rèn wéi xiàn zài yǒu le kē xué de tiān qì yù bào nóng yè yě yuè lái yuè xiàn dài huà jié qì yǐ jīng guò shí le ér qiě yóu yú quán qiú qì hòu biàn huà yǒu xiē jié qì de shuō fǎ hé shí jì qíng kuàng bìng bù wán quán yī yàng bǐ rú dào le xiǎo xuě nán fāng hěn duō chéng shì de rén kě néng hái chuān zhe duǎn xiù","bù guò gèng duō de rén rèn wéi jié qì de jià zhí bìng bù zhǐ zài yú zhǐ dǎo nóng yè nián èr shí sì jié qì bèi zhèng shì liè wèi shì jiè fēi wù zhì wén huà yí chǎn zhè shuō míng tā yǐ jīng bèi kàn zuò rén lèi gòng tóng de wén huà cái fù duì shēng huó zài chéng shì lǐ de rén lái shuō jié qì tí xǐng wǒ men zài gāo lóu dà shà zhī jiān réng rán yǒu jì jié de biàn huà réng rán yǒu zì rán de jié zòu","zhè xiē nián wǒ fā xiàn shēn biān yuè lái yuè duō de nián qīng rén kāi shǐ guān zhù jié qì yǒu rén měi dào yí gè jié qì jiù zài wǎng shàng fēn xiǎng yī zhāng zhào piān yǒu rén àn zhào jié qì tiáo zhěng zì jǐ de yǐn shí bǐ rú xià tiān duō hē lǜ dòu tāng qiū tiān duō chī lí hái yǒu yī xiē xué xiào bǎ jié qì de zhī shí dài jìn kè táng dài hái zi men qù tián lǐ kàn mài zi zěn yàng yī tiān tiān biàn huáng","qù nián dōng zhì wǒ tè yì huí le yī tàng lǎo jiā yé ye yǐ jīng bā shí duō suì le ěr duo yě bù tài hǎo kě shì yī shuō dào jié qì tā de yǎn jing jiù liàng le qǐ lái tā yī biān bāo jiǎo zi yī biān gěi wǒ jiǎng shǔ jiǔ de lǎo guī jǔ cóng dōng zhì zhè tiān kāi shǐ měi jiǔ tiān wèi yí gè jiǔ shù wán jiǔ gè jiǔ chūn tiān jiù lái le dào nà shí hou a tiān nuǎn huo le dì lǐ yòu gāi máng qǐ lái le tā shuō wán dé yì dì xiào le","nà yī kè wǒ hū rán míng bai jié qì bú shì shū běn shàng lěng bīng bīng de zhī shí ér shì yí dài yòu yí dài rén duì shēng huó de jì yì tā ràng wǒ men jì zhù rén shì zì rán de yī bù fen wú lùn shí dài zěn me biàn dōng tiān guò qù chūn tiān zǒng huì dào lái"],"translations":["Hồi nhỏ, tôi từng sống với ông bà nội ở quê vài năm. Ông biết không nhiều chữ, nhưng lại nói chính xác được khi nào nên trồng gì, thu hoạch gì. Cứ đến một ngày đặc biệt, ông lại nói một câu: \"Quanh tiết Thanh minh, trồng dưa trồng đậu.\" Hồi đó tôi không hiểu những câu nghe như đồng dao ấy từ đâu mà có. Lớn lên tôi mới biết, điều ông nói chính là \"hai mươi bốn tiết khí\" người xưa của Trung Quốc để lại.","Cái gọi là tiết khí, nói đơn giản, là người xưa dựa vào sự thay đổi vị trí của mặt trời trong một năm mà chia năm thành hai mươi bốn đoạn, mỗi đoạn khoảng mười lăm ngày, và đặt cho mỗi đoạn một cái tên. Chẳng hạn \"Lập xuân\" nghĩa là mùa xuân bắt đầu, \"Vũ thủy\" cho biết những ngày mưa dần nhiều lên, \"Kinh trập\" có nghĩa trời bắt đầu có sấm, đánh thức những con sâu bọ đã ngủ suốt mùa đông dưới đất.","Hai mươi bốn tiết khí ra đời ở vùng Hoàng Hà, đã có lịch sử hơn hai nghìn năm. Thời xưa chưa có dự báo thời tiết, nông dân chủ yếu dựa vào nó để sắp xếp việc đồng áng cả năm: khi nào làm đất, khi nào tưới nước, khi nào thu lương thực đều có quan hệ mật thiết với tiết khí. Có thể nói, tiết khí chính là tờ \"thời gian biểu\" trong tay người nông dân thời xưa.","Thú vị là tiết khí không chỉ có ích cho nông nghiệp, mà còn gắn chặt với đời sống hằng ngày. Nhiều tiết khí có phong tục và món ăn riêng. Ngày Lập xuân, người miền Bắc ăn bánh xuân để đón mùa xuân; ngày Đông chí, người miền Bắc ăn sủi cảo, người miền Nam ăn bánh trôi, dân gian còn có câu \"Đông chí lớn như Tết\". Đến Lập thu, có nơi phải ăn thịt, ý là mùa hè trời nóng, người ăn ít nên gầy đi, sang thu phải bồi bổ lại.","Trong tiết khí còn ẩn chứa sự quan sát tỉ mỉ của người xưa đối với tự nhiên. Người xưa lại chia mỗi tiết khí thành ba đoạn nhỏ, mỗi đoạn năm ngày, mỗi đoạn ứng với một hiện tượng tự nhiên. Ví dụ, trong mười lăm ngày Lập xuân, trước tiên gió xuân thổi tới, băng bắt đầu tan; tiếp đó, sâu bọ ngủ suốt mùa đông bắt đầu cựa quậy; cuối cùng, cá bơi lên mặt nước như đang cõng những tảng băng chưa tan hết. Đọc những dòng miêu tả ấy, bạn không thể không khâm phục sự kiên nhẫn quan sát của người xưa.","Vậy trong xã hội hiện đại, hai mươi bốn tiết khí còn có ích không? Có người cho rằng giờ đã có dự báo thời tiết khoa học, nông nghiệp cũng ngày càng hiện đại, tiết khí đã lỗi thời. Hơn nữa do biến đổi khí hậu toàn cầu, cách nói của một số tiết khí không hoàn toàn khớp với thực tế. Chẳng hạn đến tiết \"Tiểu tuyết\", người ở nhiều thành phố miền Nam có khi vẫn mặc áo cộc tay.","Tuy vậy, nhiều người hơn cho rằng giá trị của tiết khí không chỉ nằm ở việc chỉ dẫn nông nghiệp. Năm 2016, hai mươi bốn tiết khí chính thức được công nhận là di sản văn hóa phi vật thể thế giới, cho thấy nó đã được coi là tài sản văn hóa chung của nhân loại. Với người sống ở thành phố, tiết khí nhắc chúng ta rằng: giữa những tòa nhà cao tầng, vẫn có sự đổi thay của mùa, vẫn có nhịp điệu của thiên nhiên.","Mấy năm nay, tôi thấy ngày càng nhiều người trẻ quanh mình bắt đầu quan tâm đến tiết khí. Có người cứ đến một tiết khí lại chia sẻ một bức ảnh lên mạng, có người điều chỉnh việc ăn uống theo tiết khí, chẳng hạn mùa hè uống nhiều chè đậu xanh, mùa thu ăn nhiều lê. Còn có trường học đưa kiến thức về tiết khí vào lớp học, dẫn các em ra đồng xem lúa mì vàng dần từng ngày.","Đông chí năm ngoái, tôi cố ý về quê một chuyến. Ông đã ngoài tám mươi, tai cũng không còn thính, nhưng hễ nói đến tiết khí là mắt ông sáng lên. Ông vừa gói sủi cảo vừa kể cho tôi nghe lệ cũ \"đếm chín\": bắt đầu từ ngày Đông chí, cứ chín ngày là một \"chín\", đếm xong chín cái \"chín\" thì mùa xuân đến. \"Đến lúc ấy à, trời ấm lên, ngoài đồng lại bận rộn rồi.\" Nói xong, ông cười đắc ý.","Khoảnh khắc ấy tôi chợt hiểu, tiết khí không phải là kiến thức khô khan trên trang sách, mà là ký ức về cuộc sống của bao thế hệ. Nó giúp ta nhớ rằng con người là một phần của tự nhiên; dù thời đại đổi thay thế nào, mùa đông qua đi thì mùa xuân nhất định sẽ đến."],"questions":[{"q":"“二十四节气”是根据什么来划分的？","q_vi":"\"Hai mươi bốn tiết khí\" được chia dựa vào điều gì?","options":["月亮的变化","太阳位置的变化","农民的经验","每个月的天数"],"answer":1,"explain_vi":"Đoạn 2: người xưa dựa vào sự thay đổi vị trí của mặt trời trong năm để chia thành 24 đoạn."},{"q":"在古代，节气对农民最大的作用是什么？","q_vi":"Thời xưa, tác dụng lớn nhất của tiết khí đối với nông dân là gì?","options":["决定什么时候过节","帮助他们学习认字","帮助他们安排一年的农活","告诉他们哪里能卖粮食"],"answer":2,"explain_vi":"Đoạn 3: nông dân dựa vào tiết khí để sắp xếp việc đồng áng, nó là \"thời gian biểu\" của họ."},{"q":"根据文章，冬至这一天北方人一般吃什么？","q_vi":"Theo bài, ngày Đông chí người miền Bắc thường ăn gì?","options":["饺子","汤圆","春饼","绿豆汤"],"answer":0,"explain_vi":"Đoạn 4: Đông chí người miền Bắc ăn sủi cảo (饺子), người miền Nam ăn bánh trôi (汤圆)."},{"q":"有人认为节气已经过时了，下面哪一项不是他们的理由？","q_vi":"Có người cho rằng tiết khí đã lỗi thời; điều nào dưới đây KHÔNG phải lý do của họ?","options":["现在有科学的天气预报","农业越来越现代化","气候变化让有些说法和实际不一样","年轻人都不喜欢传统文化"],"answer":3,"explain_vi":"Đoạn 6 nêu ba lý do đầu. Còn đoạn 8 lại nói ngày càng nhiều người trẻ quan tâm đến tiết khí."},{"q":"最后一段作者想表达什么？","q_vi":"Ở đoạn cuối tác giả muốn bày tỏ điều gì?","options":["节气的知识很难记住","节气包含着人们对生活的记忆和对自然的尊重","爷爷的身体越来越差了","城市里的人不需要节气"],"answer":1,"explain_vi":"Tác giả hiểu ra tiết khí là ký ức về cuộc sống của bao thế hệ, nhắc ta rằng con người là một phần của tự nhiên."}],"beyond":[["清明","qīngmíng","THANH MINH","sáng suốt, minh mẫn · sáng suốt, thanh minh; tiết Thanh minh"],["儿歌","érgē","NHI CA","đồng dao, bài hát thiếu nhi"],["古人","gǔrén","CỔ NHÂN","cổ nhân, người xưa · người xưa"],["节气","jiéqì","TIẾT KHÍ","tiết khí (trong năm)"],["所谓","suǒwèi","SỞ VỊ","cái gọi là · cái gọi là (thường mang hàm ý thực tế không hoàn toàn đúng như tên gọi)"],["黄河","Huáng Hé","HOÀNG HÀ","Hoàng Hà"],["时间表","shíjiānbiǎo","THỜI GIAN BIỂU","thời gian biểu, lịch trình"],["汤圆","tāngyuán","THANG VIÊN","bánh trôi tàu, bánh trôi nước"],["水面","shuǐmiàn","THỦY DIỆN","mặt nước"],["背着","bèizhe","BỐI TRƯỚC","cõng, vác; giấu sau lưng"],["现代化","xiàndàihuà","HIỆN ĐẠI HÓA","hiện đại hóa"],["过时","guòshí","QUÁ THỜI","lỗi thời · lỗi thời, quá hạn, lạc hậu"],["穿着","chuānzhuó","XUYÊN TRƯỚC","cách ăn mặc · trang phục, cách ăn mặc"],["袖","xiù(zi)","TỤ","tay áo"],["看作","kànzuò","KHÁN TÁC","xem như, coi là, coi như"],["节奏","jié zòu","TIẾT TẤU","nhịp điệu, tiết tấu · nhịp điệu, tiết tấu, nhịp (sự xuất hiện đan xen có quy luật của các hiện tượng mạnh yếu…"],["田","tián","ĐIỀN","ruộng, đồng ruộng"],["特意","tèyì","ĐẶC Ý","đặc ý, cố ý, có tâm (Biểu thị hành động được thực hiện dành riêng cho một mục đích cụ thể… · cố ý; đặc ý; riêng để"],["冷冰冰","lěngbīngbīng","LÃNH BĂNG BĂNG","lạnh lùng, lạnh tanh"],["一代","yīdài","NHẤT ĐẠI","một thế hệ, một đời"]]},{"id":"h5-05","level":5,"title":"母亲和“小圆”","title_vi":"Mẹ và \"Tiểu Viên\"","topic":"gia đình","chars":1017,"paragraphs":["去年春节，儿子给家里买了一台智能音箱。这东西个子不大，圆圆的，放在客厅的电视柜上，看起来像一盏小小的灯。儿子教大家怎么用：只要叫一声它的名字，再说出你的要求，它就能放音乐、讲笑话、报天气，甚至还能帮你定闹钟。","我和妻子工作忙，新鲜了几天就把它忘在了一边。倒是我母亲，对这个小东西产生了很大的兴趣。母亲今年七十三岁，三年前父亲去世后，她就从老家搬来和我们一起住。白天我们上班，孩子上学，家里常常只剩下她一个人。","一开始，母亲不太会用，总是把它的名字叫错。音箱听不懂，就回答：“对不起，我没听清楚。”母亲也不生气，一遍一遍地重复，像在教一个刚学说话的孩子。后来，她慢慢找到了方法，还给它起了个名字，叫“小圆”。每天早上一起床，她的第一件事就是问它：“小圆，今天天气怎么样？”","渐渐地，我发现母亲和它说的话越来越多了。有一天我提前下班，刚走到门口，就听见母亲在客厅里说：“小圆，你说今天包饺子好，还是做面条好？”音箱回答：“我为你找到了一个饺子的做法……”母亲笑着说：“谁让你找做法了？我包了几十年饺子，还用你教？”","我在门外站了很久，没有进去。我忽然意识到，母亲需要的并不是天气预报和做菜的方法，而是一个能跟她说话的人。可是这几年，我每天回家，吃完饭就坐在电脑前加班，或者躺在沙发上看手机。母亲有时想跟我聊几句，我总是“嗯嗯啊啊”地随便回答两句就过去了。","那天晚上，我问妻子知不知道这件事。妻子说她早就发现了：“妈每天跟它说的话，比跟我们俩加起来还多。上次她还问它，‘你一个人待着，闷不闷啊？’”说到这里，妻子的眼睛有点儿红了。","过了几个星期，音箱突然坏了，怎么叫都没有反应。母亲急得不得了，拿着它翻过来倒过去地看，还问我是不是她说话太多，把它“累坏了”。我本来打算马上在网上再买一台，但想了想，还是决定先不买。","从那天起，我和妻子商量好，每天晚饭后都留出半个小时，什么也不干，就陪母亲聊天。一开始大家都有点儿不习惯，不知道该聊什么。母亲说的多半是老家的事：哪家的孩子结婚了，以前的邻居搬到哪儿去了，年轻的时候她和父亲是怎么认识的。这些故事，有的我听过很多遍，有的却是第一次听说。","我的女儿也加入了进来。她把学校里的有趣的事讲给奶奶听，奶奶就教她剪纸、包饺子。有一次，女儿说：“奶奶，您讲的故事比音箱里的好听多了！”母亲高兴得笑个不停。","几个月后，我在整理柜子的时候，又看到了那台坏掉的音箱。我拿去修了修，原来只是里面一个小零件松了。我把它放回电视柜上，母亲看了一眼，说：“修好了？那就放着吧，早上让它报报天气。”","现在，那台音箱每天只工作一次，就是早上告诉母亲今天的天气。其他时间，它安安静静地待在那里，好像也在听我们一家人聊天。我常常想，科技可以给我们带来很多方便，却代替不了家人之间的一句问候。真正能让老人不孤单的，不是一台聪明的机器，而是愿意坐下来听她说话的我们。"],"pinyin":["qù nián chūn jié ér zi gěi jiā lǐ mǎi le yī tái zhì néng yīn xiāng zhè dōng xi gè zi bù dà yuán yuán de fàng zài kè tīng de diàn shì guì shàng kàn qǐ lái xiàng yī zhǎn xiǎo xiǎo de dēng ér zi jiào dà jiā zěn me yòng zhǐ yào jiào yī shēng tā de míng zi zài shuō chū nǐ de yāo qiú tā jiù néng fàng yīn yuè jiǎng xiào huà bào tiān qì shèn zhì hái néng bāng nǐ dìng nào zhōng","wǒ hé qī zi gōng zuò máng xīn xiān le jǐ tiān jiù bǎ tā wàng zài le yī biān dǎo shì wǒ mǔ qīn duì zhè ge xiǎo dōng xi chǎn shēng le hěn dà de xìng qù mǔ qīn jīn nián qī shí sān suì sān nián qián fù qīn qù shì hòu tā jiù cóng lǎo jiā bān lái hé wǒ men yì qǐ zhù bái tiān wǒ men shàng bān hái zi shàng xué jiā lǐ cháng cháng zhǐ shèng xià tā yí gè rén","yī kāi shǐ mǔ qīn bù tài huì yòng zǒng shì bǎ tā de míng zi jiào cuò yīn xiāng tīng bù dǒng jiù huí dá duì bù qǐ wǒ méi tīng qīng chu mǔ qīn yě bù shēng qì yī biàn yī biàn de chóng fù xiàng zài jiào yí gè gāng xué shuō huà de hái zi hòu lái tā màn màn zhǎo dào le fāng fǎ huán gěi tā qǐ le gè míng zi jiào xiǎo yuán měi tiān zǎo shang yī qǐ chuáng tā de dì yī jiàn shì jiù shì wèn tā xiǎo yuán jīn tiān tiān qì zěn me yàng","jiàn jiàn de wǒ fā xiàn mǔ qīn hé tā shuō de huà yuè lái yuè duō le yǒu yī tiān wǒ tí qián xià bān gāng zǒu dào mén kǒu jiù tīng jiàn mǔ qīn zài kè tīng lǐ shuō xiǎo yuán nǐ shuō jīn tiān bāo jiǎo zi hǎo hái shì zuò miàn tiáo hǎo yīn xiāng huí dá wǒ wèi nǐ zhǎo dào le yí gè jiǎo zi de zuò fǎ mǔ qīn xiào zhe shuō shuí ràng nǐ zhǎo zuò fǎ le wǒ bāo le jǐ shí nián jiǎo zi hái yòng nǐ jiào","wǒ zài mén wài zhàn le hěn jiǔ méi yǒu jìn qù wǒ hū rán yì shí dào mǔ qīn xū yào de bìng bú shì tiān qì yù bào hé zuò cài de fāng fǎ ér shì yí gè néng gēn tā shuō huà de rén kě shì zhè jǐ nián wǒ měi tiān huí jiā chī wán fàn jiù zuò zài diàn nǎo qián jiā bān huò zhě tǎng zài shā fā shàng kàn shǒu jī mǔ qīn yǒu shí xiǎng gēn wǒ liáo jǐ jù wǒ zǒng shì ń ń a a dì suí biàn huí dá liǎng jù jiù guò qù le","nà tiān wǎn shang wǒ wèn qī zi zhī bù zhī dao zhè jiàn shì qī zi shuō tā zǎo jiù fā xiàn le mā měi tiān gēn tā shuō de huà bǐ gēn wǒ men liǎ jiā qǐ lái hái duō shàng cì tā hái wèn tā nǐ yí gè rén dài zhe mèn bù mèn a shuō dào zhè lǐ qī zi de yǎn jing yǒu diǎn ér hóng le","guò le jǐ gè xīng qī yīn xiāng tū rán huài le zěn me jiào dōu méi yǒu fǎn yìng mǔ qīn jí dé bù dé le ná zhe tā fān guò lái dào guò qù dì kàn hái wèn wǒ shì bú shì tā shuō huà tài duō bǎ tā lèi huài le wǒ běn lái dǎ suàn mǎ shàng zài wǎng shàng zài mǎi yī tái dàn xiǎng le xiǎng hái shì jué dìng xiān bù mǎi","cóng nà tiān qǐ wǒ hé qī zi shāng liang hǎo měi tiān wǎn fàn hòu dōu liú chū bàn gè xiǎo shí shén me yě bù gàn jiù péi mǔ qīn liáo tiān yī kāi shǐ dà jiā dōu yǒu diǎn ér bù xí guàn bù zhī dao gāi liáo shén me mǔ qīn shuō de duō bàn shì lǎo jiā de shì nǎ jiā de hái zi jié hūn le yǐ qián de lín jū bān dào nǎ ér qù le nián qīng de shí hou tā hé fù qīn shì zěn me rèn shi de zhè xiē gù shì yǒu de wǒ tīng guò hěn duō biàn yǒu de què shì dì yī cì tīng shuō","wǒ de nǚ ér yě jiā rù le jìn lái tā bǎ xué xiào lǐ de yǒu qù de shì jiǎng gěi nǎi nai tīng nǎi nai jiù jiào tā jiǎn zhǐ bāo jiǎo zi yǒu yī cì nǚ ér shuō nǎi nai nín jiǎng de gù shì bǐ yīn xiāng lǐ de hǎo tīng duō le mǔ qīn gāo xìng de xiào gè bù tíng","jǐ gè yuè hòu wǒ zài zhěng lǐ guì zi de shí hou yòu kàn dào le nà tái huài diào de yīn xiāng wǒ ná qù xiū le xiū yuán lái zhǐ shì lǐ miàn yí gè xiǎo líng jiàn sōng le wǒ bǎ tā fàng huí diàn shì guì shàng mǔ qīn kàn le yī yǎn shuō xiū hǎo le nà jiù fàng zhe ba zǎo shang ràng tā bào bào tiān qì","xiàn zài nà tái yīn xiāng měi tiān zhǐ gōng zuò yī cì jiù shì zǎo shang gào su mǔ qīn jīn tiān de tiān qì qí tā shí jiān tā ān ān jìng jìng dì dài zài nà lǐ hǎo xiàng yě zài tīng wǒ men yī jiā rén liáo tiān wǒ cháng cháng xiǎng kē jì kě yǐ gěi wǒ men dài lái hěn duō fāng biàn què dài tì bù liǎo jiā rén zhī jiān de yī jù wèn hòu zhēn zhèng néng ràng lǎo rén bù gū dān de bú shì yī tái cōng ming de jī qì ér shì yuàn yì zuò xià lái tīng tā shuō huà de wǒ men"],"translations":["Tết năm ngoái, con trai mua cho nhà một chiếc loa thông minh. Thứ này không to, tròn tròn, đặt trên tủ ti vi ở phòng khách, trông như một chiếc đèn nho nhỏ. Con trai dạy mọi người cách dùng: chỉ cần gọi tên nó một tiếng rồi nói yêu cầu, nó sẽ mở nhạc, kể chuyện cười, báo thời tiết, thậm chí còn đặt báo thức giúp bạn.","Vợ chồng tôi bận công việc, thấy lạ được mấy hôm rồi bỏ quên nó một bên. Ngược lại, mẹ tôi lại rất hứng thú với món đồ nhỏ này. Năm nay mẹ bảy mươi ba tuổi; ba năm trước bố tôi mất, bà từ quê chuyển lên sống cùng chúng tôi. Ban ngày chúng tôi đi làm, con đi học, trong nhà thường chỉ còn mình bà.","Lúc đầu, mẹ không biết dùng lắm, lúc nào cũng gọi sai tên nó. Loa không hiểu thì trả lời: \"Xin lỗi, tôi nghe không rõ.\" Mẹ cũng không giận, lặp đi lặp lại hết lần này đến lần khác, như đang dạy một đứa trẻ mới tập nói. Về sau, bà dần tìm ra cách, còn đặt cho nó một cái tên là \"Tiểu Viên\". Sáng nào vừa thức dậy, việc đầu tiên của bà là hỏi nó: \"Tiểu Viên, hôm nay thời tiết thế nào?\"","Dần dần, tôi phát hiện mẹ nói chuyện với nó ngày càng nhiều. Có hôm tôi tan làm sớm, vừa tới cửa đã nghe mẹ nói trong phòng khách: \"Tiểu Viên này, con bảo hôm nay gói sủi cảo hay nấu mì thì hơn?\" Loa trả lời: \"Tôi đã tìm cho bạn một cách làm sủi cảo...\" Mẹ cười: \"Ai bảo con tìm cách làm? Mẹ gói sủi cảo mấy chục năm rồi, còn cần con dạy à?\"","Tôi đứng ngoài cửa rất lâu mà không vào. Tôi chợt nhận ra, thứ mẹ cần không phải dự báo thời tiết hay cách nấu ăn, mà là một người có thể trò chuyện với bà. Thế nhưng mấy năm nay, ngày nào về nhà tôi cũng ăn xong là ngồi trước máy tính làm thêm, hoặc nằm trên sofa xem điện thoại. Có lúc mẹ muốn nói với tôi vài câu, tôi toàn \"ừ ừ à à\" đáp qua loa rồi thôi.","Tối hôm đó, tôi hỏi vợ có biết chuyện này không. Vợ nói cô đã phát hiện từ lâu: \"Mỗi ngày mẹ nói chuyện với nó còn nhiều hơn với cả hai vợ chồng mình cộng lại. Lần trước mẹ còn hỏi nó: 'Con ở một mình có buồn không?'\" Nói đến đây, mắt vợ tôi hơi đỏ lên.","Mấy tuần sau, chiếc loa đột nhiên hỏng, gọi thế nào cũng không phản ứng. Mẹ cuống lên, cầm nó lật qua lật lại xem, còn hỏi tôi có phải do bà nói nhiều quá nên làm nó \"mệt quá hỏng rồi\" không. Tôi vốn định lên mạng mua ngay một cái khác, nhưng nghĩ một lúc lại quyết định tạm chưa mua.","Từ hôm đó, vợ chồng tôi bàn nhau, mỗi tối sau bữa cơm dành ra nửa tiếng, không làm gì cả, chỉ ngồi trò chuyện với mẹ. Lúc đầu mọi người đều hơi không quen, chẳng biết nên nói gì. Mẹ chủ yếu kể chuyện ở quê: con nhà ai lấy vợ lấy chồng rồi, hàng xóm cũ chuyển đi đâu, hồi trẻ bà và bố quen nhau thế nào. Những câu chuyện ấy, có chuyện tôi đã nghe rất nhiều lần, có chuyện lại là lần đầu được nghe.","Con gái tôi cũng tham gia. Con bé kể cho bà nghe những chuyện thú vị ở trường, bà thì dạy cháu cắt giấy, gói sủi cảo. Có lần con gái nói: \"Bà ơi, chuyện bà kể hay hơn trong loa nhiều!\" Mẹ tôi vui đến cười mãi không thôi.","Mấy tháng sau, khi dọn tủ, tôi lại thấy chiếc loa hỏng ấy. Tôi đem đi sửa, hóa ra chỉ là một linh kiện nhỏ bên trong bị lỏng. Tôi đặt nó lại lên tủ ti vi, mẹ nhìn một cái rồi nói: \"Sửa xong rồi à? Thế thì cứ để đấy, buổi sáng cho nó báo thời tiết.\"","Bây giờ, chiếc loa mỗi ngày chỉ làm việc một lần, ấy là buổi sáng báo cho mẹ thời tiết hôm nay. Thời gian còn lại, nó nằm yên lặng ở đó, như thể cũng đang nghe cả nhà tôi trò chuyện. Tôi thường nghĩ, công nghệ có thể mang lại cho ta nhiều tiện lợi, nhưng không thay được một lời hỏi han giữa người thân. Thứ thật sự giúp người già không cô đơn không phải là một cỗ máy thông minh, mà là chúng ta — những người sẵn lòng ngồi xuống nghe họ nói."],"questions":[{"q":"为什么母亲对音箱特别感兴趣？","q_vi":"Vì sao mẹ đặc biệt hứng thú với chiếc loa?","options":["她喜欢听音乐","她白天常常一个人在家，很孤单","她想学习新技术","儿子要求她每天用"],"answer":1,"explain_vi":"Đoạn 2: bố mất, ban ngày cả nhà đi vắng, mẹ thường ở một mình — bà cô đơn nên coi chiếc loa như người để trò chuyện."},{"q":"“我”在门外站了很久，没有进去，是因为什么？","q_vi":"\"Tôi\" đứng ngoài cửa rất lâu mà không vào là vì sao?","options":["忘了带钥匙","不想打扰母亲做饭","忽然明白了母亲需要有人陪她说话","担心音箱坏了"],"answer":2,"explain_vi":"Đoạn 5: anh chợt nhận ra thứ mẹ cần là một người để nói chuyện."},{"q":"音箱坏了以后，“我”为什么没有马上再买一台？","q_vi":"Sau khi loa hỏng, vì sao \"tôi\" không mua ngay cái khác?","options":["想让家人代替音箱多陪母亲聊天","觉得音箱太贵了","母亲不让他买","网上没有卖的"],"answer":0,"explain_vi":"Đoạn 8: từ đó vợ chồng anh dành nửa tiếng mỗi tối trò chuyện với mẹ — tức muốn người nhà thay chiếc loa."},{"q":"关于这个家庭后来的变化，下面哪一项正确？","q_vi":"Về sự thay đổi sau này của gia đình, điều nào đúng?","options":["母亲搬回了老家","他们又买了一台新音箱","女儿不喜欢听奶奶讲故事","一家人每天晚饭后都会陪母亲聊天"],"answer":3,"explain_vi":"Đoạn 8–9: mỗi tối cả nhà dành nửa tiếng trò chuyện với mẹ, con gái cũng tham gia."},{"q":"这篇文章主要想说明什么？","q_vi":"Bài viết chủ yếu muốn nói điều gì?","options":["智能音箱很容易坏","老人学不会使用新科技","科技代替不了家人的陪伴","做饭是一件很有意思的事"],"answer":2,"explain_vi":"Đoạn cuối: công nghệ không thay được lời hỏi han của người thân; điều giúp người già không cô đơn là con cháu chịu ngồi nghe họ nói."}],"beyond":[["盏","zhǎn","TRẢN","ngọn (đèn), chén (trà, rượu) (lượng từ)"],["再说","zàishuō","TÁI THUYẾT","nói sau; hơn nữa; vả lại"],["学说","xuéshuō","HỌC THUYẾT","Học thuyết"],["有时","yǒushí","HỮU THỜI","có lúc"],["不知","bùzhī","BẤT TRI","không biết, chẳng hay"],["闷","mēn","MUỘN","bí bách ngột ngạt; đậy kín ủ hơi · buồn bực bực bội, u uất chán nản"],["多半","duōbàn","ĐA BÁN","đa phần, phần lớn; có lẽ"],["却是","què shì","KHƯỚC THỊ","nhưng lại là, thực ra lại"],["一眼","yīyǎn","NHẤT NHÃN","một cái liếc mắt, một ánh nhìn, một mắt nhìn"],["一家人","yījiārén","NHẤT GIA NHÂN","người một nhà, cả gia đình"],["孤单","gūdān","CÔ ĐƠN","cô đơn; cô độc; lẻ loi"]]},{"id":"h6-01","level":6,"title":"被比较的人生","title_vi":"Cuộc đời bị đem ra so sánh","topic":"nghị luận xã hội","chars":1259,"paragraphs":["“别人家的孩子”，大概是很多中国人童年记忆里最熟悉、也最让人头疼的一个人物。他的成绩永远比你好，钢琴永远比你弹得熟练，见到长辈永远比你懂礼貌。你从来没有见过他，却在父母的叹气声中，跟他比了整整十几年。","长大以后，我们以为终于可以摆脱这个看不见的对手了，却发现比较不但没有消失，反而换了一种更隐蔽、更无处不在的形式。打开手机，朋友圈里有人晒出了刚买的新车，有人在海边度假，有人升职加薪，有人的孩子拿了钢琴比赛一等奖。短短几分钟的浏览，足以让一个原本心情不错的人陷入说不清的焦虑：为什么别人都过得那么精彩，只有我还在原地踏步？","心理学上有一个概念叫“社会比较”，意思是人们往往通过与他人比较来评价自己。这本是人类的一种本能。在远古时代，了解自己在群体中的位置，对生存至关重要。适度的比较可以让我们看清差距，产生前进的动力。问题在于，社交媒体把这种本能放大到了前所未有的程度。","首先，我们比较的对象变了。过去，一个人主要和身边的同学、同事、邻居比较，范围有限，彼此的生活也大致相当。如今，我们每天面对的，是来自全国甚至全世界的“优秀样本”，其中不乏极少数的幸运儿。拿自己的普通生活去和这些人比较，结果可想而知。","其次，我们看到的并不是真实的全貌。人们在网上展示的，往往是经过精心挑选、反复修改的片段：照片里的风景是拍了几十张才选出的一张；看似轻松的度假背后，可能是刷爆的信用卡和堆积如山的工作。用自己生活的“幕后”去比别人生活的“台前”，这本身就是一场不公平的比赛。","我有一位大学同学，毕业后在一家互联网公司工作。在朋友圈里，她的生活令人羡慕：出差、健身、看展览、和朋友聚餐，每一张照片都光彩照人。直到有一次聚会，她喝了几杯酒，才说出真相：那两年她几乎每天加班到深夜，焦虑得整夜失眠，发朋友圈“只是想证明自己过得还不错”。说完，她自嘲地笑了笑：“说不定我也是别人眼里那个‘别人家的孩子’吧。”","这句话让我想了很久。在这个人人都在展示、人人都在观看的时代，我们每个人既是比较的受害者，又在不知不觉中成了别人焦虑的来源。我们一边为别人的精彩感到失落，一边又忍不住把自己最好的一面展示出来，好像只有这样，才能证明自己并没有落后。","那么，我们应该如何面对比较呢？完全不比较，恐怕既不现实，也没有必要。关键在于和谁比、比什么。","一个值得尝试的办法是“纵向比较”，也就是和过去的自己比。今天的我是不是比一年前多读了几本书，多掌握了一项技能？身体是不是更健康，心态是不是更平和？这样的比较不受他人影响，标准掌握在自己手中，带来的往往是踏实的成就感，而不是无尽的失落。","另一个办法，是有意识地减少被动接受信息的时间。有人尝试每天只在固定的时间看一次社交软件，有人干脆把一些让自己不舒服的账号设为“不看”。这并不是逃避，而是给自己留出一片安静的空间，把注意力放回到真正重要的事情上。一段时间以后，他们发现自己并没有因此错过什么重要的消息，心情反而轻松了许多。","最后，也许是最根本的一点：学会接受人生的不同节奏。有人二十二岁就找到了理想的工作，有人三十岁才开始真正明白自己想要什么；有人早早成家，有人选择独自生活。就像不同的植物开花的季节不一样，没有人规定每个人都必须在同一时间到达同一个地方。","那个“别人家的孩子”，其实从来就不存在。他只是我们把无数人的优点拼在一起而创造出来的一个完美的影子。与其追赶一个影子，不如认真地过好属于自己的、不完美却真实的每一天。"],"pinyin":["bié rén jiā de hái zi dà gài shì hěn duō zhōng guó rén tóng nián jì yì lǐ zuì shú xī yě zuì ràng rén tóu téng de yí gè rén wù tā de chéng jì yǒng yuǎn bǐ nǐ hǎo gāng qín yǒng yuǎn bǐ nǐ dàn dé shú liàn jiàn dào zhǎng bèi yǒng yuǎn bǐ nǐ dǒng lǐ mào nǐ cóng lái méi yǒu jiàn guò tā què zài fù mǔ de tàn qì shēng zhōng gēn tā bǐ le zhěng zhěng shí jǐ nián","zhǎng dà yǐ hòu wǒ men yǐ wéi zhōng yú kě yǐ bǎi tuō zhè ge kàn bú jiàn de duì shǒu le què fā xiàn bǐ jiào bù dàn méi yǒu xiāo shī fǎn ér huàn le yī zhǒng gèng yǐn bì gèng wú chǔ bù zài de xíng shì dǎ kāi shǒu jī péng you quān lǐ yǒu rén shài chū le gāng mǎi de xīn chē yǒu rén zài hǎi biān dù jià yǒu rén shēng zhí jiā xīn yǒu rén de hái zi ná le gāng qín bǐ sài yì děng jiǎng duǎn duǎn jǐ fēn zhōng de liú lǎn zú yǐ ràng yí gè yuán běn xīn qíng bù cuò de rén xiàn rù shuō bù qīng de jiāo lǜ wèi shén me bié rén dōu guò de nà me jīng cǎi zhǐ yǒu wǒ hái zài yuán dì tà bù","xīn lǐ xué shàng yǒu yí gè gài niàn jiào shè huì bǐ jiào yì si shì rén men wǎng wǎng tōng guò yǔ tā rén bǐ jiào lái píng jià zì jǐ zhè běn shì rén lèi de yī zhǒng běn néng zài yuǎn gǔ shí dài liǎo jiě zì jǐ zài qún tǐ zhōng de wèi zhì duì shēng cún zhì guān zhòng yào shì dù de bǐ jiào kě yǐ ràng wǒ men kàn qīng chā jù chǎn shēng qián jìn de dòng lì wèn tí zài yú shè jiāo méi tǐ bǎ zhè zhǒng běn néng fàng dà dào le qián suǒ wèi yǒu de chéng dù","shǒu xiān wǒ men bǐ jiào de duì xiàng biàn le guò qù yí gè rén zhǔ yào hé shēn biān de tóng xué tóng shì lín jū bǐ jiào fàn wéi yǒu xiàn bǐ cǐ de shēng huó yě dà zhì xiāng dāng rú jīn wǒ men měi tiān miàn duì de shì lái zì quán guó shèn zhì quán shì jiè de yōu xiù yàng běn qí zhōng bù fá jí shǎo shù de xìng yùn ér ná zì jǐ de pǔ tōng shēng huó qù hé zhè xiē rén bǐ jiào jié guǒ kě xiǎng ér zhī","qí cì wǒ men kàn dào de bìng bú shì zhēn shí de quán mào rén men zài wǎng shàng zhǎn shì de wǎng wǎng shì jīng guò jīng xīn tiāo xuǎn fǎn fù xiū gǎi de piàn duàn zhào piān lǐ de fēng jǐng shì pāi le jǐ shí zhāng cái xuǎn chū de yī zhāng kàn shì qīng sōng de dù jià bèi hòu kě néng shì shuā bào de xìn yòng kǎ hé duī jī rú shān de gōng zuò yòng zì jǐ shēng huó de mù hòu qù bǐ bié rén shēng huó de tái qián zhè běn shēn jiù shì yī cháng bù gōng píng de bǐ sài","wǒ yǒu yī wèi dà xué tóng xué bì yè hòu zài yī jiā hù lián wǎng gōng sī gōng zuò zài péng you quān lǐ tā de shēng huó lìng rén xiàn mù chū chāi jiàn shēn kàn zhǎn lǎn hé péng you jù cān měi yī zhāng zhào piān dōu guāng cǎi zhào rén zhí dào yǒu yī cì jù huì tā hē le jǐ bēi jiǔ cái shuō chū zhēn xiàng nà liǎng nián tā jī hū měi tiān jiā bān dào shēn yè jiāo lǜ de zhěng yè shī mián fā péng you quān zhǐ shì xiǎng zhèng míng zì jǐ guò dé hái bù cuò shuō wán tā zì cháo de xiào le xiào shuō bù dìng wǒ yě shì bié rén yǎn lǐ nà ge bié rén jiā de hái zi ba","zhè jù huà ràng wǒ xiǎng le hěn jiǔ zài zhè ge rén rén dōu zài zhǎn shì rén rén dōu zài guān kàn de shí dài wǒ men měi gè rén jì shì bǐ jiào de shòu hài zhě yòu zài bù zhī bù jué zhōng chéng le bié rén jiāo lǜ de lái yuán wǒ men yī biān wèi bié rén de jīng cǎi gǎn dào shī luò yī biān yòu rěn bú zhù bǎ zì jǐ zuì hǎo de yí miàn zhǎn shì chū lái hǎo xiàng zhǐ yǒu zhè yàng cái néng zhèng míng zì jǐ bìng méi yǒu luò hòu","nà me wǒ men yīng gāi rú hé miàn duì bǐ jiào ne wán quán bù bǐ jiào kǒng pà jì bù xiàn shí yě méi yǒu bì yào guān jiàn zài yú hé shuí bǐ bǐ shén me","yí gè zhí de cháng shì de bàn fǎ shì zòng xiàng bǐ jiào yě jiù shì hé guò qù de zì jǐ bǐ jīn tiān de wǒ shì bú shì bǐ yī nián qián duō dú le jǐ běn shū duō zhǎng wò le yī xiàng jì néng shēn tǐ shì bú shì gèng jiàn kāng xīn tài shì bú shì gèng píng hé zhè yàng de bǐ jiào bù shòu tā rén yǐng xiǎng biāo zhǔn zhǎng wò zài zì jǐ shǒu zhōng dài lái de wǎng wǎng shì tà shí de chéng jiù gǎn ér bú shì wú jìn de shī luò","lìng yí gè bàn fǎ shì yǒu yì shí de jiǎn shǎo bèi dòng jiē shòu xìn xī de shí jiān yǒu rén cháng shì měi tiān zhǐ zài gù dìng de shí jiān kàn yī cì shè jiāo ruǎn jiàn yǒu rén gān cuì bǎ yī xiē ràng zì jǐ bù shū fu de zhàng hào shè wèi bù kàn zhè bìng bú shì táo bì ér shì gěi zì jǐ liú chū yī piàn ān jìng de kōng jiān bǎ zhù yì lì fàng huí dào zhēn zhèng zhòng yào de shì qing shàng yī duàn shí jiān yǐ hòu tā men fā xiàn zì jǐ bìng méi yǒu yīn cǐ cuò guò shén me zhòng yào de xiāo xi xīn qíng fǎn ér qīng sōng le xǔ duō","zuì hòu yě xǔ shì zuì gēn běn de yì diǎn xué huì jiē shòu rén shēng de bù tóng jié zòu yǒu rén èr shí èr suì jiù zhǎo dào le lǐ xiǎng de gōng zuò yǒu rén sān shí suì cái kāi shǐ zhēn zhèng míng bai zì jǐ xiǎng yào shén me yǒu rén zǎo zǎo chéng jiā yǒu rén xuǎn zé dú zì shēng huó jiù xiàng bù tóng de zhí wù kāi huā de jì jié bù yī yàng méi yǒu rén guī dìng měi gè rén dōu bì xū zài tóng yī shí jiān dào dá tóng yī gè dì fang","nà ge bié rén jiā de hái zi qí shí cóng lái jiù bù cún zài tā zhǐ shì wǒ men bǎ wú shù rén de yōu diǎn pīn zài yì qǐ ér chuàng zào chū lái de yí gè wán měi de yǐng zi yǔ qí zhuī gǎn yí gè yǐng zi bù rú rèn zhēn dì guò hǎo shǔ yú zì jǐ de bù wán měi què zhēn shí de měi yī tiān"],"translations":["\"Con nhà người ta\" có lẽ là nhân vật quen thuộc nhất mà cũng đau đầu nhất trong ký ức tuổi thơ của nhiều người Trung Quốc. Thành tích của nó lúc nào cũng hơn bạn, đàn piano lúc nào cũng chơi thành thạo hơn bạn, gặp người lớn lúc nào cũng lễ phép hơn bạn. Bạn chưa từng gặp nó, vậy mà trong những tiếng thở dài của bố mẹ, bạn đã so bì với nó suốt hơn chục năm trời.","Lớn lên, ta tưởng cuối cùng đã thoát được đối thủ vô hình ấy, nào ngờ sự so sánh chẳng những không biến mất mà còn đổi sang một hình thức kín đáo hơn, có mặt ở khắp nơi hơn. Mở điện thoại ra, trên vòng bạn bè có người khoe chiếc xe mới mua, có người đi nghỉ ở biển, có người được thăng chức tăng lương, có người có con đoạt giải nhất cuộc thi piano. Chỉ vài phút lướt xem cũng đủ khiến một người vốn đang vui vẻ rơi vào nỗi lo âu khó gọi tên: sao ai cũng sống rực rỡ như vậy, chỉ có mình vẫn giậm chân tại chỗ?","Tâm lý học có một khái niệm gọi là \"so sánh xã hội\", nghĩa là con người thường đánh giá bản thân thông qua việc so sánh với người khác. Đây vốn là một bản năng của loài người. Thời xa xưa, biết được vị trí của mình trong bầy đàn là điều cực kỳ quan trọng đối với sự sinh tồn. So sánh vừa phải giúp ta nhìn rõ khoảng cách, sinh ra động lực tiến lên. Vấn đề là mạng xã hội đã phóng đại bản năng này đến mức chưa từng có.","Trước hết, đối tượng ta so sánh đã thay đổi. Trước đây, một người chủ yếu so với bạn học, đồng nghiệp, hàng xóm quanh mình; phạm vi có hạn, cuộc sống của mọi người cũng na ná nhau. Ngày nay, thứ ta đối diện mỗi ngày là những \"hình mẫu xuất sắc\" đến từ khắp cả nước, thậm chí khắp thế giới, trong đó không thiếu số ít những người cực kỳ may mắn. Đem cuộc sống bình thường của mình so với những người này, kết quả thế nào có thể đoán được.","Thứ hai, thứ ta nhìn thấy không phải toàn cảnh chân thực. Những gì người ta phô ra trên mạng thường là những mảnh ghép đã được chọn lọc kỹ lưỡng, sửa đi sửa lại: phong cảnh trong ảnh là tấm được chọn ra sau khi chụp mấy chục tấm; đằng sau kỳ nghỉ trông có vẻ thảnh thơi có thể là tấm thẻ tín dụng bị quẹt cháy hạn mức và núi công việc chất đống. Lấy \"hậu trường\" đời mình so với \"sân khấu\" đời người khác, bản thân việc đó đã là một cuộc thi không công bằng.","Tôi có một bạn đại học, tốt nghiệp xong làm ở một công ty Internet. Trên vòng bạn bè, cuộc sống của cô ấy khiến người ta ghen tị: đi công tác, tập gym, xem triển lãm, ăn uống với bạn bè, tấm ảnh nào cũng rạng rỡ. Mãi đến một lần họp lớp, cô uống vài ly rượu mới nói ra sự thật: hai năm đó gần như ngày nào cô cũng tăng ca đến khuya, lo âu đến mất ngủ cả đêm, đăng bài lên vòng bạn bè \"chỉ là muốn chứng minh mình sống cũng không tệ\". Nói xong, cô cười tự giễu: \"Biết đâu mình cũng là 'con nhà người ta' trong mắt ai đó.\"","Câu nói ấy khiến tôi nghĩ rất lâu. Trong thời đại ai cũng phô bày, ai cũng ngắm nhìn này, mỗi chúng ta vừa là nạn nhân của sự so sánh, lại vừa vô tình trở thành nguồn cơn lo âu của người khác. Ta vừa thấy hụt hẫng trước sự rực rỡ của người khác, vừa không nhịn được mà phô ra mặt tốt nhất của mình, như thể chỉ có vậy mới chứng minh được mình không bị tụt lại.","Vậy chúng ta nên đối mặt với sự so sánh thế nào? Hoàn toàn không so sánh, e rằng vừa không thực tế, vừa không cần thiết. Mấu chốt nằm ở chỗ so với ai và so cái gì.","Một cách đáng thử là \"so sánh theo chiều dọc\", tức là so với chính mình trước đây. Tôi hôm nay có đọc nhiều hơn một năm trước vài cuốn sách, nắm thêm một kỹ năng không? Sức khỏe có tốt hơn, tâm trạng có bình thản hơn không? Kiểu so sánh này không bị người khác chi phối, tiêu chuẩn nằm trong tay mình, thứ nó đem lại thường là cảm giác thành tựu vững vàng chứ không phải nỗi hụt hẫng không dứt.","Một cách khác là chủ động giảm thời gian tiếp nhận thông tin một cách thụ động. Có người thử mỗi ngày chỉ xem mạng xã hội một lần vào giờ cố định, có người dứt khoát đặt chế độ \"không xem\" cho những tài khoản khiến mình khó chịu. Đó không phải trốn tránh, mà là chừa cho mình một khoảng không gian yên tĩnh, đưa sự chú ý trở lại những việc thật sự quan trọng. Sau một thời gian, họ nhận ra mình chẳng hề vì thế mà bỏ lỡ tin tức quan trọng nào, tâm trạng ngược lại còn nhẹ nhõm hơn nhiều.","Cuối cùng, có lẽ cũng là điều căn bản nhất: học cách chấp nhận những nhịp điệu khác nhau của đời người. Có người hai mươi hai tuổi đã tìm được công việc lý tưởng, có người ba mươi tuổi mới thật sự hiểu mình muốn gì; có người lập gia đình sớm, có người chọn sống một mình. Giống như mỗi loài cây nở hoa vào một mùa khác nhau, chẳng ai quy định mọi người đều phải đến cùng một nơi vào cùng một thời điểm.","Cái \"con nhà người ta\" ấy thật ra chưa bao giờ tồn tại. Nó chỉ là một cái bóng hoàn hảo do ta ghép ưu điểm của vô số người lại mà tạo ra. Thay vì đuổi theo một cái bóng, chi bằng sống thật tốt từng ngày thuộc về chính mình — không hoàn hảo nhưng chân thật."],"questions":[{"q":"第一段中的“别人家的孩子”指的是什么？","q_vi":"\"Con nhà người ta\" ở đoạn 1 chỉ điều gì?","options":["邻居家真实存在的一个孩子","父母拿来和自己比较的、各方面都优秀的孩子","自己最好的朋友","电视里的一个人物"],"answer":1,"explain_vi":"Đó là hình mẫu đứa trẻ giỏi mọi mặt mà bố mẹ hay đem ra so sánh; bạn \"chưa từng gặp nó\" và đoạn cuối nói nó \"chưa bao giờ tồn tại\"."},{"q":"根据文章，社交媒体上的比较为什么特别容易让人焦虑？","q_vi":"Theo bài, vì sao so sánh trên mạng xã hội đặc biệt dễ gây lo âu?","options":["因为网上的人都不说真话","因为人们上网的时间太短","因为比较的对象范围太大，而且看到的往往只是别人最好的一面","因为社交媒体让人失去了比较的本能"],"answer":2,"explain_vi":"Đoạn 4–5: đối tượng so sánh là \"hình mẫu xuất sắc\" khắp thế giới, và thứ ta thấy chỉ là \"sân khấu\" được chọn lọc của người khác."},{"q":"作者讲大学同学的故事，主要是为了说明什么？","q_vi":"Tác giả kể chuyện người bạn đại học chủ yếu để nói lên điều gì?","options":["网上光鲜的生活背后可能有不为人知的压力","互联网公司的工作非常辛苦","喝酒以后人才会说真话","朋友圈里的照片都是假的"],"answer":0,"explain_vi":"Cuộc sống trên mạng của cô ấy đáng ngưỡng mộ nhưng thực tế tăng ca, lo âu, mất ngủ — minh họa cho ý \"sân khấu\" và \"hậu trường\"."},{"q":"“纵向比较”是什么意思？","q_vi":"\"So sánh theo chiều dọc\" có nghĩa là gì?","options":["和比自己优秀的人比","和身边的朋友比","和不如自己的人比","和过去的自己比"],"answer":3,"explain_vi":"Đoạn 9 giải thích rõ: 纵向比较 là so với chính mình trước đây."},{"q":"作者对“比较”的总体态度是什么？","q_vi":"Thái độ tổng thể của tác giả đối với \"so sánh\" là gì?","options":["比较对人只有坏处，应该完全避免","比较可以有，但要选择合适的对象和标准，并接受自己的节奏","人应该多和优秀的人比较","比较是父母的错"],"answer":1,"explain_vi":"Đoạn 8: không so sánh hoàn toàn là không thực tế; mấu chốt là so với ai, so cái gì; các đoạn sau khuyên so với chính mình và chấp nhận nhịp riêng."}],"beyond":[["度假","dù jià","ĐỘ GIẢ","đi nghỉ, đến một địa điểm để nghỉ ngơi và thư giãn đầu óc · nghỉ mát, đi nghỉ dưỡng"],["原本","yuánběn","NGUYÊN BẢN","vốn dĩ, nguyên bản · vốn dĩ"],["焦虑","jiāolǜ","TIÊU LỰ","lo âu, sốt ruột · lo âu; lo lắng; bồn chồn; bất an"],["原地","yuándì","NGUYÊN ĐỊA","chỗ cũ, vị trí ban đầu"],["他人","tārén","THA NHÂN","người khác · người khác, kẻ khác"],["远古","yuǎngǔ","VIỄN CỔ","thời viễn cổ, thời xa xưa (thời cổ đại xa xôi)"],["至关重要","zhìguān-zhòngyào","CHÍ QUAN TRỌNG YẾU","cực kỳ quan trọng, tối quan trọng, có ý nghĩa then chốt"],["适度","shìdù","THÍCH ĐỘ","vừa phải, có chừng mực, thích độ"],["社交","shèjiāo","XÃ GIAO","xã giao (chỉ các hoạt động giao lưu, qua lại trong xã hội) · giao tiếp xã hội, quan hệ xã giao"],["前所未有","qiánsuǒwèiyǒu","TIỀN SỞ VỊ HỮU","chưa từng có, tiền sở vị hữu"],["样本","yàngběn","DẠNG BẢN","mẫu thử, vật mẫu, mẫu vật"],["极少数","jí shǎoshù","CỰC THIỂU SỐ","thiểu số cực nhỏ, rất ít"],["可想而知","kěxiǎng'érzhī","KHẢ TƯỞNG NHI TRI","có thể tưởng tượng được, đủ hiểu"],["看似","kànsì","KHÁN TỰ","nhìn bề ngoài có vẻ, dường như"],["幕后","mùhòu","MẠC HẬU","hậu trường, sau cánh gà, đứng sau"],["深夜","shēnyè","THÂM DẠ","đêm khuya"],["自嘲","zìcháo","TỰ TRÀO","tự giễu, tự trào"],["受害","shòuhài","THỤ HẠI","bị hại, chịu thiệt hại"],["不知不觉","bù zhī bù jué","BẤT TRI BẤT GIÁC","một cách vô tri vô giác, không hề hay biết (thường dùng làm trạng ngữ; hoàn toàn không có… · bất giác, từ lúc nào không hay, vô tri vô giác"],["失落","shīluò","THẤT LẠC","đánh rơi, mất mát; hụt hẫng, trống vắng"],["一面","yīmiàn","NHẤT DIỆN","một mặt; vừa... vừa...; một lần gặp"],["平和","pínghé","BÌNH HÒA","ôn hòa, điềm đạm, êm dịu"],["有意识","yǒuyìshí","HỮU Ý THỨC","có chủ ý, có ý thức"],["账号","zhànghào","TRƯỚNG HIỆU","tài khoản (ngân hàng, mạng xã hội)"],["成家","chéng jiā","THÀNH GIA","lập gia đình, thành gia lập thất (Chỉ nam giới kết hôn, yên bề gia thất) · lập gia đình, yên bề gia thất"],["追赶","zhuīgǎn","TRUY CẢN","đuổi theo, rượt đuổi, theo kịp"]]},{"id":"h6-02","level":6,"title":"表壳里的秘密","title_vi":"Bí mật trong vỏ đồng hồ","topic":"truyện ngắn","chars":1210,"paragraphs":["老街拐角处有一家修表铺，门面窄得只能容下一张桌子和一把椅子。老陈在这里修了四十年的表。这些年，街两边的店换了一茬又一茬，卖布的变成了卖手机的，卖手机的又变成了奶茶店，只有他的小铺子一直没变。如今戴手表的人越来越少，生意自然冷清，可他每天早上八点依然准时开门，戴上放大镜，把桌上的零件擦得一尘不染。","那是一个初秋的下午，一位三十岁左右的女人推门进来。她穿着一件灰色的大衣，脸色有些疲惫，从包里小心翼翼地拿出一块旧手表，放在桌上。","“师傅，这块表停了好几年了，您看还能修吗？”","老陈拿起表，翻过来看了看。那是一块很普通的老式男表，表带已经换过，表面上有几道细细的划痕，指针停在九点二十分。他觉得这块表有些眼熟，却一时想不起在哪儿见过。","“这是我父亲的。”女人轻声说，“上个月他去世了。整理遗物的时候，我在他枕头底下发现了它。他戴了三十多年，后来坏了也舍不得扔。”她停顿了一下，又补充道：“我小时候，常听他说城里有个修表的老师傅手艺最好，我想应该就是您吧。”","老陈点点头，没有多问。他用工具轻轻打开表的后盖，正准备检查里面的机芯，动作却忽然停住了。在后盖的内侧，贴着一张折得极小的纸条，纸已经发黄，边角有些卷起。","就在那一刻，一段被遗忘多年的记忆猛地浮现在他眼前。","大约八年前，一个头发半白的男人来铺子里修这块表。修好以后，男人迟迟不肯走，犹豫了半天，才红着脸从口袋里掏出一张叠好的纸条，问老陈能不能把它藏进表里。“我女儿去外地很多年了，我们……吵过一架，后来就很少说话。我这个人嘴笨，有些话当面说不出口。”男人低着头说，“要是哪天她拿着这块表来找你，就说明我已经不在了。到那时候，麻烦你把这张纸条交给她。”","老陈当时答应了，还开玩笑说：“您身体这么硬朗，这表得等个二三十年呢。”男人笑了笑，没说什么。此后，他再也没有来过。时间一长，老陈竟把这件事忘得干干净净。","老陈小心地取下纸条，递给女人：“这是你父亲留给你的。八年前，他托我放进去的。”","女人愣了一下，手指微微发抖地展开纸条。上面的字歪歪扭扭，看得出写字的人并不常拿笔：","“雨儿：这块表是你出生那年我买的。那天你哭得特别响，护士说，这孩子嗓门真大，将来一定有出息。那年你非要去北京学画画，我说了很多难听的话，说你不务正业，说你以后别回来。其实你走的那天，我在车站外面站了很久，一直到火车开远了才回家。你寄回来的每一张明信片，每一幅画的照片，我都收着，放在柜子最上面的盒子里。爸爸这辈子不会说好听的，只想告诉你：你做得很好，爸爸以你为骄傲。”","女人读完，捂着嘴，眼泪一颗一颗地落在玻璃柜台上。老陈默默地转过身去，假装在架子上找零件，给她留出一点空间。铺子里很安静，只听得见墙上几十只挂钟“滴答滴答”地走着。","过了很久，女人才平静下来。她说，父亲去世前一直在医院里，她赶回去的时候，父亲已经说不出话了，只是紧紧拉着她的手。她一直以为，父亲到最后也没有原谅她。","老陈没有接话，低下头专心地修表。其实毛病并不大，只是几个零件老化了。半个小时后，他把表递了回去。秒针重新开始转动，发出轻微而清晰的声音。","女人要付钱，老陈摆了摆手：“这钱，你父亲八年前就付过了。”","女人走后，老陈站在门口，看着她的背影消失在街角。他想，自己修了一辈子的表，修的是时间，可时间从来不会倒流。不过，有些话就像藏在表壳里的纸条，虽然晚了一点，但终究还是在合适的时候，到达了它该去的地方。"],"pinyin":["lǎo jiē guǎi jiǎo chù yǒu yī jiā xiū biǎo pù mén miàn zhǎi dé zhǐ néng róng xià yī zhāng zhuō zi hé yī bǎ yǐ zi lǎo chén zài zhè lǐ xiū le sì shí nián de biǎo zhè xiē nián jiē liǎng biān de diàn huàn le yī chá yòu yī chá mài bù de biàn chéng le mài shǒu jī de mài shǒu jī de yòu biàn chéng le nǎi chá diàn zhǐ yǒu tā de xiǎo pù zi yì zhí méi biàn rú jīn dài shǒu biǎo de rén yuè lái yuè shǎo shēng yì zì rán lěng qīng kě tā měi tiān zǎo shang bā diǎn yī rán zhǔn shí kāi mén dài shàng fàng dà jìng bǎ zhuō shàng de líng jiàn cā de yī chén bù rǎn","nà shì yí gè chū qiū de xià wǔ yī wèi sān shí suì zuǒ yòu de nǚ rén tuī mén jìn lái tā chuān zhe yī jiàn huī sè de dà yī liǎn sè yǒu xiē pí bèi cóng bāo lǐ xiǎo xīn yì yì de ná chū yī kuài jiù shǒu biǎo fàng zài zhuō shàng","shī fù zhè kuài biǎo tíng le hǎo jǐ nián le nín kàn hái néng xiū ma","lǎo chén ná qǐ biǎo fān guò lái kàn le kàn nà shì yī kuài hěn pǔ tōng de lǎo shì nán biǎo biǎo dài yǐ jīng huàn guò biǎo miàn shàng yǒu jǐ dào xì xì de huà hén zhǐ zhēn tíng zài jiǔ diǎn èr shí fēn tā jué de zhè kuài biǎo yǒu xiē yǎn shú què yī shí xiǎng bù qǐ zài nǎ ér jiàn guò","zhè shì wǒ fù qīn de nǚ rén qīng shēng shuō shàng gè yuè tā qù shì le zhěng lǐ yí wù de shí hou wǒ zài tā zhěn tou dǐ xià fā xiàn le tā tā dài le sān shí duō nián hòu lái huài le yě shě bù dé rēng tā tíng dùn le yí xià yòu bǔ chōng dào wǒ xiǎo shí hou cháng tīng tā shuō chéng lǐ yǒu gè xiū biǎo de lǎo shī fù shǒu yì zuì hǎo wǒ xiǎng yīng gāi jiù shì nín ba","lǎo chén diǎn diǎn tóu méi yǒu duō wèn tā yòng gōng jù qīng qīng dǎ kāi biǎo de hòu gài zhèng zhǔn bèi jiǎn chá lǐ miàn de jī xīn dòng zuò què hū rán tíng zhù le zài hòu gài de nèi cè tiē zhe yī zhāng zhé de jí xiǎo de zhǐ tiáo zhǐ yǐ jīng fā huáng biān jiǎo yǒu xiē juǎn qǐ","jiù zài nà yī kè yī duàn bèi yí wàng duō nián de jì yì měng dì fú xiàn zài tā yǎn qián","dà yuē bā nián qián yí gè tóu fa bàn bái de nán rén lái pù zi lǐ xiū zhè kuài biǎo xiū hǎo yǐ hòu nán rén chí chí bù kěn zǒu yóu yù le bàn tiān cái hóng zhe liǎn cóng kǒu dài lǐ tāo chū yī zhāng dié hǎo de zhǐ tiáo wèn lǎo chén néng bù néng bǎ tā cáng jìn biǎo lǐ wǒ nǚ ér qù wài dì hěn duō nián le wǒ men chǎo guò yī jià hòu lái jiù hěn shǎo shuō huà wǒ zhè ge rén zuǐ bèn yǒu xiē huà dāng miàn shuō bù chū kǒu nán rén dī zhe tóu shuō yào shì nǎ tiān tā ná zhe zhè kuài biǎo lái zhǎo nǐ jiù shuō míng wǒ yǐ jīng bù zài le dào nà shí hou má fan nǐ bǎ zhè zhāng zhǐ tiáo jiāo gěi tā","lǎo chén dāng shí dā yìng le hái kāi wán xiào shuō nín shēn tǐ zhè me yìng lǎng zhè biǎo dé děng gè èr sān shí nián ne nán rén xiào le xiào méi shuō shén me cǐ hòu tā zài yě méi yǒu lái guò shí jiān yī zhǎng lǎo chén jìng bǎ zhè jiàn shì wàng dé gān gān jìng jìng","lǎo chén xiǎo xīn dì qǔ xià zhǐ tiáo dì gěi nǚ rén zhè shì nǐ fù qīn liú gěi nǐ de bā nián qián tā tuō wǒ fàng jìn qù de","nǚ rén lèng le yí xià shǒu zhǐ wēi wēi fā dǒu de zhǎn kāi zhǐ tiáo shàng miàn de zì wāi wāi niǔ niǔ kàn dé chū xiě zì de rén bìng bù cháng ná bǐ","yǔ ér zhè kuài biǎo shì nǐ chū shēng nà nián wǒ mǎi de nà tiān nǐ kū de tè bié xiǎng hù shì shuō zhè hái zi sǎng mén zhēn dà jiāng lái yí dìng yǒu chū xī nà nián nǐ fēi yào qù běi jīng xué huà huà wǒ shuō le hěn duō nán tīng de huà shuō nǐ bù wù zhèng yè shuō nǐ yǐ hòu bié huí lái qí shí nǐ zǒu de nà tiān wǒ zài chē zhàn wài miàn zhàn le hěn jiǔ yì zhí dào huǒ chē kāi yuǎn le cái huí jiā nǐ jì huí lái de měi yī zhāng míng xìn piàn měi yī fú huà de zhào piān wǒ dōu shōu zhe fàng zài guì zi zuì shàng miàn de hé zi lǐ bà ba zhè bèi zi bú huì shuō hǎo tīng de zhǐ xiǎng gào su nǐ nǐ zuò de hěn hǎo bà ba yǐ nǐ wèi jiāo ào","nǚ rén dú wán wǔ zhe zuǐ yǎn lèi yī kē yī kē dì luò zài bō lí guì tái shàng lǎo chén mò mò dì zhuǎn guò shēn qù jiǎ zhuāng zài jià zi shàng zhǎo líng jiàn gěi tā liú chū yì diǎn kōng jiān pù zi lǐ hěn ān jìng zhǐ tīng de jiàn qiáng shàng jǐ shí zhǐ guà zhōng dī dā dī dā dì zǒu zhe","guò le hěn jiǔ nǚ rén cái píng jìng xià lái tā shuō fù qīn qù shì qián yì zhí zài yī yuàn lǐ tā gǎn huí qù de shí hou fù qīn yǐ jīng shuō bù chū huà le zhǐ shì jǐn jǐn lā zhe tā de shǒu tā yì zhí yǐ wéi fù qīn dào zuì hòu yě méi yǒu yuán liàng tā","lǎo chén méi yǒu jiē huà dī xià tou zhuān xīn dì xiū biǎo qí shí máo bìng bìng bù dà zhǐ shì jǐ gè líng jiàn lǎo huà le bàn gè xiǎo shí hòu tā bǎ biǎo dì le huí qù miǎo zhēn chóng xīn kāi shǐ zhuǎn dòng fā chū qīng wēi ér qīng xī de shēng yīn","nǚ rén yào fù qián lǎo chén bǎi le bǎi shǒu zhè qián nǐ fù qīn bā nián qián jiù fù guò le","nǚ rén zǒu hòu lǎo chén zhàn zài mén kǒu kàn zhe tā de bèi yǐng xiāo shī zài jiē jiǎo tā xiǎng zì jǐ xiū le yī bèi zi de biǎo xiū de shì shí jiān kě shí jiān cóng lái bù huì dào liú bù guò yǒu xiē huà jiù xiàng cáng zài biǎo ké lǐ de zhǐ tiáo suī rán wǎn le yì diǎn dàn zhōng jiū hái shì zài hé shì de shí hou dào dá le tā gāi qù de dì fang"],"translations":["Ở góc phố cũ có một tiệm sửa đồng hồ, mặt tiền hẹp đến mức chỉ vừa một cái bàn và một chiếc ghế. Ông Trần đã sửa đồng hồ ở đây bốn mươi năm. Mấy năm nay, cửa hàng hai bên phố thay hết lứa này đến lứa khác, tiệm vải thành tiệm điện thoại, tiệm điện thoại lại thành quán trà sữa, chỉ có tiệm nhỏ của ông là chẳng đổi thay. Giờ người đeo đồng hồ ngày càng ít, buôn bán dĩ nhiên ế ẩm, nhưng tám giờ sáng nào ông cũng vẫn mở cửa đúng giờ, đeo kính lúp, lau những linh kiện trên bàn sạch không một hạt bụi.","Đó là một buổi chiều đầu thu, một người phụ nữ chừng ba mươi tuổi đẩy cửa bước vào. Chị mặc chiếc áo khoác dài màu xám, nét mặt có phần mệt mỏi, cẩn thận lấy từ trong túi ra một chiếc đồng hồ cũ đặt lên bàn.","\"Bác ơi, chiếc đồng hồ này dừng mấy năm rồi, bác xem còn sửa được không ạ?\"","Ông Trần cầm lên, lật qua xem. Đó là một chiếc đồng hồ nam kiểu cũ rất bình thường, dây đã thay, mặt kính có vài vết xước mảnh, kim dừng ở chín giờ hai mươi. Ông thấy chiếc đồng hồ hơi quen mắt, nhưng nhất thời không nhớ ra đã thấy ở đâu.","\"Đây là của bố cháu.\" Người phụ nữ khẽ nói. \"Tháng trước ông mất. Lúc dọn đồ ông để lại, cháu thấy nó dưới gối. Ông đeo nó hơn ba mươi năm, sau này hỏng rồi cũng không nỡ vứt.\" Chị ngừng một chút rồi nói thêm: \"Hồi nhỏ cháu hay nghe ông bảo trong phố có một ông thợ sửa đồng hồ tay nghề giỏi nhất, cháu nghĩ chắc là bác.\"","Ông Trần gật đầu, không hỏi thêm. Ông dùng dụng cụ nhẹ nhàng mở nắp sau, vừa định kiểm tra bộ máy bên trong thì động tác bỗng khựng lại. Ở mặt trong nắp sau có dán một mảnh giấy gấp cực nhỏ, giấy đã ngả vàng, các góc hơi quăn lên.","Đúng khoảnh khắc ấy, một ký ức bị lãng quên nhiều năm chợt hiện ra trước mắt ông.","Khoảng tám năm trước, một người đàn ông tóc đã điểm bạc đến tiệm sửa chiếc đồng hồ này. Sửa xong, ông ta mãi không chịu về, do dự hồi lâu mới đỏ mặt rút từ túi ra một mảnh giấy gấp sẵn, hỏi ông Trần có thể giấu nó vào trong đồng hồ không. \"Con gái tôi đi xa nhiều năm rồi, bố con tôi... từng cãi nhau một trận, sau đó rất ít nói chuyện. Tôi vụng miệng, có những lời không nói thẳng ra được.\" Người đàn ông cúi đầu nói, \"Nếu một ngày nào đó nó cầm chiếc đồng hồ này đến tìm ông, tức là tôi không còn nữa. Đến lúc ấy, phiền ông đưa mảnh giấy này cho nó.\"","Ông Trần khi ấy nhận lời, còn đùa: \"Ông khỏe mạnh thế này, chiếc đồng hồ còn phải đợi hai ba chục năm nữa.\" Người đàn ông cười cười, không nói gì. Từ đó về sau, ông ta không bao giờ quay lại. Lâu dần, ông Trần lại quên sạch chuyện này.","Ông Trần cẩn thận gỡ mảnh giấy, đưa cho người phụ nữ: \"Đây là thứ bố cháu để lại cho cháu. Tám năm trước, ông ấy nhờ bác bỏ vào.\"","Người phụ nữ sững lại, ngón tay hơi run run mở mảnh giấy ra. Chữ trên đó xiêu xiêu vẹo vẹo, nhìn là biết người viết không mấy khi cầm bút:","\"Vũ à: Chiếc đồng hồ này bố mua năm con ra đời. Hôm đó con khóc to lắm, cô y tá bảo con bé này giọng to thế, sau này chắc chắn làm nên chuyện. Năm ấy con nhất quyết đi Bắc Kinh học vẽ, bố đã nói nhiều lời khó nghe, bảo con không lo làm việc đàng hoàng, bảo con sau này đừng về nữa. Thật ra hôm con đi, bố đứng ngoài nhà ga rất lâu, đến khi tàu chạy xa rồi mới về nhà. Từng tấm bưu thiếp, từng tấm ảnh chụp tranh con gửi về, bố đều cất cả, để trong cái hộp trên cùng của tủ. Cả đời bố không biết nói lời hay, chỉ muốn nói với con: con làm rất tốt, bố tự hào về con.\"","Đọc xong, người phụ nữ bịt miệng, nước mắt từng giọt từng giọt rơi xuống mặt quầy kính. Ông Trần lặng lẽ quay đi, vờ tìm linh kiện trên giá để chừa cho chị một chút không gian. Trong tiệm rất yên tĩnh, chỉ nghe tiếng mấy chục chiếc đồng hồ treo tường chạy \"tích tắc tích tắc\".","Rất lâu sau, người phụ nữ mới bình tĩnh lại. Chị kể, trước khi mất bố chị nằm viện suốt, lúc chị vội về thì ông đã không nói được nữa, chỉ nắm chặt tay chị. Chị vẫn luôn nghĩ, đến cuối cùng bố cũng không tha thứ cho mình.","Ông Trần không đáp lời, cúi đầu chăm chú sửa đồng hồ. Thật ra hỏng hóc không lớn, chỉ là vài linh kiện đã cũ. Nửa tiếng sau, ông đưa trả chiếc đồng hồ. Kim giây lại bắt đầu chuyển động, phát ra âm thanh khẽ khàng mà rõ ràng.","Người phụ nữ muốn trả tiền, ông Trần xua tay: \"Tiền này, bố cháu đã trả từ tám năm trước rồi.\"","Người phụ nữ đi rồi, ông Trần đứng ở cửa nhìn bóng chị khuất dần nơi góc phố. Ông nghĩ, mình sửa đồng hồ cả đời, sửa chính là thời gian, nhưng thời gian chưa bao giờ quay ngược. Có điều, có những lời giống như mảnh giấy giấu trong vỏ đồng hồ, tuy muộn một chút, nhưng rốt cuộc vẫn đến được nơi nó cần đến, vào đúng lúc thích hợp."],"questions":[{"q":"第一段描写老陈的修表铺，主要想表现什么？","q_vi":"Đoạn 1 miêu tả tiệm sửa đồng hồ của ông Trần chủ yếu để thể hiện điều gì?","options":["老街的生意越来越好","老陈不想换别的工作是因为懒","在不断变化的时代里，老陈一直坚持做自己的事","修表是一门很赚钱的手艺"],"answer":2,"explain_vi":"Các cửa hàng xung quanh thay đổi liên tục, khách ít dần, nhưng ông Trần vẫn mở cửa đúng giờ mỗi ngày — thể hiện sự kiên trì giữa thời cuộc đổi thay."},{"q":"老陈打开后盖后为什么忽然停住了？","q_vi":"Vì sao ông Trần mở nắp sau ra thì bỗng khựng lại?","options":["他发现了一张纸条，想起了八年前的事","他发现表里的零件都坏了","他发现这块表是假的","他的工具突然坏了"],"answer":0,"explain_vi":"Đoạn 6–7: ông thấy mảnh giấy dán trong nắp sau, và ký ức tám năm trước chợt hiện về."},{"q":"女人的父亲为什么要把纸条藏在表里？","q_vi":"Vì sao bố của người phụ nữ giấu mảnh giấy trong đồng hồ?","options":["他想考验老陈是不是诚实","他怕女儿发现他生病了","他想让女儿学会修表","他不善于表达，有些话当面说不出口"],"answer":3,"explain_vi":"Đoạn 8: ông nói mình vụng miệng, có những lời không nói thẳng ra được, và hai bố con từng cãi nhau."},{"q":"读了纸条以后，女人最可能明白了什么？","q_vi":"Đọc mảnh giấy xong, người phụ nữ nhiều khả năng hiểu ra điều gì?","options":["父亲一直反对她学画画","父亲其实早就原谅了她，并且为她骄傲","父亲希望她回老家工作","父亲把表留给她是为了让她卖掉"],"answer":1,"explain_vi":"Đoạn 12 và 14: chị vốn nghĩ bố không tha thứ cho mình, nhưng thư viết bố cất giữ mọi tranh của chị và tự hào về chị."},{"q":"老陈说“这钱，你父亲八年前就付过了”，意思是什么？","q_vi":"Ông Trần nói \"Tiền này, bố cháu đã trả từ tám năm trước rồi\" có ý gì?","options":["她父亲八年前预付了修表费","老陈记错了时间","老陈不愿收钱，把这次修表当作完成她父亲的托付","老陈觉得修表太简单，不值得收钱"],"answer":2,"explain_vi":"Đây là cách nói tế nhị: ông không lấy tiền, coi việc sửa đồng hồ và trao thư là hoàn thành lời nhờ cậy của người cha."}],"beyond":[["容下","róngxià","DUNG HẠ","chứa được, vừa"],["穿着","chuānzhuó","XUYÊN TRƯỚC","cách ăn mặc · trang phục, cách ăn mặc"],["遗物","yíwù","DI VẬT","di vật, kỷ vật của người đã khuất"],["枕头","zhěntou","CHẨM ĐẦU","cái gối"],["遗忘","yíwàng","DI VONG","quên lãng · lãng quên, quên lãng"],["浮现","fúxiàn","PHÙ HIỆN","hiện lên (trong đầu) · hiện lên; hiển hiện; nổi lên (trong tâm trí)"],["迟迟","chíchí","TRÌ TRÌ","mãi mà không, lần lữa mãi, chậm trễ"],["不肯","bù kěn","BẤT KHẲNG","không chịu, không bằng lòng, từ chối"],["硬朗","yìnglang","NGẠNH LÃNG","quắc thước, khỏe khoắn, cứng cáp (người già)"],["微微","wēiwēi","VI VI","hơi hơi, khẽ"],["捂","wǔ","Ô","che, bịt (miệng) · bịt, che kín, ấp ủ"],["架子","jiàzi","GIÁ TỬ","giá; khung; kệ; thói kiêu căng; vẻ ta đây"],["老化","lǎohuà","LÃO HÓA","lão hóa, thoái hóa do tuổi tác/thời gian"],["轻微","qīngwēi","KHINH VI","nhẹ, không đáng kể · nhẹ, nhỏ, không đáng kể"],["背影","bèiyǐng","BỐI ẢNH","bóng dáng từ phía sau, bóng lưng (Hình ảnh cơ thể nhìn từ phía mặt sau lưng)"]]},{"id":"h6-03","level":6,"title":"遗忘，是大脑的智慧","title_vi":"Lãng quên là trí tuệ của bộ não","topic":"khoa học thường thức","chars":1250,"paragraphs":["考试前一天晚上背得滚瓜烂熟的单词，第二天一进考场就忘得一干二净；刚认识的新同事，介绍完名字不到五分钟就想不起来了；明明记得要买牛奶，到了超市却买了一堆别的东西，偏偏忘了牛奶。几乎每个人都为健忘烦恼过，甚至希望自己能拥有“过目不忘”的本领。","然而，越来越多的研究表明，忘记并不是大脑的缺陷，而是一种经过长期进化形成的功能。如果一个人真的什么都忘不掉，生活不但不会更美好，反而可能变成一场灾难。","十九世纪末，德国心理学家艾宾浩斯做了一个著名的实验。他让自己记忆大量没有意义的字母组合，然后在不同的时间间隔后测试自己还能记住多少。结果发现，忘记在学习之后立刻开始，而且最初的速度非常快：二十分钟后，大约忘掉了四成；一天以后，忘掉了将近七成；此后，忘记的速度逐渐放慢。根据这些数据画出的曲线，就是后来广为人知的“遗忘曲线”。","很长一段时间里，人们把遗忘曲线看作大脑“不够用”的证据。但从另一个角度看，这条曲线恰恰说明，大脑在不停地进行筛选：那些只用过一次、和生活关系不大的信息，会很快被清除；而那些反复出现、对我们有用的信息，则会被保存下来。","医学上曾记录过一些记忆力超常的人。有一位女性能清楚地回忆起自己十几岁以后几乎每一天发生的事：那天是星期几，天气如何，吃了什么，和谁说过什么话。听上去令人羡慕，可她本人却说，这种能力更像是一种负担。过去的痛苦和尴尬会不受控制地涌上心头，每一次都像刚刚发生一样清晰。她无法像普通人那样把过去的事放下，常常被困在回忆里，难以专心面对眼前的生活。","这个例子告诉我们，遗忘的重要作用之一，就是保护我们的情绪。随着时间的推移，痛苦的记忆会逐渐变得模糊，心里的伤口才有机会慢慢愈合。我们之所以能从失败、失去和伤害中走出来，在很大程度上要感谢大脑这种“有选择的遗忘”。","遗忘的另一个作用，是帮助我们更好地思考。科学家发现，大脑在储存记忆时，并不会把每一个细节都原封不动地保留下来，而是倾向于提取其中的规律和要点。比如，你可能记不清自己见过的每一只狗长什么样，却能一眼认出眼前的动物是一只狗。正是因为忘掉了大量无关紧要的细节，我们才能概括、归纳，把经验运用到新的情况中去。一个记住所有细节的大脑，反而可能被信息淹没，无法做出灵活的判断。","那么，睡眠和遗忘又有什么关系呢？近年来的研究表明，睡觉时大脑并没有完全休息，而是在整理白天收集的信息：重要的内容被加强，不重要的连接被削弱。所以，熬夜复习往往事倍功半，而保证充足的睡眠，才能让真正需要的知识留下来。","了解了忘记的规律，我们就可以更聪明地学习。既然忘记在学习后立刻开始，而且先快后慢，那么最有效的办法就是在快要忘记的时候及时复习。第一次复习可以安排在学习后的当天，然后是第二天、一周后、一个月后，复习的间隔逐渐拉长。这种方法被称为“间隔重复”，如今许多背单词的软件都是根据这一原理设计的。","此外，把新知识和已有的经验联系起来，也能让记忆更加牢固。比如学一个新词时，不要只是孤立地背它的意思，而要把它放进一个句子、一个故事里，甚至和自己的亲身经历联系起来。大脑认为“有用”“有意义”的东西，自然更愿意保留。","说到底，遗忘和记忆并不是对立的两面，而是同一个过程中相互配合的两个部分。正如一位科学家所说：“记忆的目的不是保存过去，而是帮助我们更好地面对未来。”下次再忘记什么事情的时候，也许不必太懊恼——那可能只是你的大脑在替你做选择。"],"pinyin":["kǎo shì qián yī tiān wǎn shang bèi dé gǔn guā làn shú de dān cí dì èr tiān yī jìn kǎo chǎng jiù wàng de yī gān èr jìng gāng rèn shi de xīn tóng shì jiè shào wán míng zi bú dào wǔ fēn zhōng jiù xiǎng bù qǐ lái le míng míng jì de yào mǎi niú nǎi dào le chāo shì què mǎi le yī duī bié de dōng xi piān piān wàng le niú nǎi jī hū měi gè rén dōu wèi jiàn wàng fán nǎo guò shèn zhì xī wàng zì jǐ néng yōng yǒu guò mù bù wàng de běn lǐng","rán ér yuè lái yuè duō de yán jiū biǎo míng wàng jì bìng bú shì dà nǎo de quē xiàn ér shì yī zhǒng jīng guò cháng qī jìn huà xíng chéng de gōng néng rú guǒ yí gè rén zhēn de shén me dōu wàng bù diào shēng huó bù dàn bú huì gèng měi hǎo fǎn ér kě néng biàn chéng yī cháng zāi nàn","shí jiǔ shì jì mò dé guó xīn lǐ xué jiā ài bīn hào sī zuò le yí gè zhù míng de shí yàn tā ràng zì jǐ jì yì dà liàng méi yǒu yì yì de zì mǔ zǔ hé rán hòu zài bù tóng de shí jiān jiàn gé hòu cè shì zì jǐ hái néng jì zhù duō shǎo jié guǒ fā xiàn wàng jì zài xué xí zhī hòu lì kè kāi shǐ ér qiě zuì chū de sù dù fēi cháng kuài èr shí fēn zhōng hòu dà yuē wàng diào le sì chéng yī tiān yǐ hòu wàng diào le jiāng jìn qī chéng cǐ hòu wàng jì de sù dù zhú jiàn fàng màn gēn jù zhè xiē shù jù huà chū de qū xiàn jiù shì hòu lái guǎng wéi rén zhī de yí wàng qū xiàn","hěn zhǎng yī duàn shí jiān lǐ rén men bǎ yí wàng qū xiàn kàn zuò dà nǎo bù gòu yòng de zhèng jù dàn cóng lìng yí gè jiǎo dù kàn zhè tiáo qū xiàn qià qià shuō míng dà nǎo zài bù tíng de jìn xíng shāi xuǎn nà xiē zhǐ yòng guò yī cì hé shēng huó guān xi bù dà de xìn xī huì hěn kuài bèi qīng chú ér nà xiē fǎn fù chū xiàn duì wǒ men yǒu yòng de xìn xī zé huì bèi bǎo cún xià lái","yī xué shàng céng jì lù guò yī xiē jì yì lì chāo cháng de rén yǒu yī wèi nǚ xìng néng qīng chu de huí yì qǐ zì jǐ shí jǐ suì yǐ hòu jī hū měi yī tiān fā shēng de shì nà tiān shì xīng qī jǐ tiān qì rú hé chī le shén me hé shuí shuō guò shén me huà tīng shàng qù lìng rén xiàn mù kě tā běn rén què shuō zhè zhǒng néng lì gèng xiàng shì yī zhǒng fù dān guò qù de tòng kǔ hé gān gà huì bù shòu kòng zhì dì yǒng shàng xīn tóu měi yī cì dōu xiàng gāng gāng fā shēng yī yàng qīng xī tā wú fǎ xiàng pǔ tōng rén nà yàng bǎ guò qù de shì fàng xià cháng cháng bèi kùn zài huí yì lǐ nán yǐ zhuān xīn miàn duì yǎn qián de shēng huó","zhè ge lì zi gào su wǒ men yí wàng de zhòng yào zuò yòng zhī yī jiù shì bǎo hù wǒ men de qíng xù suí zhe shí jiān de tuī yí tòng kǔ de jì yì huì zhú jiàn biàn dé mó hú xīn lǐ de shāng kǒu cái yǒu jī huì màn màn yù hé wǒ men zhī suǒ yǐ néng cóng shī bài shī qù hé shāng hài zhōng zǒu chū lái zài hěn dà chéng dù shàng yào gǎn xiè dà nǎo zhè zhǒng yǒu xuǎn zé de yí wàng","yí wàng de lìng yí gè zuò yòng shì bāng zhù wǒ men gèng hǎo de sī kǎo kē xué jiā fā xiàn dà nǎo zài chǔ cún jì yì shí bìng bú huì bǎ měi yí gè xì jié dōu yuán fēng bù dòng de bǎo liú xià lái ér shì qīng xiàng yú tí qǔ qí zhōng de guī lǜ hé yào diǎn bǐ rú nǐ kě néng jì bù qīng zì jǐ jiàn guò de měi yī zhī gǒu zhǎng shén me yàng què néng yī yǎn rèn chū yǎn qián de dòng wù shì yī zhī gǒu zhèng shì yīn wèi wàng diào le dà liàng wú guān jǐn yào de xì jié wǒ men cái néng gài kuò guī nà bǎ jīng yàn yùn yòng dào xīn de qíng kuàng zhōng qù yí gè jì zhù suǒ yǒu xì jié de dà nǎo fǎn ér kě néng bèi xìn xī yān mò wú fǎ zuò chū líng huó de pàn duàn","nà me shuì mián hé yí wàng yòu yǒu shén me guān xi ne jìn nián lái de yán jiū biǎo míng shuì jiào shí dà nǎo bìng méi yǒu wán quán xiū xī ér shì zài zhěng lǐ bái tiān shōu jí de xìn xī zhòng yào de nèi róng bèi jiā qiáng bù zhòng yào de lián jiē bèi xuē ruò suǒ yǐ áo yè fù xí wǎng wǎng shì bèi gōng bàn ér bǎo zhèng chōng zú de shuì mián cái néng ràng zhēn zhèng xū yào de zhī shí liú xià lái","liǎo jiě le wàng jì de guī lǜ wǒ men jiù kě yǐ gèng cōng ming de xué xí jì rán wàng jì zài xué xí hòu lì kè kāi shǐ ér qiě xiān kuài hòu màn nà me zuì yǒu xiào de bàn fǎ jiù shì zài kuài yào wàng jì de shí hou jí shí fù xí dì yī cì fù xí kě yǐ ān pái zài xué xí hòu de dàng tiān rán hòu shì dì èr tiān yī zhōu hòu yí gè yuè hòu fù xí de jiàn gé zhú jiàn lā cháng zhè zhǒng fāng fǎ bèi chēng wéi jiàn gé chóng fù rú jīn xǔ duō bèi dān cí de ruǎn jiàn dōu shì gēn jù zhè yī yuán lǐ shè jì de","cǐ wài bǎ xīn zhī shí hé yǐ yǒu de jīng yàn lián xì qǐ lái yě néng ràng jì yì gèng jiā láo gù bǐ rú xué yí gè xīn cí shí bú yào zhǐ shì gū lì dì bèi tā de yì si ér yào bǎ tā fàng jìn yí gè jù zi yí gè gù shì lǐ shèn zhì hé zì jǐ de qīn shēn jīng lì lián xì qǐ lái dà nǎo rèn wéi yǒu yòng yǒu yì yì de dōng xi zì rán gèng yuàn yì bǎo liú","shuō dào dǐ yí wàng hé jì yì bìng bú shì duì lì de liǎng miàn ér shì tóng yī gè guò chéng zhōng xiāng hù pèi hé de liǎng gè bù fen zhèng rú yī wèi kē xué jiā suǒ shuō jì yì de mù dì bú shì bǎo cún guò qù ér shì bāng zhù wǒ men gèng hǎo dì miàn duì wèi lái xià cì zài wàng jì shén me shì qing de shí hou yě xǔ bù bì tài ào nǎo nà kě néng zhǐ shì nǐ de dà nǎo zài tì nǐ zuò xuǎn zé"],"translations":["Những từ vựng thuộc làu làu vào tối hôm trước kỳ thi, hôm sau vừa bước vào phòng thi đã quên sạch sành sanh; người đồng nghiệp mới quen, giới thiệu tên xong chưa đầy năm phút đã không nhớ nổi; rõ ràng nhớ là phải mua sữa, đến siêu thị lại mua cả đống thứ khác, khéo làm sao lại quên đúng hộp sữa. Hầu như ai cũng từng phiền muộn vì tính hay quên, thậm chí mong mình có tài \"xem qua là nhớ\".","Thế nhưng, ngày càng nhiều nghiên cứu cho thấy lãng quên không phải là khiếm khuyết của bộ não, mà là một chức năng hình thành qua quá trình tiến hóa lâu dài. Nếu một người thật sự cái gì cũng không quên được, cuộc sống chẳng những không tốt đẹp hơn mà còn có thể trở thành một tai họa.","Cuối thế kỷ XIX, nhà tâm lý học người Đức Ebbinghaus đã làm một thí nghiệm nổi tiếng. Ông tự ghi nhớ một lượng lớn tổ hợp chữ cái vô nghĩa, rồi sau những khoảng thời gian khác nhau kiểm tra xem mình còn nhớ được bao nhiêu. Kết quả cho thấy, sự lãng quên bắt đầu ngay sau khi học, và lúc đầu tốc độ rất nhanh: sau hai mươi phút quên khoảng bốn phần mười; sau một ngày quên gần bảy phần mười; sau đó tốc độ quên chậm dần. Đường cong vẽ ra từ những số liệu này chính là \"đường cong lãng quên\" về sau ai cũng biết.","Trong một thời gian dài, người ta coi đường cong lãng quên là bằng chứng cho thấy bộ não \"không đủ dùng\". Nhưng nhìn từ góc độ khác, đường cong này lại cho thấy bộ não không ngừng sàng lọc: những thông tin chỉ dùng một lần, ít liên quan đến cuộc sống sẽ nhanh chóng bị xóa đi; còn những thông tin xuất hiện lặp lại, có ích cho ta thì được giữ lại.","Y học từng ghi nhận một số người có trí nhớ phi thường. Có một phụ nữ có thể nhớ rõ hầu như từng ngày trong đời mình từ năm mười mấy tuổi: hôm đó là thứ mấy, thời tiết ra sao, đã ăn gì, đã nói gì với ai. Nghe thì đáng ngưỡng mộ, nhưng chính bà lại nói khả năng ấy giống một gánh nặng hơn. Những đau khổ và ngượng ngùng trong quá khứ cứ ùa về trong lòng mà không kiểm soát được, lần nào cũng rõ ràng như vừa mới xảy ra. Bà không thể như người bình thường mà buông bỏ chuyện đã qua, thường xuyên bị mắc kẹt trong hồi ức, khó tập trung đối diện với cuộc sống trước mắt.","Ví dụ này cho ta biết, một trong những tác dụng quan trọng của lãng quên là bảo vệ cảm xúc. Theo thời gian, ký ức đau khổ dần nhạt nhòa, vết thương trong lòng mới có cơ hội từ từ lành lại. Sở dĩ chúng ta có thể bước ra khỏi thất bại, mất mát và tổn thương, phần lớn phải cảm ơn khả năng \"lãng quên có chọn lọc\" này của bộ não.","Một tác dụng khác của lãng quên là giúp ta suy nghĩ tốt hơn. Các nhà khoa học phát hiện, khi lưu trữ ký ức, bộ não không giữ nguyên vẹn từng chi tiết, mà có xu hướng rút ra quy luật và điểm chính. Ví dụ, có thể bạn không nhớ rõ từng con chó mình từng gặp trông thế nào, nhưng liếc qua là nhận ra con vật trước mắt là một con chó. Chính vì quên đi vô số chi tiết không quan trọng, ta mới có thể khái quát, quy nạp, vận dụng kinh nghiệm vào tình huống mới. Một bộ não nhớ hết mọi chi tiết, ngược lại có thể bị thông tin nhấn chìm, không thể đưa ra phán đoán linh hoạt.","Vậy giấc ngủ và sự lãng quên có liên quan gì? Các nghiên cứu những năm gần đây cho thấy, khi ngủ bộ não không hoàn toàn nghỉ ngơi, mà đang sắp xếp thông tin thu thập ban ngày: nội dung quan trọng được củng cố, những kết nối không quan trọng bị làm yếu đi. Vì thế, thức khuya ôn bài thường tốn công mà ít hiệu quả, còn ngủ đủ giấc mới giúp những kiến thức thật sự cần thiết được giữ lại.","Hiểu được quy luật của lãng quên, ta có thể học thông minh hơn. Đã biết sự lãng quên bắt đầu ngay sau khi học, lại nhanh trước chậm sau, thì cách hiệu quả nhất là ôn kịp thời vào lúc sắp quên. Lần ôn đầu tiên có thể xếp ngay trong ngày học, rồi đến hôm sau, một tuần sau, một tháng sau, khoảng cách giữa các lần ôn dần kéo dài. Phương pháp này được gọi là \"lặp lại ngắt quãng\", ngày nay nhiều phần mềm học từ vựng được thiết kế dựa trên nguyên lý này.","Ngoài ra, gắn kiến thức mới với kinh nghiệm sẵn có cũng giúp trí nhớ bền chắc hơn. Chẳng hạn khi học một từ mới, đừng chỉ học thuộc nghĩa của nó một cách tách rời, mà hãy đặt nó vào một câu, một câu chuyện, thậm chí gắn với trải nghiệm của chính mình. Những thứ bộ não cho là \"có ích\", \"có ý nghĩa\" thì đương nhiên nó sẵn lòng giữ lại hơn.","Suy cho cùng, lãng quên và ghi nhớ không phải hai mặt đối lập, mà là hai phần phối hợp với nhau trong cùng một quá trình. Như một nhà khoa học từng nói: \"Mục đích của trí nhớ không phải là lưu giữ quá khứ, mà là giúp ta đối mặt với tương lai tốt hơn.\" Lần tới khi quên điều gì đó, có lẽ không cần quá bực bội — đó có thể chỉ là bộ não đang chọn lựa thay bạn."],"questions":[{"q":"根据“遗忘曲线”，下面哪种说法是正确的？","q_vi":"Theo \"đường cong lãng quên\", nhận định nào dưới đây đúng?","options":["学习一周以后才开始遗忘","遗忘的速度一直保持不变","刚学完时遗忘最快，以后逐渐变慢","一天以后几乎什么都不记得了"],"answer":2,"explain_vi":"Đoạn 3: quên bắt đầu ngay sau khi học, lúc đầu rất nhanh (20 phút quên 4/10, một ngày gần 7/10), sau đó chậm dần."},{"q":"作者提到那位记忆力超常的女性，是为了说明什么？","q_vi":"Tác giả nhắc đến người phụ nữ có trí nhớ phi thường để nói lên điều gì?","options":["什么都忘不掉其实是一种负担","记忆力好的人都很成功","女性的记忆力比男性好","每个人都可以训练出超常的记忆力"],"answer":0,"explain_vi":"Đoạn 5: bà nói khả năng ấy là gánh nặng, ký ức đau khổ cứ ùa về, khiến bà mắc kẹt trong quá khứ."},{"q":"第七段中，“一个记住所有细节的大脑，反而可能被信息淹没”的意思是：","q_vi":"Ở đoạn 7, câu \"một bộ não nhớ hết mọi chi tiết, ngược lại có thể bị thông tin nhấn chìm\" có nghĩa là:","options":["大脑的空间很快就会被用完","细节太多会妨碍人总结规律、灵活思考","记住细节的人更容易生病","信息越多，判断就越准确"],"answer":1,"explain_vi":"Đoạn 7: nhờ quên chi tiết vụn vặt ta mới khái quát, quy nạp được; nhớ hết chi tiết lại khiến khó phán đoán linh hoạt."},{"q":"根据文章，下面哪种复习方法最合理？","q_vi":"Theo bài, cách ôn tập nào dưới đây hợp lý nhất?","options":["考试前一天熬夜把所有内容复习一遍","学完以后一个月再复习","每天把同样的内容复习十遍","在快要忘记的时候复习，间隔逐渐拉长"],"answer":3,"explain_vi":"Đoạn 8–9: thức khuya ôn bài là tốn công ít hiệu quả; nên ôn lúc sắp quên với khoảng cách kéo dài dần (lặp lại ngắt quãng)."},{"q":"这篇文章的主要观点是什么？","q_vi":"Quan điểm chính của bài viết là gì?","options":["人应该努力做到过目不忘","遗忘是大脑的一种有用的功能，和记忆相互配合","睡眠对记忆没有影响","背单词的软件没有什么用"],"answer":1,"explain_vi":"Tiêu đề và đoạn cuối: lãng quên là trí tuệ của bộ não, là phần phối hợp với ghi nhớ trong cùng một quá trình."}],"beyond":[["一干二净","yīgān-èrjìng","NHẤT CAN NHỊ TỊNH","sạch sành sanh, hết sạch, không còn chút nào"],["德国","Déguó","ĐỨC QUỐC","Nước Đức"],["心理学家","xīnlǐxuéjiā","TÂM LÝ HỌC GIA","nhà tâm lý học"],["忘掉","wàngdiào","VONG TRẠO","quên đi, quên sạch"],["曲线","qūxiàn","KHÚC TUYẾN","đường cong, đường lượn sóng · đường cong"],["为人","wéirén","VI NHÂN","đối nhân xử thế, cách làm người; tính cách phẩm hạnh"],["遗忘","yíwàng","DI VONG","quên lãng · lãng quên, quên lãng"],["记忆力","jìyìlì","KÝ ỨC LỰC","trí nhớ"],["心头","xīntóu","TÂM ĐẦU","trong lòng"],["普通人","pǔtōng rén","PHỔ THÔNG NHÂN","người bình thường, dân thường"],["推移","tuīyí","THÔI DI","trôi qua (thời gian); biến chuyển, thay đổi (tình hình)"],["愈合","yùhé","DŨ HỢP","lành lại, liền sẹo, khép miệng (vết thương)"],["之所以","zhīsuǒyǐ","CHI SỞ DĨ","sở dĩ, lý do mà..."],["一眼","yīyǎn","NHẤT NHÃN","một cái liếc mắt, một ánh nhìn, một mắt nhìn"],["无关紧要","wúguān-jǐnyào","VÔ QUAN KHẨN YẾU","không quan trọng, không đáng kể, không can hệ gì"],["近年来","jìnnián lái","CẬN NIÊN LAI","những năm gần đây, dạo gần đây"],["说到底","shuōdàodǐ","THUYẾT ĐÁO ĐỂ","nói cho cùng, rốt cuộc"]]},{"id":"h6-04","level":6,"title":"园林里的“看不见”","title_vi":"Cái \"không nhìn thấy\" trong lâm viên","topic":"văn hóa – du lịch","chars":1225,"paragraphs":["第一次去苏州看园林，我其实是有些失望的。导游带着我们从一个院子走到另一个院子，四周都是白墙、灰瓦、假山和池塘，面积也不算大，跟我想象中宏伟的宫殿完全不同。走了不到一个小时，我就觉得这些园子看起来都差不多，忍不住问同行的朋友：“这有什么好看的？”","朋友是学建筑的，听了我的话只是笑笑，说：“你走得太快了。园林不是用来‘逛’的，是用来‘看’的。”她拉着我在一扇窗前停下来。那是一扇刻着花纹的窗户，形状像一片树叶。透过窗户望出去，正好看到墙外的一丛竹子和半块石头，在阳光下投下深深浅浅的影子，就像一幅装在画框里的水墨画。","“这叫‘框景’。”朋友解释说，“设计园林的人故意在墙上开各种形状的窗，有圆的、方的、扇形的，还有花瓶形的。人走到每一扇窗前，看到的都是一幅不同的画。窗户就像画框，把外面的风景‘框’了起来。”","我这才注意到，走廊的墙上每隔几步就有一扇窗，而且没有两扇是一样的。我放慢脚步，一扇一扇地看过去，果然，每一扇窗后面的景色都不同：有时是一棵梅树，有时是屋顶的一角，有时只是白墙上落下的树影。随着脚步移动，画面也在不断变化，好像在看一部没有声音的电影。","朋友又带我走到一座假山前。假山不高，却很复杂，里面有弯弯曲曲的小路。我们从一头钻进去，眼前一会儿暗、一会儿亮，转了几个弯，从另一头出来的时候，竟然看到了一片完全意想不到的水面，水上有一座小亭子，几棵柳树垂在岸边。“这叫‘欲扬先抑’，”朋友说，“先让你看不见，再让你突然看见，惊喜就是这样制造出来的。”","原来，园林最讲究的，恰恰是“看不见”。中国古代的园林大多建在城市里，面积有限。为了在小小的空间里表现出山水的无限，设计者想尽了办法：用墙把园子分成许多小区域，让人无法一眼看到全部；用曲折的走廊和小路延长行走的路线；在墙的另一边“借”来远处的塔或山，让园子显得比实际更大。这种“藏”与“露”的艺术，让一个并不大的园子，走上半天也不觉得重复。","这让我想起中国传统绘画中的“留白”。一幅山水画，往往有大片空白，可能是天空，可能是水面，也可能是云雾。画家并不把一切都画满，而是给看画的人留下想象的空间。园林也是如此，它不把所有的风景一下子摆在你面前，而是让你一边走，一边发现，一边想象。","在一座小亭子里休息的时候，朋友给我讲了一个故事。据说古时候有一位主人建好了园子，请朋友来参观。客人看了一圈，说园子里什么都好，就是少了一点“声音”。主人想了想，在窗外种了几棵芭蕉。从此每到下雨的时候，雨点打在宽大的叶子上，发出清脆的声音，坐在屋里就能“听”到园子里的风景。","我忽然明白，园林的美不只在于眼睛看到的东西，还在于声音、光线、季节，甚至心情。春天看花，夏天听雨，秋天赏月，冬天观雪，同一个角落，在不同的时间会给人完全不同的感受。古人造园，其实是在创造一种生活方式——一种慢下来、静下来，和自然对话的生活。","离开苏州前的最后一个早上，我一个人又去了一次那座园子。那天游客很少，我没有看地图，也没有赶路，只是随意地走，看到喜欢的窗就停下来，看到合适的石凳就坐一会儿。一只鸟落在墙头，叫了几声又飞走了；池塘里的鱼慢慢地游过一片落叶的影子。那一个小时，我好像什么也没做，却觉得心里满满的。","回到城市以后，我又回到了忙碌的日常。每天匆匆忙忙地赶地铁、开会、回消息，眼睛总是盯着下一个目标。可是偶尔，我会想起园林里那一扇扇小窗。也许生活和园林一样，最美的风景，往往不在终点，而在那些我们愿意停下脚步的地方。"],"pinyin":["dì yī cì qù sū zhōu kàn yuán lín wǒ qí shí shì yǒu xiē shī wàng de dǎo yóu dài zhe wǒ men cóng yí gè yuàn zi zǒu dào lìng yí gè yuàn zi sì zhōu dōu shì bái qiáng huī wǎ jiǎ shān hé chí táng miàn jī yě bù suàn dà gēn wǒ xiǎng xiàng zhōng hóng wěi de gōng diàn wán quán bù tóng zǒu le bú dào yí gè xiǎo shí wǒ jiù jué de zhè xiē yuán zi kàn qǐ lái dōu chà bu duō rěn bú zhù wèn tóng háng de péng you zhè yǒu shén me hǎo kàn de","péng you shì xué jiàn zhù de tīng le wǒ de huà zhǐ shì xiào xiào shuō nǐ zǒu de tài kuài le yuán lín bú shì yòng lái guàng de shì yòng lái kàn de tā lā zhe wǒ zài yī shàn chuāng qián tíng xià lái nà shì yī shàn kè zhe huā wén de chuāng hu xíng zhuàng xiàng yī piàn shù yè tòu guò chuāng hu wàng chū qù zhèng hǎo kàn dào qiáng wài de yī cóng zhú zi hé bàn kuài shí tou zài yáng guāng xià tóu xià shēn shēn qiǎn qiǎn de yǐng zi jiù xiàng yī fú zhuāng zài huà kuāng lǐ de shuǐ mò huà","zhè jiào kuāng jǐng péng you jiě shì shuō shè jì yuán lín de rén gù yì zài qiáng shàng kāi gè zhǒng xíng zhuàng de chuāng yǒu yuán de fāng de shàn xíng de hái yǒu huā píng xíng de rén zǒu dào měi yī shàn chuāng qián kàn dào de dōu shì yī fú bù tóng de huà chuāng hu jiù xiàng huà kuāng bǎ wài miàn de fēng jǐng kuāng le qǐ lái","wǒ zhè cái zhù yì dào zǒu láng de qiáng shàng měi gé jǐ bù jiù yǒu yī shàn chuāng ér qiě méi yǒu liǎng shàn shì yī yàng de wǒ fàng màn jiǎo bù yī shàn yī shàn dì kàn guò qù guǒ rán měi yī shàn chuāng hòu miàn de jǐng sè dōu bù tóng yǒu shí shì yī kē méi shù yǒu shí shì wū dǐng de yī jiǎo yǒu shí zhǐ shì bái qiáng shàng là xià de shù yǐng suí zhe jiǎo bù yí dòng huà miàn yě zài bù duàn biàn huà hǎo xiàng zài kàn yī bù méi yǒu shēng yīn de diàn yǐng","péng you yòu dài wǒ zǒu dào yī zuò jiǎ shān qián jiǎ shān bù gāo què hěn fù zá lǐ miàn yǒu wān wān qū qū de xiǎo lù wǒ men cóng yī tóu zuān jìn qù yǎn qián yī huì er àn yī huì er liàng zhuǎn le jǐ gè wān cóng lìng yī tóu chū lái de shí hou jìng rán kàn dào le yī piàn wán quán yì xiǎng bù dào de shuǐ miàn shuǐ shàng yǒu yī zuò xiǎo tíng zi jǐ kē liǔ shù chuí zài àn biān zhè jiào yù yáng xiān yì péng you shuō xiān ràng nǐ kàn bú jiàn zài ràng nǐ tū rán kàn jiàn jīng xǐ jiù shì zhè yàng zhì zào chū lái de","yuán lái yuán lín zuì jiǎng jiū de qià qià shì kàn bú jiàn zhōng guó gǔ dài de yuán lín dà duō jiàn zài chéng shì lǐ miàn jī yǒu xiàn wèi le zài xiǎo xiǎo de kōng jiān lǐ biǎo xiàn chū shān shuǐ de wú xiàn shè jì zhě xiǎng jǐn le bàn fǎ yòng qiáng bǎ yuán zi fēn chéng xǔ duō xiǎo qū yù ràng rén wú fǎ yī yǎn kàn dào quán bù yòng qū zhé de zǒu láng hé xiǎo lù yán cháng xíng zǒu de lù xiàn zài qiáng de lìng yī biān jiè lái yuǎn chù de tǎ huò shān ràng yuán zi xiǎn de bǐ shí jì gèng dà zhè zhǒng cáng yǔ lù de yì shù ràng yí gè bìng bù dà de yuán zi zǒu shàng bàn tiān yě bù jué de chóng fù","zhè ràng wǒ xiǎng qǐ zhōng guó chuán tǒng huì huà zhōng de liú bái yī fú shān shuǐ huà wǎng wǎng yǒu dà piàn kòng bái kě néng shì tiān kōng kě néng shì shuǐ miàn yě kě néng shì yún wù huà jiā bìng bù bǎ yī qiè dōu huà mǎn ér shì gěi kàn huà de rén liú xià xiǎng xiàng de kōng jiān yuán lín yě shì rú cǐ tā bù bǎ suǒ yǒu de fēng jǐng yí xià zi bǎi zài nǐ miàn qián ér shì ràng nǐ yī biān zǒu yī biān fā xiàn yī biān xiǎng xiàng","zài yī zuò xiǎo tíng zi lǐ xiū xī de shí hou péng you gěi wǒ jiǎng le yí gè gù shì jù shuō gǔ shí hou yǒu yī wèi zhǔ rén jiàn hǎo le yuán zi qǐng péng you lái cān guān kè rén kàn le yī quān shuō yuán zi lǐ shén me dōu hǎo jiù shì shǎo le yì diǎn shēng yīn zhǔ rén xiǎng le xiǎng zài chuāng wài zhǒng le jǐ kē bā jiāo cóng cǐ měi dào xià yǔ de shí hou yǔ diǎn dǎ zài kuān dà de yè zi shàng fā chū qīng cuì de shēng yīn zuò zài wū lǐ jiù néng tīng dào yuán zi lǐ de fēng jǐng","wǒ hū rán míng bai yuán lín de měi bù zhǐ zài yú yǎn jing kàn dào de dōng xi hái zài yú shēng yīn guāng xiàn jì jié shèn zhì xīn qíng chūn tiān kàn huā xià tiān tīng yǔ qiū tiān shǎng yuè dōng tiān guān xuě tóng yī gè jiǎo luò zài bù tóng de shí jiān huì gěi rén wán quán bù tóng de gǎn shòu gǔ rén zào yuán qí shí shì zài chuàng zào yī zhǒng shēng huó fāng shì yī zhǒng màn xià lái jìng xià lái hé zì rán duì huà de shēng huó","lí kāi sū zhōu qián de zuì hòu yí gè zǎo shang wǒ yí gè rén yòu qù le yī cì nà zuò yuán zi nà tiān yóu kè hěn shǎo wǒ méi yǒu kàn dì tú yě méi yǒu gǎn lù zhǐ shì suí yì de zǒu kàn dào xǐ huan de chuāng jiù tíng xià lái kàn dào hé shì de shí dèng jiù zuò yī huì er yī zhī niǎo luò zài qiáng tóu jiào le jǐ shēng yòu fēi zǒu le chí táng lǐ de yú màn màn dì yóu guò yī piàn luò yè de yǐng zi nà yí gè xiǎo shí wǒ hǎo xiàng shén me yě méi zuò què jué de xīn lǐ mǎn mǎn de","huí dào chéng shì yǐ hòu wǒ yòu huí dào le máng lù de rì cháng měi tiān cōng cōng máng máng dì gǎn dì tiě kāi huì huí xiāo xi yǎn jing zǒng shì dīng zhe xià yí gè mù biāo kě shì ǒu ěr wǒ huì xiǎng qǐ yuán lín lǐ nà yī shàn shàn xiǎo chuāng yě xǔ shēng huó hé yuán lín yī yàng zuì měi de fēng jǐng wǎng wǎng bù zài zhōng diǎn ér zài nà xiē wǒ men yuàn yì tíng xià jiǎo bù de dì fang"],"translations":["Lần đầu đến Tô Châu xem lâm viên, thật ra tôi hơi thất vọng. Hướng dẫn viên dẫn chúng tôi đi từ sân này sang sân khác, bốn bề toàn là tường trắng, ngói xám, núi giả và ao nước, diện tích cũng chẳng lớn lắm, khác hẳn những cung điện tráng lệ trong tưởng tượng của tôi. Đi chưa đầy một tiếng, tôi đã thấy các khu vườn này trông na ná nhau, không nhịn được hỏi người bạn đi cùng: \"Cái này có gì hay mà xem?\"","Bạn tôi học kiến trúc, nghe vậy chỉ cười, nói: \"Cậu đi nhanh quá. Lâm viên không phải để 'dạo', mà là để 'ngắm'.\" Cô kéo tôi dừng lại trước một ô cửa sổ. Đó là ô cửa chạm hoa văn, có hình một chiếc lá. Nhìn qua ô cửa, vừa vặn thấy một khóm trúc và nửa tảng đá bên ngoài tường, dưới nắng in xuống những chiếc bóng đậm nhạt, hệt như một bức tranh thủy mặc lồng trong khung.","\"Cái này gọi là 'khuông cảnh' — đóng khung cảnh vật.\" Bạn tôi giải thích. \"Người thiết kế lâm viên cố ý trổ trên tường đủ loại cửa sổ: tròn, vuông, hình quạt, cả hình bình hoa nữa. Người ta đi đến trước mỗi ô cửa đều thấy một bức tranh khác nhau. Cửa sổ như khung tranh, 'đóng khung' phong cảnh bên ngoài lại.\"","Lúc ấy tôi mới để ý, trên tường hành lang cứ cách vài bước lại có một ô cửa sổ, mà không có hai ô nào giống nhau. Tôi đi chậm lại, ngắm từng ô một, quả nhiên cảnh sau mỗi ô cửa đều khác: khi là một cây mai, khi là một góc mái nhà, có khi chỉ là bóng cây đổ trên bức tường trắng. Theo bước chân di chuyển, khung cảnh cũng không ngừng thay đổi, như đang xem một bộ phim không tiếng.","Bạn tôi lại dẫn tôi đến trước một hòn núi giả. Núi không cao nhưng rất phức tạp, bên trong có những lối đi quanh co. Chúng tôi chui vào từ một đầu, trước mắt lúc tối lúc sáng, rẽ mấy khúc quanh, khi ra ở đầu kia thì bất ngờ thấy một mặt nước hoàn toàn không ngờ tới, trên có một ngôi đình nhỏ, mấy cây liễu rủ bên bờ. \"Đây gọi là 'muốn nâng thì trước hãy nén',\" bạn tôi nói, \"trước hết không cho cậu thấy, rồi bất chợt cho cậu thấy, niềm vui bất ngờ được tạo ra như thế đấy.\"","Hóa ra, điều lâm viên chú trọng nhất lại chính là cái \"không nhìn thấy\". Lâm viên cổ Trung Quốc phần lớn xây trong thành, diện tích có hạn. Để thể hiện sự vô tận của núi sông trong một không gian nhỏ bé, người thiết kế đã nghĩ hết mọi cách: dùng tường chia vườn thành nhiều khu nhỏ, để người ta không thể nhìn một lượt thấy hết; dùng hành lang và lối đi quanh co để kéo dài đường đi; \"mượn\" ngọn tháp hay ngọn núi phía xa bên kia tường, khiến khu vườn trông rộng hơn thực tế. Nghệ thuật \"giấu\" và \"lộ\" này khiến một khu vườn không lớn, đi cả nửa ngày cũng không thấy lặp lại.","Điều này làm tôi nhớ đến \"lưu bạch\" — khoảng trống — trong hội họa truyền thống Trung Quốc. Một bức tranh sơn thủy thường có những mảng trống lớn, có thể là bầu trời, mặt nước, cũng có thể là mây mù. Họa sĩ không vẽ kín mọi thứ, mà để lại cho người xem khoảng không để tưởng tượng. Lâm viên cũng vậy, nó không bày hết phong cảnh ra trước mắt bạn cùng một lúc, mà để bạn vừa đi, vừa khám phá, vừa tưởng tượng.","Khi nghỉ chân trong một ngôi đình nhỏ, bạn tôi kể một câu chuyện. Tương truyền thời xưa có một chủ nhân xây xong vườn, mời bạn bè đến tham quan. Khách xem một vòng, nói trong vườn cái gì cũng đẹp, chỉ thiếu một chút \"âm thanh\". Chủ nhân nghĩ ngợi rồi trồng mấy cây chuối ngoài cửa sổ. Từ đó, mỗi khi trời mưa, hạt mưa gõ lên những tàu lá rộng phát ra tiếng lanh lảnh, ngồi trong nhà cũng có thể \"nghe\" thấy phong cảnh trong vườn.","Tôi chợt hiểu, vẻ đẹp của lâm viên không chỉ nằm ở những gì mắt nhìn thấy, mà còn ở âm thanh, ánh sáng, mùa màng, thậm chí cả tâm trạng. Mùa xuân ngắm hoa, mùa hạ nghe mưa, mùa thu thưởng trăng, mùa đông xem tuyết; cùng một góc vườn, vào những thời điểm khác nhau lại cho người ta cảm nhận hoàn toàn khác. Người xưa làm vườn, thật ra là đang tạo ra một lối sống — lối sống chậm lại, lắng lại, trò chuyện cùng thiên nhiên.","Buổi sáng cuối cùng trước khi rời Tô Châu, tôi một mình quay lại khu vườn ấy. Hôm đó ít khách, tôi không xem bản đồ, cũng không vội vã, chỉ thong thả đi, thấy ô cửa nào thích thì dừng lại, thấy ghế đá nào vừa ý thì ngồi một lát. Một chú chim đậu trên đầu tường, kêu vài tiếng rồi bay mất; đàn cá trong ao chậm rãi bơi qua bóng một chiếc lá rụng. Một tiếng đồng hồ ấy, tôi dường như chẳng làm gì, nhưng trong lòng lại thấy đầy ắp.","Trở về thành phố, tôi lại quay về những ngày bận rộn thường nhật. Ngày ngày vội vã đuổi theo tàu điện ngầm, họp hành, trả lời tin nhắn, mắt lúc nào cũng dán vào mục tiêu tiếp theo. Nhưng thỉnh thoảng, tôi lại nhớ tới những ô cửa sổ nhỏ trong lâm viên. Có lẽ cuộc sống cũng như lâm viên, phong cảnh đẹp nhất thường không ở điểm cuối, mà ở những nơi ta sẵn lòng dừng bước."],"questions":[{"q":"作者第一次看苏州园林时，为什么感到失望？","q_vi":"Lần đầu xem lâm viên Tô Châu, vì sao tác giả thấy thất vọng?","options":["园林里游客太多了","园林面积不大，看起来都差不多","导游讲解得不好","天气不好，看不清风景"],"answer":1,"explain_vi":"Đoạn 1: diện tích không lớn, khác cung điện tráng lệ trong tưởng tượng, đi chưa đầy một tiếng đã thấy các vườn na ná nhau."},{"q":"什么是“框景”？","q_vi":"\"Khuông cảnh\" (框景) là gì?","options":["把风景画挂在墙上","用竹子做成的画框","通过各种形状的窗户，把外面的风景变成一幅幅画","在园子里修很多走廊"],"answer":2,"explain_vi":"Đoạn 3: cửa sổ đủ hình dạng như khung tranh, \"đóng khung\" phong cảnh bên ngoài thành từng bức tranh."},{"q":"关于“欲扬先抑”，下面哪种理解是正确的？","q_vi":"Về \"欲扬先抑\", cách hiểu nào dưới đây đúng?","options":["先让人看不见美景，再突然展现，给人惊喜","假山越高越好","园林里的路越直越好","先看水，再看山"],"answer":0,"explain_vi":"Đoạn 5: đi qua núi giả lúc tối lúc sáng rồi bất ngờ thấy mặt nước — \"trước không cho thấy, rồi bất chợt cho thấy\"."},{"q":"主人在窗外种芭蕉，是为了什么？","q_vi":"Chủ nhân trồng chuối ngoài cửa sổ để làm gì?","options":["为了挡住阳光","为了吃芭蕉","为了让园子显得更大","为了下雨时能听到雨打叶子的声音"],"answer":3,"explain_vi":"Đoạn 8: khách chê vườn thiếu \"âm thanh\"; trồng chuối để khi mưa, hạt mưa gõ lên lá tạo tiếng lanh lảnh."},{"q":"最后一段作者想表达什么？","q_vi":"Đoạn cuối tác giả muốn bày tỏ điều gì?","options":["城市生活比园林更有意思","生活中也要学会放慢脚步，欣赏过程中的风景","应该多去苏州旅游","工作的目标非常重要"],"answer":1,"explain_vi":"Phong cảnh đẹp nhất không ở điểm cuối mà ở những nơi ta chịu dừng bước — tức nên sống chậm lại, trân trọng quá trình."}],"beyond":[["苏州","Sūzhōu","TÔ CHÂU","Tô Châu"],["不算","bù suàn","BẤT TOÁN","không tính, không coi là, chưa tính là"],["花纹","huāwén","HOA VĂN","hoa văn, họa tiết"],["透过","tòuguò","THẤU QUÁ","xuyên qua, thông qua, nhờ vào"],["有时","yǒushí","HỮU THỜI","có lúc"],["屋顶","wūdǐng","ỐC ĐỈNH","mái nhà, nóc nhà"],["落下","luòxia","LẠC HẠ","rơi xuống, buông xuống, hạ xuống"],["小路","xiǎolù","TIỂU LỘ","đường nhỏ, lối mòn, ngõ hẻm"],["一头","yītóu","NHẤT ĐẦU","cắm đầu, đâm đầu vào; một đầu; một mái đầu"],["水面","shuǐmiàn","THỦY DIỆN","mặt nước"],["柳树","liǔshù","LIỄU THỤ","cây liễu"],["一眼","yīyǎn","NHẤT NHÃN","một cái liếc mắt, một ánh nhìn, một mắt nhìn"],["行走","xíngzǒu","HÀNH TẨU","bước đi, đi lại, hành tẩu (走) · đi, đi lại"],["大片","dàpiàn","ĐẠI PHIẾN","vùng rộng lớn, mảng lớn; phim bom tấn"],["清脆","qīngcuì","THANH THÚY","trong trẻo, lảnh lót, giòn giã"],["古人","gǔrén","CỔ NHÂN","cổ nhân, người xưa · người xưa"],["墙头","qiángtóu","TƯỜNG ĐẦU","đầu tường, mép tường"],["匆匆","cōngcōng","THÔNG THÔNG","vội vã, vội vàng · vội vàng, vội vã"]]},{"id":"h6-05","level":6,"title":"机器会翻译，我们还要学外语吗？","title_vi":"Máy đã biết dịch, chúng ta còn cần học ngoại ngữ không?","topic":"thư từ – giáo dục","chars":1227,"paragraphs":["小安：你好！上周收到你的邮件，我读了好几遍。你说最近心里很乱：手机上的翻译软件越来越厉害，对着菜单拍一张照片，几秒钟就能翻译出来；跟中国人聊天，说一句话，软件马上就能读出译文。你辛辛苦苦背了两年单词、练了两年声调，好像突然变得没有意义了。你问我：在这样的时代，还有必要花那么多时间学一门外语吗？","这个问题，我想很多学外语的人都想过。说实话，我刚开始用这些软件的时候，也吃了一惊。它们的进步确实快得惊人，几年前还错误百出，现在翻译一般的文章已经相当通顺了，有的甚至还能用不同的声音把译文读出来。如果你学外语只是为了看懂路牌、点菜、问路，那么我得承认，软件在很多时候已经可以代替你了。","但是，语言从来不只是一种工具。","我想先给你讲一件小事。几年前，我带学生去中国南方交流，住在一位老奶奶家里。老奶奶不会说普通话，只会说当地的方言，我们听得很吃力。有一天晚上，她拿出一本旧相册，一页一页地给我们讲照片里的人。有一个学生想用翻译软件，可是软件根本听不懂方言。最后，我们就靠着几个简单的词、手势和表情，听她讲了整整一个晚上。那天晚上我们到底听懂了多少，我已经记不清了，可我永远记得，她讲到去世的丈夫时，眼睛里闪着的光。那种交流，是任何机器都无法替代的。","这件事让我明白，人和人之间的交流，靠的不仅是“信息”，还有语气、停顿、表情，以及说话的人愿意为对方付出的那份努力。当你用对方的语言，结结巴巴地说出一句“谢谢”的时候，对方感受到的不只是这两个字的意思，更是你的尊重和诚意。这份心意，是翻译软件传达不了的。","其次，学一门外语，其实是在学习另一种看世界的方式。比如你学汉语时一定发现了，汉语里有很多跟饮食有关的说法：一份工作叫“饭碗”，受欢迎叫“吃香”，生活艰难叫“吃苦”。这些说法背后，是一个民族的生活经验和思维习惯。软件可以把它们翻译成你的母语，但只有你自己真正学过、用过、体会过，才会明白它们为什么这样说，又在什么场合说才最合适。","再说，学外语的过程本身，就是在锻炼大脑。研究表明，长期学习和使用两种以上语言的人，注意力更集中，处理复杂任务的能力也更强。更重要的是，这个过程会培养你的耐心和毅力。你还记得刚开始学声调的时候吗？“妈、麻、马、骂”，你练了整整一个月，急得差点儿哭出来。可是现在，你已经能用汉语给我写一封这么长的邮件了。这种一点一点克服困难的经历，本身就是一笔财富。","当然，我并不是说你应该拒绝翻译软件。恰恰相反，我希望你把它当成一个好帮手。遇到不认识的词，可以查一查；写完一段话，可以让软件帮你检查有没有明显的错误；去一个陌生的地方旅行，它也能帮你解决不少麻烦。不过要记住，软件给出的答案并不总是对的，最后做判断的，还应该是你自己。工具越先进，越应该被聪明地使用，而不是让人变得懒惰。","至于将来，我无法预测技术会发展到什么程度。也许有一天，机器真的能做到完美的翻译。但即便到了那一天，我相信，一个能用对方的语言讲笑话、聊心事、读懂一首诗的人，依然会比一个只会举着手机的人，走得更近，看得更深。","所以，不要因为一时的困惑就放弃。你已经走了两年的路，路上的每一个生词、每一次说错话的尴尬，都在悄悄地改变着你。下次再遇到困难的时候，不妨想想那位老奶奶的相册，想想你第一次用汉语和别人聊上十分钟时的兴奋。","祝学习顺利！期待你明年来中国的时候，我们用汉语好好地聊一聊。你的老师：王明，十一月十四日。"],"pinyin":["xiǎo ān nǐ hǎo shàng zhōu shōu dào nǐ de yóu jiàn wǒ dú le hǎo jǐ biàn nǐ shuō zuì jìn xīn lǐ hěn luàn shǒu jī shàng de fān yì ruǎn jiàn yuè lái yuè lì hài duì zhe cài dān pāi yī zhāng zhào piān jǐ miǎo zhōng jiù néng fān yì chū lái gēn zhōng guó rén liáo tiān shuō yī jù huà ruǎn jiàn mǎ shàng jiù néng dú chū yì wén nǐ xīn xīn kǔ kǔ bèi le liǎng nián dān cí liàn le liǎng nián shēng diào hǎo xiàng tū rán biàn dé méi yǒu yì yì le nǐ wèn wǒ zài zhè yàng de shí dài hái yǒu bì yào huā nà me duō shí jiān xué yī mén wài yǔ ma","zhè ge wèn tí wǒ xiǎng hěn duō xué wài yǔ de rén dōu xiǎng guò shuō shí huà wǒ gāng kāi shǐ yòng zhè xiē ruǎn jiàn de shí hou yě chī le yī jīng tā men de jìn bù què shí kuài dé jīng rén jǐ nián qián hái cuò wù bǎi chū xiàn zài fān yì yì bān de wén zhāng yǐ jīng xiāng dāng tōng shùn le yǒu de shèn zhì hái néng yòng bù tóng de shēng yīn bǎ yì wén dú chū lái rú guǒ nǐ xué wài yǔ zhǐ shì wèi le kàn dǒng lù pái diǎn cài wèn lù nà me wǒ de chéng rèn ruǎn jiàn zài hěn duō shí hou yǐ jīng kě yǐ dài tì nǐ le","dàn shì yǔ yán cóng lái bù zhǐ shì yī zhǒng gōng jù","wǒ xiǎng xiān gěi nǐ jiǎng yī jiàn xiǎo shì jǐ nián qián wǒ dài xué sheng qù zhōng guó nán fāng jiāo liú zhù zài yī wèi lǎo nǎi nai jiā lǐ lǎo nǎi nai bú huì shuō pǔ tōng huà zhǐ huì shuō dāng dì de fāng yán wǒ men tīng dé hěn chī lì yǒu yī tiān wǎn shang tā ná chū yī běn jiù xiàng cè yī yè yī yè de gěi wǒ men jiǎng zhào piān lǐ de rén yǒu yí gè xué sheng xiǎng yòng fān yì ruǎn jiàn kě shì ruǎn jiàn gēn běn tīng bù dǒng fāng yán zuì hòu wǒ men jiù kào zhe jǐ gè jiǎn dān de cí shǒu shì hé biǎo qíng tīng tā jiǎng le zhěng zhěng yí gè wǎn shang nà tiān wǎn shang wǒ men dào dǐ tīng dǒng le duō shǎo wǒ yǐ jīng jì bù qīng le kě wǒ yǒng yuǎn jì de tā jiǎng dào qù shì de zhàng fu shí yǎn jing lǐ shǎn zhe de guāng nà zhǒng jiāo liú shì rèn hé jī qì dōu wú fǎ tì dài de","zhè jiàn shì ràng wǒ míng bai rén hé rén zhī jiān de jiāo liú kào de bù jǐn shì xìn xī hái yǒu yǔ qì tíng dùn biǎo qíng yǐ jí shuō huà de rén yuàn yì wèi duì fāng fù chū de nà fèn nǔ lì dāng nǐ yòng duì fāng de yǔ yán jiē jiē bā bā de shuō chū yī jù xiè xiè de shí hou duì fāng gǎn shòu dào de bù zhǐ shì zhè liǎng gè zì de yì si gèng shì nǐ de zūn zhòng hé chéng yì zhè fèn xīn yì shì fān yì ruǎn jiàn chuán dá bù liǎo de","qí cì xué yī mén wài yǔ qí shí shì zài xué xí lìng yī zhǒng kàn shì jiè de fāng shì bǐ rú nǐ xué hàn yǔ shí yí dìng fā xiàn le hàn yǔ lǐ yǒu hěn duō gēn yǐn shí yǒu guān de shuō fǎ yī fèn gōng zuò jiào fàn wǎn shòu huān yíng jiào chī xiāng shēng huó jiān nán jiào chī kǔ zhè xiē shuō fǎ bèi hòu shì yí gè mín zú de shēng huó jīng yàn hé sī wéi xí guàn ruǎn jiàn kě yǐ bǎ tā men fān yì chéng nǐ de mǔ yǔ dàn zhǐ yǒu nǐ zì jǐ zhēn zhèng xué guò yòng guò tǐ huì guò cái huì míng bai tā men wèi shén me zhè yàng shuō yòu zài shén me chǎng hé shuō cái zuì hé shì","zài shuō xué wài yǔ de guò chéng běn shēn jiù shì zài duàn liàn dà nǎo yán jiū biǎo míng cháng qī xué xí hé shǐ yòng liǎng zhǒng yǐ shàng yǔ yán de rén zhù yì lì gèng jí zhōng chǔ lǐ fù zá rèn wù de néng lì yě gèng qiáng gèng zhòng yào de shì zhè ge guò chéng huì péi yǎng nǐ de nài xīn hé yì lì nǐ hái jì de gāng kāi shǐ xué shēng diào de shí hou ma mā má mǎ mà nǐ liàn le zhěng zhěng yí gè yuè jí dé chà diǎn ér kū chū lái kě shì xiàn zài nǐ yǐ jīng néng yòng hàn yǔ gěi wǒ xiě yī fēng zhè me zhǎng de yóu jiàn le zhè zhǒng yì diǎn yì diǎn kè fú kùn nán de jīng lì běn shēn jiù shì yī bǐ cái fù","dāng rán wǒ bìng bú shì shuō nǐ yīng gāi jù jué fān yì ruǎn jiàn qià qià xiāng fǎn wǒ xī wàng nǐ bǎ tā dàng chéng yí gè hǎo bāng shǒu yù dào bù rèn shi de cí kě yǐ chá yī chá xiě wán yī duàn huà kě yǐ ràng ruǎn jiàn bāng nǐ jiǎn chá yǒu méi yǒu míng xiǎn de cuò wù qù yí gè mò shēng de dì fang lǚ xíng tā yě néng bāng nǐ jiě jué bù shǎo má fan bù guò yào jì zhù ruǎn jiàn gěi chū de dá àn bìng bù zǒng shì duì de zuì hòu zuò pàn duàn de hái yīng gāi shì nǐ zì jǐ gōng jù yuè xiān jìn yuè yīng gāi bèi cōng ming de shǐ yòng ér bú shì ràng rén biàn dé lǎn duò","zhì yú jiāng lái wǒ wú fǎ yù cè jì shù huì fā zhǎn dào shén me chéng dù yě xǔ yǒu yī tiān jī qì zhēn de néng zuò dào wán měi de fān yì dàn jí biàn dào le nà yī tiān wǒ xiāng xìn yí gè néng yòng duì fāng de yǔ yán jiǎng xiào huà liáo xīn shì dú dǒng yī shǒu shī de rén yī rán huì bǐ yí gè zhǐ huì jǔ zhe shǒu jī de rén zǒu de gèng jìn kàn de gēng shēn","suǒ yǐ bú yào yīn wèi yī shí de kùn huò jiù fàng qì nǐ yǐ jīng zǒu le liǎng nián de lù lù shàng de měi yí gè shēng cí měi yī cì shuō cuò huà de gān gà dōu zài qiāo qiāo dì gǎi biàn zhe nǐ xià cì zài yù dào kùn nán de shí hou bù fáng xiǎng xiǎng nà wèi lǎo nǎi nai de xiàng cè xiǎng xiǎng nǐ dì yī cì yòng hàn yǔ hé bié rén liáo shàng shí fēn zhōng shí de xīng fèn","zhù xué xí shùn lì qī dài nǐ míng nián lái zhōng guó de shí hou wǒ men yòng hàn yǔ hǎo hǎo dì liáo yī liáo nǐ de lǎo shī wáng míng shí yī yuè shí sì rì"],"translations":["An thân mến! Tuần trước nhận được email của em, thầy đã đọc đi đọc lại mấy lần. Em nói dạo này trong lòng rối bời: phần mềm dịch trên điện thoại ngày càng giỏi, chụp thực đơn một tấm là vài giây đã dịch xong; nói chuyện với người Trung Quốc, nói một câu là phần mềm đọc ngay bản dịch. Em vất vả học thuộc từ vựng hai năm, luyện thanh điệu hai năm, bỗng dưng như trở nên vô nghĩa. Em hỏi thầy: trong thời đại như thế này, có còn cần bỏ nhiều thời gian như vậy để học một ngoại ngữ không?","Câu hỏi này, thầy nghĩ nhiều người học ngoại ngữ đều từng nghĩ tới. Nói thật, khi mới dùng những phần mềm này, thầy cũng giật mình. Chúng tiến bộ nhanh thật đáng kinh ngạc, mấy năm trước còn đầy lỗi, giờ dịch những bài viết thông thường đã khá trôi chảy, có phần mềm thậm chí còn đọc được bản dịch bằng nhiều giọng khác nhau. Nếu em học ngoại ngữ chỉ để đọc biển chỉ đường, gọi món, hỏi đường, thì thầy phải thừa nhận, nhiều lúc phần mềm đã có thể thay em rồi.","Nhưng ngôn ngữ chưa bao giờ chỉ là một công cụ.","Thầy muốn kể em nghe một chuyện nhỏ trước. Mấy năm trước, thầy dẫn sinh viên sang miền Nam Trung Quốc giao lưu, ở nhà một bà cụ. Bà không biết tiếng phổ thông, chỉ nói tiếng địa phương, chúng tôi nghe rất vất vả. Một tối nọ, bà lấy ra một cuốn album cũ, lật từng trang kể cho chúng tôi về những người trong ảnh. Có một sinh viên định dùng phần mềm dịch, nhưng phần mềm hoàn toàn không hiểu tiếng địa phương. Cuối cùng, chúng tôi chỉ dựa vào vài từ đơn giản, cử chỉ và nét mặt mà nghe bà kể suốt cả buổi tối. Tối hôm ấy rốt cuộc chúng tôi hiểu được bao nhiêu, thầy không còn nhớ rõ, nhưng thầy mãi nhớ ánh sáng lấp lánh trong mắt bà khi kể về người chồng đã khuất. Kiểu giao tiếp ấy, không cỗ máy nào thay thế được.","Chuyện đó giúp thầy hiểu rằng, giao tiếp giữa người với người không chỉ dựa vào \"thông tin\", mà còn có giọng điệu, những quãng ngừng, nét mặt, cùng với nỗ lực mà người nói sẵn lòng bỏ ra vì người kia. Khi em dùng ngôn ngữ của đối phương, ấp úng nói một câu \"cảm ơn\", điều người ta cảm nhận không chỉ là nghĩa của hai chữ ấy, mà còn là sự tôn trọng và chân thành của em. Tấm lòng ấy, phần mềm dịch không truyền tải được.","Thứ hai, học một ngoại ngữ thật ra là học một cách nhìn thế giới khác. Chẳng hạn khi học tiếng Hán, chắc em đã nhận ra tiếng Hán có rất nhiều cách nói liên quan đến ăn uống: một công việc gọi là \"bát cơm\", được ưa chuộng gọi là \"ăn thơm\", sống gian khổ gọi là \"ăn khổ\". Đằng sau những cách nói này là kinh nghiệm sống và thói quen tư duy của cả một dân tộc. Phần mềm có thể dịch chúng sang tiếng mẹ đẻ của em, nhưng chỉ khi tự em thật sự học, dùng và cảm nhận, em mới hiểu vì sao người ta nói như vậy, và nói trong hoàn cảnh nào là hợp nhất.","Hơn nữa, bản thân quá trình học ngoại ngữ là đang rèn luyện bộ não. Nghiên cứu cho thấy những người lâu dài học và dùng từ hai ngôn ngữ trở lên tập trung tốt hơn, khả năng xử lý nhiệm vụ phức tạp cũng mạnh hơn. Quan trọng hơn, quá trình ấy rèn cho em sự kiên nhẫn và bền bỉ. Em còn nhớ lúc mới học thanh điệu không? \"Mā, má, mǎ, mà\", em luyện tròn một tháng, sốt ruột đến suýt khóc. Vậy mà giờ em đã có thể viết cho thầy một email dài thế này bằng tiếng Hán. Trải nghiệm vượt qua khó khăn từng chút một như thế, bản thân nó đã là một tài sản.","Tất nhiên, thầy không nói em nên từ chối phần mềm dịch. Ngược lại hoàn toàn, thầy mong em coi nó là một trợ thủ đắc lực. Gặp từ không biết thì tra; viết xong một đoạn thì nhờ phần mềm kiểm tra xem có lỗi rõ ràng nào không; đi du lịch đến nơi xa lạ, nó cũng giúp em giải quyết không ít phiền phức. Có điều phải nhớ, đáp án phần mềm đưa ra không phải lúc nào cũng đúng, người đưa ra phán đoán cuối cùng vẫn nên là chính em. Công cụ càng tiên tiến thì càng nên được dùng một cách thông minh, chứ không phải khiến con người trở nên lười biếng.","Còn về tương lai, thầy không thể dự đoán công nghệ sẽ phát triển đến mức nào. Có lẽ một ngày nào đó, máy móc thật sự dịch được hoàn hảo. Nhưng dù đến ngày ấy, thầy tin rằng một người có thể dùng ngôn ngữ của đối phương để kể chuyện cười, tâm sự, đọc hiểu một bài thơ, vẫn sẽ đi gần hơn và nhìn sâu hơn so với một người chỉ biết giơ điện thoại lên.","Vì vậy, đừng vì băn khoăn nhất thời mà bỏ cuộc. Em đã đi được hai năm đường, mỗi từ mới trên con đường ấy, mỗi lần ngượng ngùng vì nói sai, đều đang lặng lẽ thay đổi em. Lần tới gặp khó khăn, em thử nghĩ đến cuốn album của bà cụ, nghĩ đến niềm hào hứng lần đầu tiên em nói chuyện được mười phút với người khác bằng tiếng Hán.","Chúc em học tập thuận lợi! Mong năm sau khi em sang Trung Quốc, thầy trò mình sẽ trò chuyện thật thoải mái bằng tiếng Hán. Thầy của em: Vương Minh, ngày 14 tháng 11."],"questions":[{"q":"小安为什么给老师写信？","q_vi":"Vì sao An viết thư cho thầy?","options":["她想请老师帮她找工作","她觉得翻译软件很厉害，怀疑学外语还有没有意义","她的翻译软件坏了","她想去中国南方旅行"],"answer":1,"explain_vi":"Đoạn 1: phần mềm dịch ngày càng giỏi khiến An thấy hai năm học như vô nghĩa, nên hỏi có còn cần học ngoại ngữ không."},{"q":"老师讲老奶奶的故事，想说明什么？","q_vi":"Thầy kể chuyện bà cụ để nói lên điều gì?","options":["方言比普通话难学","老人都喜欢看旧照片","真正的人与人之间的交流，机器无法替代","出国交流一定要带翻译软件"],"answer":2,"explain_vi":"Đoạn 4: dù phần mềm không hiểu tiếng địa phương, họ vẫn giao tiếp bằng từ ngữ đơn giản, cử chỉ, nét mặt — \"không cỗ máy nào thay thế được\"."},{"q":"第六段举“饭碗”“吃香”等例子，是为了说明：","q_vi":"Đoạn 6 đưa ví dụ \"饭碗\", \"吃香\" là để nói lên:","options":["学外语也是在了解另一种看世界的方式","中国人特别喜欢吃饭","这些词翻译软件翻译不出来","学汉语应该先学饮食方面的词"],"answer":0,"explain_vi":"Câu chủ đề đoạn 6: học ngoại ngữ là học một cách nhìn thế giới khác; sau các cách nói ấy là kinh nghiệm sống và tư duy của một dân tộc."},{"q":"老师对翻译软件的态度是什么？","q_vi":"Thái độ của thầy đối với phần mềm dịch là gì?","options":["坚决反对使用","认为它会完全代替人","认为它一点儿用也没有","可以把它当成帮手，但要聪明地使用"],"answer":3,"explain_vi":"Đoạn 8: thầy không bảo từ chối phần mềm, mà mong An coi nó là trợ thủ, dùng thông minh chứ đừng để nó khiến mình lười."},{"q":"根据全文，下面哪一项不是老师提到的学外语的好处？","q_vi":"Theo toàn bài, điều nào dưới đây KHÔNG phải lợi ích của việc học ngoại ngữ mà thầy nhắc đến?","options":["能表达对别人的尊重和诚意","能锻炼大脑，培养耐心和毅力","一定能找到收入更高的工作","能了解另一个民族的思维习惯"],"answer":2,"explain_vi":"Thầy nhắc đến sự tôn trọng (đoạn 5), cách nhìn thế giới (đoạn 6), rèn luyện não bộ và sự bền bỉ (đoạn 7); không hề nói đến thu nhập cao hơn."}],"beyond":[["通顺","tōngshùn","THÔNG THUẬN","trôi chảy, lưu loát, thông suốt (văn phong)"],["结结巴巴","jiējiebābā","KẾT KẾT BA BA","ấp úng, nói lắp (nói chuyện không lưu loát)"],["诚意","chéngyì","THÀNH Ý","thiện chí, lòng thành, thành ý"],["心意","xīnyì","TÂM Ý","tấm lòng, thành ý, tâm ý"],["饭碗","fànwǎn","PHẠN OẢN","bát cơm; chén cơm manh áo, kế sinh nhai"],["恰恰相反","qiàqià xiāngfǎn","KHÁP KHÁP TƯƠNG PHẢN","hoàn toàn ngược lại, trái lại hẳn"],["帮手","bāngshǒu","BANG THỦ","người giúp đỡ, trợ thủ · người giúp việc, người phụ tá"],["心事","xīnshì","TÂM SỰ","tâm sự, chuyện bận lòng · tâm sự, nỗi niềm trong lòng, điều trăn trở"],["困惑","kùnhuò","KHỐN HOẶC","lúng túng (không hiểu, không chắc chắn) · băn khoăn, bối rối"]]}]};
